-- Sources: data/i18n/frFR. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_frFR")
P.entries["zone:razorfenkraul"] = {n="Kraal de Tranchebauge",s="Niché à l'extrême sud des Tarides, le Kraal de Tranchebauge est le cœur ancestral des hurans de Kalimdor. Ces tribus féroces vénèrent ce dense labyrinthe de ronces géantes comme le lieu de repos sacré de leur progéniteur, le demi-dieu déchu Agamaggan. Aujourd'hui, le Kraal est devenu agressivement hostile sous la tyrannie de la matriarche hurane Charlga Trancheflanc, dont les sombres agissements menacent toute la région.",h="Niché à l'extrême sud des Tarides, le Kraal de Tranchebauge est le cœur ancestral des hurans de Kalimdor.",kw={"agamaggan","les tarides","charlga","halmgar","kraal","huran","ramtusk","tranchebauge","trancheflanc","fléau"},ang={["class:Shaman"]="La géomancie des hurans altère la terre et les éléments autour du sang d'Agamaggan, offrant une démonstration saisissante de pouvoirs chamaniques ancestraux maniés avec des intentions sauvages.",["faction:Horde"]="Neutraliser l'agressivité qui règne au sein du Kraal est indispensable pour protéger les convois de ravitaillement et les campements naissants à travers les étendues méridionales des Tarides.",["race:Tauren"]="Les hurans contestent les frontières de Mulgore depuis bien longtemps, et leur profanation de la terre par le biais de sombres alliances fait de la purification du Kraal un enjeu vital pour la défense tribale.",["race:Undead"]="Les apothicaires de Fossoyeuse manifestent un vif intérêt pour les réactifs étranges, le guano de chauve-souris et les rumeurs d'incursions du Fléau observées au cœur des ronces."},sec={{t="Le sang du Dieu Sanglier",b="Il y a dix mille ans, au cours de la guerre apocalyptique des Anciens, le colossal dieu sauvage Agamaggan se jeta dans la bataille contre la Légion ardente. Le grand sanglier finit par succomber au combat, mais son sacrifice préserva la vie sur Azeroth. La légende raconte que partout où son sang s'est infiltré dans la terre, de gigantesques lianes épineuses ont jailli, formant d'épais labyrinthes défensifs à travers les plaines du sud. Les hurans, vénérant Agamaggan comme leur ancêtre divin, revendiquèrent ces fourrés colossaux comme leurs terres sacrées, faisant du plus vaste d'entre eux Tranchebauge."},{t="L'ambition de la matrone",b="Le Kraal de Tranchebauge est dirigé d'une défense de fer par l'Ancienne Charlga Trancheflanc. Sous sa tutelle despotique, les hurans chamaniques ont abandonné leurs escarmouches territoriales traditionnelles pour mener une guerre agressive et concertée contre les tribus rivales, les routes commerciales régionales et les jeunes colonies de la Horde. Pire encore, de troublantes rumeurs et des rapports d'éclaireurs font état de créatures mortes-vivantes rôdant près des ronces. On craint que Charlga n'ait commencé à négocier avec des émissaires de la redoutable Fléau, cherchant à exploiter la nécromancie interdite pour décupler la sauvagerie de sa tribu."}},faq={{q="Qu'est-ce que le Kraal de Tranchebauge ?",a="Le Kraal de Tranchebauge est un ancien réseau souterrain de lianes épineuses géantes situé dans les Tarides du sud. Il sert de foyer spirituel et de bastion à la race des hurans, qui considèrent ce dédale inextricable comme leur foyer ancestral.",al={"qu'est-ce que le kraal","explications kraal de tranchebauge","aperçu de tranchebauge"}},{q="Comment les épines géantes sont-elles apparues ?",a="Ces énormes ronces ont jailli du sol il y a dix mille ans, pendant la guerre des Anciens, nées directement du sang versé par le demi-dieu sanglier déchu Agamaggan.",al={"pourquoi y a-t-il des épines géantes","d'où viennent les ronces","épines d'agamaggan"}},{q="Qui dirige le Kraal de Tranchebauge ?",a="Le Kraal est dirigé par Charlga Trancheflanc, une matrone et chamane hurane impitoyable qui commande la tribu Tranchebauge et organise des attaques contre les villages voisins et les voyageurs.",al={"qui est le boss du kraal","charlga trancheflanc","matrone du kraal"}},{q="Pourquoi la Horde s'inquiète-t-elle pour le Kraal de Tranchebauge ?",a="En plus des assauts constants des hurans contre les colonies naissantes des Tarides, les éclaireurs de la Horde ont repéré des morts-vivants rôdant autour des fourrés, faisant naître la terrifiante crainte que Charlga ne s'allie avec le Fléau.",al={"pourquoi la horde s'y intéresse","intérêt de la horde pour le kraal","menace des tarides"}},{q="Pourquoi les forces de l'Alliance s'intéressent-elles au Kraal ?",a="L'expansion agressive de la tribu de Charlga menace les avant-postes situés près de Féralas et des Mille pointes, poussant les commandants et éclaireurs de l'Alliance basés à Thalanaar à chercher la mort de la matrone afin de sécuriser la frontière.",al={"quêtes alliance kraal","pourquoi l'alliance va là-bas","quête de thalanaar"}},{q="Que signifie la défaite de l'Appelle-terre Halmgar dans l'histoire ?",a="Terrasser l'Appelle-terre Halmgar, un géomancien rare et influent tapi au cœur des fourrés, porte un coup sévère au clergé des sculpteurs de terre hurans. Priver le Kraal d'invocateurs élémentaires aussi puissants désorganise les fortifications défensives de Charlga Trancheflanc et entrave la capacité des hurans à manipuler les ronces sacrées d'Agamaggan.",al={"que se passe-t-il après la mort de l'appelle-terre halmgar","histoire de l'appelle-terre halmgar","halmgar vaincu"}}},fx={a384c7af={q="Qui est Amnennar ?",a="Amnennar le Porte-froid est un puissant agent du Fléau qui a pris ses quartiers dans les Souilles de Tranchebauge voisines. Agissant dans l'ombre, il manipule les chefs quilboars et commande les forces de la Tête de mort pour transformer les ronces du sud en un bastion de morts-vivants.",al={"qui est amnennar","amnennar le porte-froid","lore d'amnennar"}},af015f4e={q="Comment me suis-je retrouvé dans le Kraal de Tranchebauge ?",a="Vous avez voyagé jusqu'aux confins sud des Tarides, près des hautes falaises surplombant les Mille pointes. En progressant à travers les broussailles disputées, vous avez découvert l'immense fourré de ronces nourries par le sang qui a jailli du cadavre de l'ancien dieu sanglier Agamaggan. Creusée directement dans ces immenses vignes d'épines pétrifiées se trouve l'entrée ouest du Kraal, où les défenseurs quilboars gardent les accès contre quiconque ose s'aventurer sur leur territoire sacré.",al={"comment suis-je arrivé ici","comment atteindre le kraal de tranchebauge","où se trouve le kraal de tranchebauge"}},["141f6ea5"]={q="Que suis-je censé faire dans le Kraal de Tranchebauge ?",a="Vous êtes ici pour briser la puissance hostile de la tribu de Tranchebauge et stopper leur expansion agressive à travers les Tarides. Sous la direction de leur vieille, Charlga Trancheflanc, ces quilboars fanatiques ont intensifié leurs assauts violents contre les colonies et les caravanes voisines. Votre objectif est de vous frayer un chemin à travers les passages de ronces tortueux, de briser le commandement de la Tête de mort et d'abattre Charlga avant que sa sombre géomancie et ses tractations suspectes avec de sinistres forces mortes-vivantes ne déclenchent une guerre totale.",al={"quelle est ma mission ici","pourquoi suis-je dans le kraal de tranchebauge","que fais-je ici"}},["59c8bcc4"]={q="Qui a fait pousser toutes ces épines dans le Kraal de Tranchebauge ?",a="Personne ne les a construites à la main. Il y a dix mille ans, durant la Guerre des Anciens, le colossal demi-dieu sanglier Agamaggan tomba en combattant la Légion ardente. Là où son sang divin a imprégné le sol, des ronces massives et impénétrables ont jailli de la terre, formant le fourré labyrinthique que vous voyez aujourd'hui.",al={"qui a créé les épines","qui a fait pousser les épines","origine des épines du kraal"}},["4843f165"]={q="Qu'est-ce que les Huran ?",a="Les Huran sont des humanoïdes primitifs et agressifs ressemblant à des sangliers, originaires de Kalimdor. Ils ont un dos musclé et voûté hérissé de piquants défensifs acérés. Considérés comme la progéniture mortelle du demi-dieu Agamaggan, ils vénèrent ses lieux de repos et défendent farouchement leurs territoires épineux contre tout étranger.",al={"que sont les huran","qui sont les huran","histoire des huran"}},ea4583b3={q="Pourquoi les Huran vivent-ils dans un labyrinthe d'épines géant ?",a="Le labyrinthe d'épines a germé directement du sang de leur dieu déchu, Agamaggan. Pour les Huran, Tranchebauge est une terre sacrée et son véritable lieu de repos. Les ronces leur offrent à la fois une vénération sacrée et des forteresses naturelles presque impénétrables contre leurs ennemis régionaux.",al={"pourquoi vivre dans les épines","pourquoi les huran vivent-ils ici","labyrinthe d'épines huran"}},b1fd1d2b={q="Charlga Trancheflanc est-elle la chef de tous les Huran ?",a="Pas de tous les Huran, mais elle dirige la puissante tribu de Tranchebauge retranchée au sein du Kraal. C'est une vieille femme rusée et géomancienne qui a chassé les taurens locaux des Tarides du sud et exerce une autorité étendue, bien que les tribus Huran rivales dispersées à travers Kalimdor se gouvernent indépendamment.",al={"chef charlga trancheflanc","qui dirige tous les huran","charlga est-elle en charge de tous"}},["8ed48c28"]={q="Qui est Agathelos le Déchaîné ?",a="Agathelos est un sanglier massif et féroce qui habite au sein du Kraal de Tranchebauge. Les Huran vénèrent les sangliers comme des symboles vivants de leur dieu Agamaggan, voyant les bêtes particulièrement grandes et tenaces comme Agathelos comme des bénédictions directes et des manifestations sacrées du pouvoir primal du Grand Sanglier.",al={"qui est agathelos","histoire d'agathelos le déchaîné","agathelos sanglier géant"}},["4f663063"]={q="La Horde fourre-t-elle aussi son nez dans le Kraal de Tranchebauge ?",a="Oui. Les pillards de Charlga Trancheflanc mènent continuellement des assauts brutaux sur les colonies de la Horde à travers les Tarides et ont chassé les taurens de leurs terres ancestrales du sud. Les orcs comme les taurens envoient activement des guerriers pour briser le pouvoir de la vieille femme et mettre fin à la menace Huran.",al={"la horde est-elle ici","présence de la horde à tranchebauge","horde au kraal de tranchebauge"}},["5328604f"]={q="Qui est Agamaggan ?",a="Agamaggan, le Grand Sanglier, était un Gardien ancien et l'un des premiers et plus puissants Dieux sauvages à fouler Azeroth. En le vénérant comme leur créateur, les Huran célèbrent sa mémoire, puisant une puissance spirituelle et géomantique de son sang et des vastes amas d'épines nés de son sacrifice.",al={"qui est agamaggan","agamaggan le grand sanglier","histoire d'agamaggan"}},bc4e6730={q="Agamaggan est-il mort durant la Guerre des Anciens ?",a="Oui. Il y a dix mille ans, Agamaggan a répondu à l'appel de Cénarius pour défendre Azeroth contre la Légion ardente. Il a ravagé le continent, écrasant des milliers de démons avant de finalement tomber au combat face à des légions démoniaques écrasantes, sacrifiant sa vie pour que Malfurion Hurlorage puisse atteindre le Puits d'éternité.",al={"comment agamaggan est-il mort","agamaggan guerre des anciens","agamaggan est-il mort"}},e47b7687={q="Les Huran vénèrent-ils toujours Agamaggan ?",a="Ils le font, avec une dévotion fanatique. Les chamans et géomanciens Huran prient Agamaggan pour obtenir de la force au combat, vénèrent les sangliers géants comme étant ses bénédictions, et accumulent les Éclats de sang formés à partir de son sang pétrifié. Ils croient que ses restes physiques les protègent, eux et leur foyer sacré.",al={"les huran vénèrent-ils toujours agamaggan","religion des huran","culte d'agamaggan"}},["7583b13a"]={q="Qui sont les gars de la Tête de mort ?",a="La Tête de mort est une faction Huran militante dirigée sur le champ de bataille par le seigneur Brusquebroche, opérant aux côtés de la tribu de Tranchebauge. Brusquebroche dirige ses troupes disciplinées et aguerries au combat pour maintenir une mainmise sur le labyrinthe d'épines et mener des guerres vicieuses contre leurs voisins.",al={"tribu de la tête de mort","qui sont ceux de la tête de mort","huran de la tête de mort"}},["4bc36485"]={q="Les Huran d'ici vont-ils attaquer les colonies des Tarides ?",a="C'est déjà le cas. Sous le commandement de la vieille femme Charlga Trancheflanc, des groupes de pillards agressifs balayent constamment les terres environnantes depuis les épines. Ils ont harcelé les voyageurs près de la Grande élévation, agressé des tribus rivales et poussé les colonies et caravanes de la Horde au bord d'une guerre ouverte.",al={"les huran vont-ils attaquer les tarides","attaque huran sur les tarides","raids huran dans les tarides"}},ed4c33ec={q="Quelle est la différence entre le Kraal et les Souilles ?",a="Tous deux sont des réseaux d'épines massifs engendrés par la chute d'Agamaggan, mais ils servent des rôles différents. Le Kraal de Tranchebauge est le cœur ancestral où Charlga Trancheflanc rassemble des pillards Huran vivants. Les Souilles de Tranchebauge, situées plus au sud-est près de la gueule squelettique massive du demi-dieu, sont tombées sous l'influence plus sombre du Fléau.",al={"différence entre le kraal et les souilles","kraal de tranchebauge contre souilles","kraal ou souilles"}},["974f5634"]={q="Le Fléau est-il impliqué dans Tranchebauge ?",a="Oui. Des rapports troublants et des missives capturées révèlent que Charlga Trancheflanc a commencé à négocier avec des agents du Fléau. Des éclaireurs ont aperçu des morts-vivants empiétant près de Tranchebauge, soulevant de graves préoccupations quant au fait que les sbires du roi-liche cherchent à prendre pied sur Kalimdor par le biais de ces tribus insoupçonnées.",al={"le fléau dans tranchebauge","y a-t-il des morts-vivants dans tranchebauge","présence du fléau au kraal"}}},fp="14,218,21.427.0,20.423.1,23.142.0,34.156.0,25.170.0,48.182.0,48.157.0,59.248.0"}
P.entries["zone:redridge"] = {n="Les Carmines",s="À l'est de la Forêt d’Elwynn, Les Carmines se caractérisent par des rivières tumultueuses, des pentes boisées et l'étendue sereine du Lac placide. Malgré ses hauteurs pittoresques, la région est assiégée par les gnolls Shadowhide hostiles et l'avancée des orcs Rochenoire de la Horde noire. L'armée du royaume étant accaparée par les dissensions internes à Hurlevent, la ville riveraine de Comté-du-Lac doit s'en remettre à des mercenaires itinérants pour tenir la ligne.",h="À l'est de la Forêt d’Elwynn, Les Carmines se caractérisent par des rivières tumultueuses, des pentes boisées...",kw={"orcs blackrock","lac placide","comté-du-lac","magistrat salomon","maréchal marris","les carmines","vallée des etripeurs","shadowhide","guet-de-pierre","donjon de guet-de-pierre","verner bongoulot"},ang={["faction:Alliance"]="Comté-du-Lac sert de centre de première ligne crucial pour les jeunes soldats de l'Alliance qui affûtent leurs compétences face aux forces organisées des orcs et des gnolls.",["faction:Horde"]="Les orcs Rochenoire retranchés dans Les Carmines appartiennent à la Horde noire hostile, ce qui en fait les ennemis de la Horde de Thrall tout autant que des humains de Comté-du-Lac.",["profession:Herbalism"]="Les pentes montagneuses tempérées favorisent une pousse régulière d'Eglantine, de Doulourante, de Mage royal et de Chardonnier.",["profession:Mining"]="Les crêtes rocheuses et les vallées entourant le Lac placide offrent d'abondants affleurements de cuivre, d'étain et de rares filons d'argent, en particulier près des Cavernes de Rethban."},sec={{t="Un bastion assiégé",b="La chaîne des Carmines comptait autrefois parmi les régions les plus paisibles du royaume, approvisionnant Hurlevent en bois d'œuvre, en poissons d'eau douce et en récoltes. Aujourd'hui, cette vie paisible s'est effondrée. La commune riveraine de Comté-du-Lac demeure perpétuellement fortifiée contre de violentes incursions. À l'est, le Donjon de Guet-de-pierre — jadis un fier bastion du royaume — est tombé sous le contrôle d'orcs Rochenoire renégats, coupant les routes et menaçant d'envahir totalement les vallées orientales."},{t="La chaîne divisée",b="Sur le plan géographique, ces sommets font partie de la colonne vertébrale qui traverse le sous-continent d'Azeroth. Il y a plusieurs siècles, la chaîne de montagnes s'étendait bien plus au nord, jusqu'à ce que le clan Dark Iron n'invoque par mégarde Ragnaros le seigneur du Feu, déchirant la terre et créant le cratère ardent du Mont Rochenoire. Ce cataclysme a séparé les sommets du nord pour former les Steppes Ardentes étouffées par les cendres, ne laissant que les vallées méridionales des Carmines luxuriantes, verdoyantes et vulnérables aux attaques venues des hauteurs."},{t="Négligée par la Couronne",b="Tandis que le Magistrat Salomon et le Maréchal Marris implorent des renforts, le conseil de régence de Hurlevent a de fait abandonné Comté-du-Lac à son propre sort. Les suppliques désespérées envoyées à la Colline des Sentinelles et à Sombre-Comté ne donnent rien, ces deux colonies sœurs étant paralysées par leurs propres crises. Sans le moindre renfort en vue, les magistrats locaux doivent engager tout mercenaire compétent prêt à braver la Grand-route de la Crête du lac, à nettoyer les camps de gnolls et à repousser l'ombre qui plane sur le Lac placide."},{t="Les allégeances cachées",b="Le Démoniste renégat Morganth s'est d'abord allié aux orcs Rochenoire pour s'emparer du Donjon de Guet-de-pierre, avant de les trahir et d'asservir les gnolls Shadowhide depuis la Tour d'Ilgalar. Des rapports récupérés au cours de l'enquête sur les Rochenoire révèlent également une alliance entre les orcs et le Vol draconique noir."}},faq={{q="Pourquoi Hurlevent n'envoie-t-il pas de soldats pour aider Comté-du-Lac ?",a="Les soldats royaux survivants de Comté-du-Lac sont largement inférieurs en nombre après la perte du Donjon de Guet-de-pierre. Le Magistrat Salomon a réclamé des troupes, des armes, des vivres et des fournitures, mais les forces de Hurlevent sont dispersées et les colonies voisines ont leurs propres soucis. La garnison s'en remet donc aux aventuriers pour l'aider à tenir la région.",al={"pourquoi aucun garde de hurlevent","pourquoi les carmines sont abandonnees","ou est l armee de hurlevent"}},{q="Qui contrôle le Donjon de Guet-de-pierre ?",a="Le Donjon de Guet-de-pierre a été envahi par des orcs Rochenoire affiliés à la Horde noire. Depuis cette place forte montagnarde fortifiée, ils menacent les vallées orientales et circulent le long de la Grand-route de la Crête du lac. Leurs relations avec les autres menaces locales sont explorées au fil de l'enquête.",al={"qui se trouve a guet-de-pierre","ennemis de guet-de-pierre","qu est-il arrive a guet-de-pierre"}},{q="Quelles menaces peuplent le Lac placide ?",a="Bien que tranquilles depuis la rive, les eaux du Lac placide sont infestées de tribus de murlocs hostiles qui attaquent les quais et les ruines à proximité. Les nageurs doivent également faire face à des prédateurs battus, les threshadons tapis sous la surface, alimentant des rumeurs persistantes de monstres aquatiques rôdant dans les profondeurs.",al={"monstres du lac placide","dangers du lac des carmines","murlocs du lac placide"}},{q="Y a-t-il des avant-postes de la Horde dans Les Carmines ?",a="Non. Les Carmines ne contiennent aucun campement, marchand ou maître de vol de la Horde. Les voyageurs de la Horde qui traversent la région transitent généralement entre les Steppes Ardentes au nord et le Marais des Chagrins au sud-est, devant emprunter des routes tenues par l'Alliance et une nature sauvage hostile.",al={"villes de la horde les carmines","les carmines horde ou alliance","maitre de vol de la horde les carmines"}},{q="Que sont les Trois chemins ?",a="Les Trois chemins forment une croisée vitale dans le coin sud-ouest des Carmines. Cet endroit relie la Grand-route de la Crête du lac à la frontière orientale de la Forêt d’Elwynn et à la route vers le Bois de la Pénombre, ce qui en fait un carrefour de transit essentiel fréquemment ciblé par les gnolls errants et les bêtes sauvages.",al={"trois chemins","croisee des trois chemins","intersection des carmines"}},{q="Pourquoi le sentier nord menant aux Steppes Ardentes est-il si périlleux ?",a="Le sentier qui part vers le nord après le camp de Render grimpe directement vers les Steppes Ardentes, une désolation volcanique dominée par de puissants orcs Rochenoire, des élémentaires de feu et des drakônides. Ce brusque accroissement du danger fait du col de montagne septentrional l'une des ascensions géographiques les plus meurtrières du sud d'Azeroth.",al={"route nord des carmines","frontiere des steppes ardentes les carmines","col nord des carmines"}}},fx={["85c0e73f"]={q="Qu'est-ce que les Carmines ?",a="Les Carmines sont une région montagneuse et pittoresque située à l'est de la Forêt d’Elwynn et au sud des Steppes Ardentes. Connue pour ses rivières tumultueuses, ses ormes imposants et le lac placide aux eaux scintillantes, elle fut longtemps considérée comme l'une des terres les plus paisibles du sud d'Azeroth. Aujourd'hui, sa beauté tranquille est brisée par l'invasion des orcs de Rochenoire, de violents gnolls et des murlocs hostiles du lac.",al={"qu'est-ce que les carmines","zone des carmines","parle-moi des carmines"}},["5d244582"]={q="Les Carmines font-elles partie du royaume de Hurlevent ?",a="Oui, les Carmines sont sous la protection et le domaine du royaume de Hurlevent, bien que depuis la Seconde Guerre, leurs dirigeants locaux gèrent largement les affaires courantes de manière indépendante. Le magistrat Salomon de Comté-du-Lac continue d'adresser formellement des pétitions au trône de Hurlevent pour sa défense, s'appuyant sur le commerce de l'Alliance et une loyauté mutuelle, même lorsque les troupes royales sont absentes.",al={"les carmines appartiennent-elles à hurlevent","les carmines sont-elles alliance","comté-du-lac fait-il partie de hurlevent"}},["8563150d"]={q="Pourquoi y a-t-il un lac au milieu des Carmines ?",a="Le Lac placide recueille naturellement les eaux de drainage des chaînes de montagnes environnantes. Ses eaux claires et sereines assuraient autrefois la subsistance de Comté-du-Lac grâce à une pêche abondante et de l'eau pure, bien qu'elles aient été récemment envahies par des tribus vicieuses de murlocs et traquées par des battoirs rôdant sous la surface.",al={"pourquoi le lac placide","origine du lac des carmines","qu'est-ce que le lac dans les carmines"}},["8de34bfa"]={q="Que s'est-il passé dans les Carmines ?",a="Les Carmines étaient autrefois un havre de fermes humaines paisibles jusqu'à la Première Guerre, lorsque le chef de guerre Main-Noire et les démonistes du Conseil des ombres ont vaincu les chevaliers de Sir Anduin Lothar et poussé les humains à l'exil. Reclamée et reconstruite par l'Alliance après la Seconde Guerre, la région est récemment retombée sous le coup d'un siège après que les orcs de Rochenoire ont poussé depuis les montagnes pour s'emparer du Donjon de Guet-de-pierre.",al={"histoire des carmines","que s'est-il passé dans les carmines","première guerre des carmines"}},bf444872={q="Les Carmines sont-elles dangereuses ?",a="Malgré leur apparence idyllique, les Carmines sont extraordinairement périlleuses. Les orcs de Rochenoire contrôlent les canyons orientaux et le donjon, les gnolls de la Griffe-d'ombre pillent les bois et les murlocs pullulent sur les rives du lac. Même la route du nord borde les sommets brûlants des Steppes Ardentes, où des menaces monstrueuses, bien supérieures à une patrouille moyenne, rôdent juste au-delà des cols de la vallée.",al={"les carmines sont-elles sûres","niveau de danger des carmines","à quel point les carmines sont-elles dangereuses"}},["1cc45818"]={q="Pourquoi tout le monde est-il si inquiet à Comté-du-Lac ?",a="Comté-du-Lac est en état de siège actif. Les orcs de Rochenoire ont capturé le Donjon de Guet-de-pierre juste de l'autre côté du lac, les gnolls de la Griffe-d'ombre pressent la ville depuis les collines et les murlocs infestent les voies navigables. Avec le pont brisé et l'absence de renforts venus de Hurlevent, les habitants craignent qu'un assaut total ne les anéantisse à tout moment.",al={"pourquoi comté-du-lac a-t-il peur","menace sur comté-du-lac","pourquoi s'inquiéter à comté-du-lac"}},["851f5e81"]={q="Comté-du-Lac est-il sur le point de tomber ?",a="Sans intervention extérieure, la position de Comté-du-Lac est sombre. La garde locale est largement dépassée en nombre par les pillards orcs, les meutes de gnolls et les monstres du lac. Leur forteresse de Guet-de-pierre a été facilement envahie et les défenseurs de Comté-du-Lac ont été repoussés jusqu'à la rive ouest du lac, maintenant à peine un périmètre le long du pont brisé.",al={"comté-du-lac va-t-il tomber","comté-du-lac est-il condamné","comté-du-lac peut-il survivre"}},["7ced12b0"]={q="Hurlevent a-t-il envoyé de l'aide à Comté-du-Lac ?",a="Comté-du-Lac a fait appel à Hurlevent, à la Marche de l’Ouest et à Sombre-Comté pour obtenir de l'aide, mais les colonies voisines sont absorbées par leurs propres crises. Le général Marcus Jonathan a également été sollicité pour des renforts. Les soldats royaux qui défendent encore Comté-du-Lac manquent toujours de troupes et de fournitures après la chute du Donjon de Guet-de-pierre.",al={"hurlevent a-t-il aidé comté-du-lac","aide de hurlevent pour comté-du-lac","hurlevent a-t-il envoyé des troupes dans les carmines"}},["3a3ab87f"]={q="Qui est aux commandes ici ?",a="Comté-du-Lac est gouverné par le magistrat Salomon, qui supervise les affaires civiles et municipales depuis l'Hôtel de ville de Comté-du-Lac. Les opérations militaires et de défense incombent au maréchal Marris, qui dirige la garde locale et coordonne les efforts défensifs près du pont.",al={"qui dirige les carmines","qui gouverne comté-du-lac","dirigeants des carmines"}},["1dd15680"]={q="Qui est le magistrat Salomon ?",a="Le magistrat Salomon est le dirigeant élu de Comté-du-Lac et juge en chef de la cour de Comté-du-Lac. Vieillissant et épuisé, il porte le fardeau de maintenir la ville nourrie, organisée et politiquement liée au royaume, tout en adressant désespérément des pétitions aux dirigeants étrangers et régionaux pour obtenir un soutien militaire.",al={"magistrat salomon","qui est salomon","salomon des carmines"}},["0e63cf14"]={q="Le maréchal Marris rend-il des comptes au magistrat Salomon ?",a="Oui. Salomon représente l'autorité civile et la cour du royaume à Comté-du-Lac, tandis que le maréchal Marris commande le détachement de la garde de Hurlevent qui y est stationné. Les deux travaillent en étroite collaboration, Salomon gérant la survie diplomatique et municipale tandis que Marris s'occupe des escarmouches tactiques et du déploiement des troupes.",al={"marris répond-il à salomon","rang du maréchal marris et salomon","qui est le supérieur à comté-du-lac"}},["7b7fd7c0"]={q="Qui sont les orcs de Rochenoire et pourquoi sont-ils dans les Carmines ?",a="Le clan Rochenoire est un reste impitoyable de la Vieille Horde basé dans le Mont Rochenoire au nord. Contrairement à la Horde de Thrall en Kalimdor, ces renégats rejettent toute paix avec l'Alliance. Ils sont descendus des Steppes Ardentes dans les Carmines pour conquérir la région, utilisant le Donjon de Guet-de-pierre comme base pour écraser Comté-du-Lac.",al={"orcs de blackrock dans les carmines","pourquoi des orcs dans les carmines","qui est le clan blackrock des carmines"}},["114fb915"]={q="D'où viennent les orcs de Rochenoire ?",a="Ils ont marché vers le sud en traversant les cols escarpés des montagnes du nord, venant directement des Steppes Ardentes et du Pic Rochenoire, leur ancienne forteresse de la Seconde Guerre. Ils ont installé des avant-postes comme le camp de Render avant de submerger le Donjon de Guet-de-pierre.",al={"d'où viennent les orcs des carmines","origine des orcs de blackrock","d'où viennent les orcs"}},["9f02e3ae"]={q="Les orcs de Rochenoire sont-ils les mêmes orcs que ceux des guerres ?",a="Oui. Ce sont des vétérans endurcis et des descendants directs du clan Rochenoire de la Première et de la Seconde Guerre qui ont refusé de se rendre ou de suivre la nouvelle voie chamanique de Thrall. Ils conservent leurs pratiques sanguinaires originales et leur magie noire, restant attachés à leur mission originelle d'extinction des royaumes humains.",al={"les orcs de blackrock viennent-ils de la première guerre","orcs de blackrock de la seconde guerre","sont-ce les mêmes orcs des anciennes guerres"}},["09fb7c4a"]={q="Que sont les gnolls des Carmines ? Pourquoi attaquent-ils ?",a="Les gnolls de la Griffe-d'ombre locaux sont des humanoïdes sauvages ressemblant à des hyènes qui habitent les collines et les vallées des Carmines. Bien qu'ils soient naturellement territoriaux et prédateurs, leur violence actuelle et coordonnée est guidée par des influences obscures qui ont unifié leurs meutes dispersées en une armée organisée déterminée à massacrer les colonies humaines.",al={"gnolls des carmines","pourquoi les gnolls attaquent-ils les carmines","gnolls de la griffe-d'ombre"}},ba7471d2={q="Les gnolls travaillent-ils avec les orcs ?",a="Les gnolls de la Griffe-d'ombre servent le démoniste renégat Morganth dans la Tour d'Ilgalar. Leur relation avec les orcs de Rochenoire peut être étudiée grâce aux rapports récupérés dans la région.",al={"gnolls et orcs alliés","les gnolls travaillent-ils pour blackrock","les orcs et les gnolls font-ils équipe"}},["74e139ea"]={q="Qui est Yowler ?",a="Yowler est le chef des gnolls des Carmines. Résidant dans les collines au-dessus de Comté-du-Lac, il rallie la meute contre la ville. Verner Bongoulot demande aux aventuriers de le vaincre et de rapporter sa patte.",al={"qui est yowler","yowler chef gnoll","yowler des carmines"}},b25dfaa0={q="Pourquoi le The Everstill Bridge est-il brisé et pourquoi est-ce important ?",a="Le The Everstill Bridge est lourdement endommagé. C'est une question cruciale car il enjambe l'étroit du Lac placide, servant de principal axe de transport pour Comté-du-Lac vers la rive orientale et le Guet-de-pierre. Sa destruction entrave le commerce et la défense de la ville, tout en compliquant toute contre-attaque contre les campements ennemis.",al={"pont the everstill bridge cassé","pourquoi pont cassé comté-du-lac","pont cassé les carmines"}},b35f81a4={q="Pourquoi Hurlevent n'a-t-elle pas réparé le The Everstill Bridge ?",a="Hurlevent n'a envoyé aucun financement, ravitaillement ou maçon pour aider. La responsabilité repose entièrement sur les travailleurs locaux dirigés par le Contremaître Oslow, dont les efforts de réparation sont constamment interrompus et sabotés par des raids de murlocs et des pertes de ravitaillement.",al={"pourquoi pont pas réparé","réparation pont comté-du-lac hurlevent","qui répare le pont"}},["834d2ea2"]={q="Pourquoi y a-t-il des dragonnets du vol noir dans Les Carmines ?",a="Des dragonnets du vol noir ont déferlé à travers les cols depuis les Steppes Ardentes, infestant la Grand-route de la Crête du lac et les canyons du sud. Ils rôdent sur les crêtes rocheuses pour explorer le territoire et s'en prendre aux passants, servant d'avertissement inquiétant que la couvée de Deathwing est active à proximité.",al={"dragonnets dans les carmines","dragons noirs les carmines","pourquoi dragonnets les carmines"}},ce7dd1a7={q="Les dragons travaillent-ils avec les orcs ?",a="La présence grandissante du clan Rochenoire et les signalements de dragonnets du vol noir alarment Comté-du-Lac. Le Magistrat Salomon demande aux voyageurs de faire part de ses inquiétudes au Généralissime Bolvar Fordragon. Une enquête plus approfondie révèle la nature de la menace.",al={"dragons noirs alliés à blackrock","alliance orcs et dragons","orcs blackrock et dragons"}},["7d7bd3f8"]={q="Pourquoi est-ce qu'un aventurier fait tout le travail ici au lieu des gardes ?",a="Les gardes de Comté-du-Lac sont totalement occupés à défendre le périmètre de la ville, ne laissant personne de disponible pour des sorties offensives. Les renforts demandés étant toujours indisponibles, le Magistrat Salomon et le Maréchal Marris n'ont d'autre choix que d'engager des aventuriers de passage pour repousser les orcs, éliminer les gnolls et sécuriser la grand-route.",al={"pourquoi je fais ça les carmines","pourquoi aventuriers les carmines","où sont les gardes les carmines"}},["839c7682"]={q="Où est l'armée de Hurlevent ?",a="Les forces de Hurlevent sont dispersées. Des soldats royaux sont restés à Comté-du-Lac après leur défaite au Donjon de Guet-de-pierre, mais les demandes répétées de la ville pour obtenir des troupes fraîches et des ravitaillements n'ont pas apporté les renforts dont ses défenseurs ont besoin.",al={"où sont les soldats de hurlevent","pourquoi pas d'armée de hurlevent","emplacement armée hurlevent"}},de572e98={q="Comment ai-je fini dans Les Carmines ?",a="Vous avez probablement suivi les routes vers l'est depuis la Forêt d’Elwynn en passant par le carrefour de Trois chemins, ou avez traversé la rivière depuis les bois sombres du Bois de la Pénombre au sud-ouest. En tant que jeune champion aidant les terres des Humains, vos voyages vous mènent naturellement ici une fois que les troubles périphériques autour de Hurlevent nécessitent des mains plus robustes. Les appels à l'aide de Comté-du-Lac atteignent les territoires voisins, attirant les aventuriers itinérants le long de la Grand-route de la Crête du lac vers ces hauteurs en conflit.",al={"comment suis-je arrivé ici","comment atteindre les carmines","pourquoi je suis venu dans les carmines"}},d1ce2561={q="Que suis-je censé faire dans Les Carmines ?",a="Comté-du-Lac est dans une situation désespérée et pratiquement abandonnée par la couronne. Vous êtes ici pour répondre aux appels à l'aide du Magistrat Salomon et du Maréchal Marris. La ville est durement pressée par les gnolls Shadowhide qui saccagent les routes et les féroces orcs du clan Rochenoire qui se sont emparés du Donjon de Guet-de-pierre. Avec une garnison royale en infériorité numérique et le The Everstill Bridge brisé, vous devez repousser les gnolls, refouler l'avant-garde orque et empêcher ce paisible refuge lacustre de s'effondrer complètement.",al={"que fais-je ici","pourquoi je suis ici","quel est mon but dans les carmines","quelle est ma mission ici"}}},fp="18,271,21.379.0,17.453.0,22.430.0,22.309.1,52.324.0,29.235.0,37.186.0,41.258.0,26.229.0,60.279.0"}
P.entries["zone:riverglades"] = {n="Rives Claires",s="Les Rives Claires sont une vallée fluviale disputée à l'est des Steppes ardentes et des Terres ingrates, historiquement revendiquée par le royaume de Hurlevent. Envahie par l'Ancienne Horde durant la Première guerre et largement abandonnée par la couronne, la région demeure un champ de bataille où les loyalistes humains locaux affrontent les avant-postes de la Horde moderne et la faune locale. Elle borde Les Carmines au sud-ouest, le Marais des Chagrins au sud, et fait face à Tanaris de l'autre côté de la mer.",h="Les Rives Claires sont une vallée fluviale disputée à l'est des Steppes ardentes et des Terres ingrates...",kw={"défilé des rochenoires","confrérie du cheval","demar brant","donjon de fort-lointain","bastion krol’dok","port de poudremèche","défilé des carmines","rives claires","rog’mar","clairsoleil"},ang={["faction:Alliance"]="Les soldats de l'Alliance voient de vieilles blessures se rouvrir dans les Rives Claires, où les vestiges de la Confrérie du cheval poursuivent une croisade méconnue pour reprendre des terres abandonnées par Hurlevent lors de la Première guerre.",["faction:Horde"]="Pour la Horde, l'établissement d'avant-postes comme Rog’mar garantit un point d'ancrage côtier sûr et maintient la pression sur les anciens bastions humains qui subsistent à l'est des Carmines.",["race:Human"]="Les voyageurs humains contemplent un chapitre tragique de leur propre histoire à Clairsoleil, rappel du lourd tribut payé lors de la Première guerre sur la frontière orientale de leur royaume."},sec={{t="Une marche frontalière oubliée",b="Faisant historiquement partie du royaume de Hurlevent, les Rives Claires tombèrent en ruine durant la Première guerre lorsque l'Ancienne Horde déferla sur la région. Sa colonie centrale, Clairsoleil, fut mise à sac par les orcs, qui n'épargnèrent sa tour des mages que pour étudier la sorcellerie humaine avant de réduire en esclavage les villageois survivants. Bien que les soldats de Hurlevent aient déployé des efforts pour libérer les captifs et reconstruire, le royaume finit par considérer toute la vallée comme perdue et détourna ses ressources vers la défense de ses terres d'origine. Pendant des années, la région resta largement coupée de tout soutien officiel de la couronne."},{t="La lutte pour Fort-Lointain",b="Bien qu'abandonnés par les hauts dirigeants de Hurlevent, les défenseurs humains ne cédèrent jamais totalement leur patrie. Sous les ordres du commandant de chevalerie Demar Brant de la légendaire Confrérie du cheval, les loyalistes restants tiennent le Donjon de Fort-Lointain comme un bastion contre la nature sauvage et les envahisseurs hostiles. Dans le même temps, la Horde moderne maintient une forte présence à proximité dans des avant-postes tels que Rog’mar et Bolder’ok, veillant à ce que l'ancien conflit pour les clairières continue de couver."},{t="Géographie et voies de passage",b="S'étirant le long de la côte de la mer Interdite, les Rives Claires sont bordées d'un relief montagneux et de cours d'eau sinueux. Les voyageurs à pied peuvent traverser à l'ouest par le Défilé des Rochenoires vers les Steppes ardentes, serpenter au sud-ouest par le Défilé des Carmines en direction des Carmines, naviguer vers le sud jusqu'au Marais des Chagrins, ou cheminer au nord-ouest au-delà du Suaire du Crépuscule vers les Terres ingrates. Sur la côte, le Port de Poudremèche propose une traversée maritime menant directement par-delà l'océan au Port Gentepression à Tanaris."}},faq={{q="Que sont les Rives Claires ?",a="Les Rives Claires sont une région disputée située à l'est des Terres ingrates et des Steppes ardentes, faisant face à la mer Interdite. Autrefois territoire florissant de Hurlevent, c'est aujourd'hui une frontière active disputée entre l'Alliance au Donjon de Fort-Lointain et la Horde à Rog’mar.",al={"aperçu des rives claires","qu'est-ce que cette zone","à propos des rives claires"}},{q="Qu'est-il arrivé à Clairsoleil ?",a="Clairsoleil a été attaquée et détruite par l'Ancienne Horde au cours de la Première guerre. Les orcs ont capturé les villageois survivants pour en faire des esclaves et ont préservé la tour des mages locale afin de déchiffrer la magie humaine. Bien que les soldats de Hurlevent aient libéré les captifs et tenté de reconstruire, le royaume a fini par abandonner la région pour se concentrer sur ses frontières occidentales.",al={"histoire de clairsoleil","chute de clairsoleil","qu'est-il arrivé à la ville"}},{q="Qui contrôle le Donjon de Fort-Lointain ?",a="Le Donjon de Fort-Lointain est tenu par des loyalistes de l'Alliance menés par le commandant de chevalerie Demar Brant de la Confrérie du cheval. Ses forces ont passé des années à se battre pour reconquérir les Rives Claires après que Hurlevent a initialement considéré le territoire comme perdu.",al={"qui dirige fort-lointain","l'alliance aux rives claires","confrérie du cheval"}},{q="Comment se rendre à Tanaris depuis les Rives Claires ?",a="Un bateau côtier assure des liaisons régulières entre le Port de Poudremèche sur la rive est des Rives Claires et le Port Gentepression à Tanaris, offrant une traversée maritime directe à travers les flots.",al={"bateau pour tanaris","bateau du port de poudremèche","comment aller à tanaris"}},{q="Quels cols mènent aux autres zones ?",a="Vous pouvez voyager vers le sud-ouest à travers le Défilé des Carmines pour rejoindre Les Carmines, ou vous diriger directement au sud vers le Marais des Chagrins. À l'ouest, le Défilé des Rochenoires mène au-delà des Collines Hirsutes vers les Steppes ardentes, tandis que les sentiers au nord du Suaire du Crépuscule mènent directement aux Terres ingrates.",al={"comment aller aux carmines","cols depuis les rives claires","sorties des rives claires"}},{q="Qu'est-ce que le Bastion Krol’dok ?",a="Le Bastion Krol’dok est un complexe de donjon fortifié situé dans les Rives Claires, constituant un foyer de puissance hostile majeur au sein de ce territoire disputé.",al={"bastion krol'dok","donjon des rives claires","quel donjon se trouve ici"}}},fp="11,291,22.431.0,25.415.0,20.414.0,24.187.0,28.295.0,27.212.0,46.146.0,34.266.0,28.127.0"}
P.entries["zone:ruinsoflordaeron"] = {n="Ruines de Lordaeron",s="Perchées directement au-dessus de Fossoyeuse la souterraine, les Ruines de Lordaeron sont les vestiges désolés du puissant royaume septentrional de l'humanité d'autrefois. Tombées aux mains du Fléau et du prince Arthas au cours de la Troisième guerre, les rues de la surface et les places fissurées grouillent désormais de monstruosités errantes, de spectres vengeurs et de vils expérimentateurs. L'Alliance comme la Horde dépêchent des expéditions dans cette citadelle flétrie pour récupérer les reliques d'un passé déchu ou purger les horreurs qui rôdent au-dessus de la capitale des Réprouvés.",h="Perchées directement au-dessus de Fossoyeuse la souterraine, les Ruines de Lordaeron sont les vestiges...",kw={"bjork","lordaeron captain","nouvelle peste","rath'mael","ruines de lordaeron","the abandoned","the baron","clairières de tirisfal","fossoyeuse","viktor the vile","witherfang"},ang={["class:Paladin"]="Lordaeron fut le berceau des chevaliers de la Main d'argent ; arpenter ses salles profanées pour purger les horreurs et offrir le repos aux capitaines tourmentés est un devoir solennel de la Lumière.",["faction:Alliance"]="S'aventurer en Lordaeron permet à l'Alliance de frapper aux portes de la capitale des Réprouvés tout en apportant justice et paix aux esprits de leurs frères massacrés du nord.",["race:Human"]="Les aventuriers humains considèrent la capitale en ruine comme une terre sacrée dérobée par la trahison, et cherchent à récupérer les reliques perdues tout en honorant leurs proches disparus.",["race:Undead"]="Pour les Réprouvés, les ruines supérieures représentent leur ancien foyer et leur cimetière éternel. Les nettoyer permet de sécuriser leur entrée et d'approvisionner les apothicaires en composants pour développer la Nouvelle Peste."},sec={{t="La cour d'un empire déchu",b="Capital City était autrefois le joyau des Royaumes de l'est, le siège du roi Terenas Menethil II et le cœur battant de la civilisation humaine. Lorsque le prince Arthas est revenu du Norfendre, il a assassiné son père dans la salle du trône et a déchaîné les morts-vivants sur la population. Aujourd'hui, tandis que les Réprouvés résident dans les catacombes de Fossoyeuse en contrebas, les ruines de la surface demeurent une zone crépusculaire à l'abandon. Les arches brisées et les pavés envahis de mauvaises herbes abritent des bêtes sauvages telles que Witherfang et des reliques démentes du passé."},{t="Tourment et pestilence",b="Les périls qui guettent dans ces terres en ruine dépassent les simples morts sans repos. Des apothicaires et de sinistres individus comme Viktor the Vile s'affairent à tester de nouvelles pestes dans l'ombre, tandis que des créations corrompues telles que The Abandoned errent librement. Des esprits courroucés comme Rath'mael et des serviteurs maudits tels que The Baron hantent les couloirs effondrés, prisonniers d'un tourment sans fin et s'en prenant à tout intrus, vivant ou mort-vivant, qui croise leur route."},{t="Les fantômes de la garde royale",b="Parmi les dangers les plus poignants des ruines supérieures figurent les vestiges spectraux des défenseurs de la cité, culminant avec l'apparition d'un Lordaeron Captain fantomatique. Toujours fidèles à leurs serments brisés, ces apparitions perçoivent quiconque s'approche du trône comme un envahisseur. Accorder le repos au Captain et à ses soldats apporte un dénouement teinté d'amertume à une veille ininterrompue qui dure depuis le jour où la capitale est tombée."}},faq={{q="Où se trouve le donjon des Ruines de Lordaeron ?",a="Le donjon est situé directement à la surface de Capital City dans les Clairières de Tirisfal, juste au-dessus du réseau d'accès descendant vers la capitale des Réprouvés, Fossoyeuse.",al={"emplacement ruines de lordaeron","où se trouve donjon lordaeron","entrée donjon fossoyeuse"}},{q="Pourquoi la Horde et l'Alliance s'intéressent-elles à cet endroit ?",a="Pour l'Alliance, s'aventurer en Lordaeron est un pèlerinage sacré afin de retrouver des héritages familiaux perdus, de rassembler des blasons royaux et d'accorder le repos éternel aux ancêtres défunts. Pour la Horde, en particulier les Réprouvés, nettoyer les ruines supérieures est essentiel pour sécuriser le périmètre de Fossoyeuse et obtenir des échantillons de recherche pour la nouvelle peste de la Société royale des apothicaires.",al={"pourquoi aller aux ruines de lordaeron","quêtes alliance lordaeron","quêtes horde lordaeron"}},{q="Qui est Viktor the Vile ?",a="Viktor the Vile est l'une des figures malveillantes qui profitent de l'anarchie des ruines pour mener de viles expériences et alimenter la corruption purulente qui maintient la capitale supérieure infestée d'abominations perverties.",al={"histoire viktor the vile","qui est viktor the vile"}},{q="Qu'est-ce que « The Abandoned » rencontré dans les ruines ?",a="The Abandoned est une grotesque monstruosité morte-vivante laissée à l'abandon dans les ruines. À l'instar de nombreuses horreurs rapiécées créées pendant et après la conquête du Fléau, il déambule sans but dans les salles délabrées, attaquant tout ce qu'il croise.",al={"the abandoned boss","qui est the abandoned"}},{q="Que signifie la défaite du Lordaeron Captain pour l'histoire ?",a="Vaincre le Lordaeron Captain spectral libère un défenseur royal de haut rang d'un devoir perpétuel et rendu fou par le temps. Lié par l'honneur depuis le massacre initial du Fléau, le Captain a passé des années à protéger un royaume détruit contre tous ceux qui s'en approchaient. Accorder le repos au Captain brise un cycle atroce de servitude fantomatique et permet de récupérer son Insigne ensanglanté.",al={"vaincre lordaeron captain","importance lordaeron captain","mort du capitaine lordaeron"}},{q="Les Ruines de Lordaeron sont-elles séparées de Fossoyeuse ?",a="Oui. Alors que les Réprouvés ont élu domicile dans les cavernes de Fossoyeuse en dessous, les ruines de la surface constituent une zone de combat active envahie de fantômes agités, de prédateurs féroces et de menaces expérimentales que les Réprouvés n'ont pas totalement éradiqués.",al={"fossoyeuse est-elle dans ce donjon","ruines contre fossoyeuse"}}},fx={f7d23701={q="Arthas est-il toujours en vie, et pourrai-je un jour le combattre ?",a="Arthas n'est pas mort au sens mortel du terme, mais a été totalement corrompu pour devenir un chevalier de la mort, champion du Fléau. Il se trouve loin de l'autre côté de la mer, en Norfendre, hors de portée de quiconque en Lordaeron. Votre combat actuel se livre contre les menaces qui rôdent ici : les commandants locaux du Fléau, la Croisade écarlate et les bêtes sauvages qui infestent ces ruines.",al={"puis-je combattre arthas","arthas est-il en vie","allons-nous affronter arthas"}},["9fc2648e"]={q="Est-il le roi Liche maintenant ?",a="Des murmures venant du nord prétendent qu'Arthas a gravi la flèche de la Couronne de glace pour délivrer le roi Liche du siège d'Illidan, brisant la glace pour s'emparer du Heaume de domination et fusionner son âme avec celle de Ner'zhul. Pour le monde en général, l'état exact du Norfendre reste enveloppé d'un mystère glacial, mais sa sombre présence plane sur tous les morts-vivants.",al={"arthas est-il le roi liche","arthas est-il devenu roi liche","identité de roi liche d'arthas"}},["89a21402"]={q="Comment ai-je fini dans les Ruines de Lordaeron ?",a="Vous avez franchi les portes extérieures en ruine de la capitale déchue dans les Clairières de Tirisfal, juste au-dessus des ascenseurs qui descendent vers Fossoyeuse. Que vous ayez répondu à un appel militaire, poursuivi des rumeurs d'horreurs incontrôlées s'accrochant au cadavre du royaume, ou que vous vous soyez faufilé à travers un territoire hostile pour récupérer des vestiges sacrés du passé, votre voyage vous a conduit dans les cours scellées et disputées où les ombres du Fléau et les fantômes de l'ancienne humanité rôdent encore.",al={"comment suis-je arrivé ici","comment ai-je fini ici","pourquoi suis-je dans les ruines de lordaeron","comment suis-je arrivé jusqu'ici"}},bb4abd7f={q="Que suis-je censé faire dans les Ruines de Lordaeron ?",a="Vous êtes ici pour purger les horreurs qui festeront dans les ruines de surface au-dessus de la capitale des Réprouvés. Pour la Horde, cela signifie traquer les bêtes sauvages du Fléau, récupérer des insignes perdus et tester des concoctions mortelles pour la Société royale des apothicaires. Pour l'Alliance, il s'agit d'une frappe clandestine visant à purifier des terres ancestrales, récupérer des héritages sacrés comme le Crest of Lordaeron et apporter du réconfort aux fantômes errants et tourmentés qui n'ont pas trouvé la paix.",al={"que fais-je ici","quelle est ma mission ici","que dois-je faire dans les ruines","quel est mon objectif ici"}},["6b51523d"]={q="Que s'est-il passé dans cette salle du trône en haut des escaliers ?",a="La salle du trône a été le théâtre de la trahison catastrophique qui a mis fin au royaume. Le prince Arthas, tout juste revenu du Norfendre, est entré dans cette salle en passant devant des citoyens qui l'acclamaient au son des cloches. Alors que son père, le roi Terenas, se levait de son trône pour l'accueillir, Arthas a tiré Deuillegivre, a proclamé qu'il succédait à son père et a plongé la lame runique maudite dans le cœur du vieux roi.",al={"que s'est-il passé dans la salle du trône","histoire de la salle du trône de lordaeron","histoire de la salle du trône"}},["6e83c082"]={q="Est-ce l'endroit où Terenas a été tué ?",a="Oui. Si vous vous tenez juste devant la estrade brisée, vous êtes sur les dalles mêmes où le roi Terenas Menethil II a rendu son dernier souffle. Une faible tache sombre reste visible sur le sol en pierre, que l'on dit être le sang du vieux roi qui s'est imprégné dans la maçonnerie lorsque son fils l'a abattu. Même aujourd'hui, des murmures spectraux et des cloches résonnent faiblement dans la chambre.",al={"où terenas a-t-il été tué","est-ce le sang de terenas","endroit où le roi terenas est mort"}},ea8d978d={q="Qu'est-il advenu de la couronne de Terenas ?",a="La couronne d'or de Terenas est tombée au sol lorsque Arthas l'a assassiné dans la salle du trône. Sa chute marque la fin de son règne et la catastrophe qui s'est abattue sur Lordaeron.",al={"pourquoi la couronne est-elle au sol","couronne du roi terenas ruines","sang sur la couronne de terenas"}},bb044bc8={q="Les Réprouvés font-ils vraiment partie de la Horde ?",a="Oui, bien qu'il s'agisse en grande partie d'un pacte de survie mutuelle. Entourés par la Croisade écarlate, des Humains hostiles et les restes du Fléau, les Réprouvés ont envoyé des ambassadeurs par-delà les mers pour chercher des alliés. La Horde, ayant besoin d'un point d'ancrage dans les Royaumes de l'est pour contrer l'Alliance, a accepté de leur accorder l'entrée, offrant aux Réprouvés le soutien militaire et le statut international dont ils avaient cruellement besoin.",al={"réprouvés horde alliance","les morts-vivants sont-ils dans la horde","pourquoi les réprouvés sont-ils dans la horde"}},["50000697"]={q="Pourquoi Thrall a-t-il accepté les Morts-vivants au sein de la Horde ?",a="Thrall a été convaincu principalement par l'intercession de l'archidruide Hamuul Runetotem et des Taurens, qui pensaient que les Réprouvés étaient des victimes tragiques qui pourraient un jour trouver la rédemption ou un remède à leur affliction. De plus, Thrall a reconnu la nécessité stratégique d'une place forte établie dans les Royaumes de l'est pour empêcher l'Alliance de dominer le continent nord sans opposition.",al={"pourquoi thrall a-t-il accepté les morts-vivants","raison de thrall pour les réprouvés","pourquoi la horde a accepté les réprouvés"}},["9af0f393"]={q="Les Orcs et les Taurens leur font-ils confiance ?",a="Pas entièrement. Bien que les Taurens les considèrent avec une profonde pitié et espèrent guérir leur condition, de nombreux Orcs nourrissent de profonds doutes concernant la magie noire, la nécromancie et la nature sinistre de Fossoyeuse. Thrall surveille de près les actions de Sylvanas, et les ambassadeurs postés se méfient de ce qui se prépare au sein des laboratoires de la Société royale des apothicaires.",al={"les orcs font-ils confiance aux réprouvés","confiance des taurens envers les réprouvés","la horde fait-elle confiance aux morts-vivants"}},["849f698a"]={q="Est-il prudent que je me tienne ici ?",a="Cela dépend entièrement de vos allégeances. Si vous combattez pour la Horde, les Réprouvés et leurs abominations vous reconnaissent comme un allié, bien que les ombres au-dessus abritent des créatures errantes et des esprits persistants. Si vous marchez sous la bannière de l'Alliance, vous êtes en plein territoire ennemi ; les sentinelles réprouvées et les gardes de l'effroi vous abattront à vue.",al={"les ruines de lordaeron sont-elles sûres","suis-je en sécurité ici","danger de se tenir à lordaeron"}},aac358a1={q="Les gardes vont-ils m'attaquer ?",a="Les gardes de la mort réprouvés et les abominations royales postés autour des ruines ignoreront ou protégeront les voyageurs de la Horde, mais ils sont brutalement hostiles envers les champions de l'Alliance. De plus, des renégats et des monstres hostiles rôdent dans les couloirs isolés et les ailes de donjon des ruines au-dessus, et ils attaqueront quiconque croise leur chemin, quelle que soit son allégeance.",al={"les gardes de fossoyeuse vont-ils attaquer","les gardes des ruines sont-ils hostiles","les gardes m'attaquent-ils"}},e9ec8c01={q="Reste-t-il des membres du Fléau dans les environs ?",a="Oui. Bien que Sylvanas ait balayé la majorité du Fléau hors de la Capitale, le Fléau reste fortement retranché juste au-delà des frontières dans les Maleterres de l’Ouest. Même dans les recoins les plus sombres et les sous-niveaux oubliés de ces ruines, des Morts-vivants sans esprit et des restes du Fléau subsistent encore, attendant de déchiqueter toute chair vivante qui s'aventure trop loin.",al={"le fléau dans les ruines de lordaeron","le fléau est-il proche de fossoyeuse","y a-t-il du fléau à proximité"}},["0a975308"]={q="De quelle peste tout le monde parle-t-il ?",a="Ils parlent de la Peste de la non-mort, une horrible contagion bio-magique développée par le roi-liche et ses nécromanciens. Distribuée à travers Lordaeron par le biais de céréales infectées par le Culte des damnés, elle tuait quiconque les consommait en quelques heures et réanimait immédiatement leurs cadavres en tant que serviteurs obéissants et pourrissants du Fléau.",al={"qu'est-ce que la peste de la non-mort","de quelle peste parle-t-on","peste de lordaeron"}},["290f94a8"]={q="Qui a créé la peste originale ?",a="La peste originale a été conçue par les seigneurs de l'effroi de la Légion ardente et perfectionnée par le roi-liche, Ner'zhul, alors qu'il était emprisonné au sommet du Trône de glace en Norfendre. Pour la libérer sur Lordaeron, il a enrôlé l'archimage renégat de Dalaran, Kel'Thuzad, qui a fondé le Culte des damnés et a corrompu les stocks de céréales.",al={"qui a créé la peste de la non-mort","créateur de la peste originale","qui a créé la peste"}},["89f62638"]={q="Sylvanas en fabrique-t-elle une nouvelle ?",a="Oui. Dame Sylvanas a chargé la Société royale des apothicaires de concocter une « nouvelle peste ». Son objectif est de créer une arme biologique suffisamment puissante pour anéantir à la fois le Fléau et les vivants, assurant ainsi la survie des Réprouvés et la vengeance contre Arthas. Leurs tests secrets ont lieu en ce moment même dans l'Apothicarium ci-dessous.",al={"sylvanas crée-t-elle une peste","nouvelle peste des réprouvés","nouvelle peste de fossoyeuse"}},dcb566d2={q="Qui est le roi-liche et que veut-il ?",a="Le roi-liche est le souverain suprême du Fléau, créé à partir de l'esprit torturé du chaman orc Ner'zhul enfermé dans la glace au sommet du Trône de glace. Son objectif était d'affaiblir Azeroth pour la Légion ardente, mais il nourrissait ses propres ambitions terrifiantes : éradiquer toute vie mortelle et la remplacer par un empire éternel et unifié de non-mort sous son commandement mental absolu.",al={"qui est le roi-liche","que veut le roi-liche","motivations du roi-liche"}},["3a9893a7"]={q="Où se trouve le roi-liche maintenant ?",a="Il règne depuis le Trône de glace au sommet du glacier de la Couronne de glace sur le continent lointain et gelé du Norfendre. Suite à l'assaut d'Illidan qui a fissuré sa prison glacée, le roi-liche a rappelé Arthas au Norfendre pour fusionner leurs esprits et préserver son pouvoir, loin du royaume brisé de Lordaeron.",al={"où est le roi-liche","emplacement du roi-liche","où est le trône de glace"}},["0138c577"]={q="Contrôle-t-il toujours les Réprouvés ?",a="Non. Lorsque le Trône de glace a été fissuré par la magie d'Illidan, l'emprise télépathique du roi-liche a commencé à se briser. Sylvanas et de nombreux autres Morts-vivants ont retrouvé leur libre arbitre et se sont détachés de son esprit collectif. Bien qu'il cherche à les récupérer, les Réprouvés résistent désormais violemment à ses murmures et se battent farouchement pour maintenir leur autonomie.",al={"le roi-liche contrôle-t-il les réprouvés","le roi-liche peut-il commander les réprouvés","libre arbitre des réprouvés"}},["6a523c60"]={q="Qui est la Croisade écarlate et pourquoi haïssent-ils les Morts-vivants ?",a="La Croisade écarlate est un ordre de fanatiques religieux humains formé à partir des restes brisés de la Main d'argent et des chevaliers de Lordaeron. Traumatisés par la peste qui a détruit leur patrie, ils sont consumés par la paranoïa. À leurs yeux, tous les Morts-vivants sont des abominations sans exception, et tout vivant qui s'associe à eux est considéré comme corrompu et marqué pour l'exécution.",al={"qui est la croisade écarlate","pourquoi la croisade écarlate hait les morts-vivants","histoire de la croisade écarlate"}},b59db3a3={q="Sont-ils les mêmes que l'Aube d'argent ?",a="Non, ce sont des rivaux acharnés aux racines communes. Tous deux sont nés des cendres des Chevaliers de la Main d'argent, mais lorsque la Croisade écarlate a succombé à un fanatisme aveugle et à la xénophobie, des paladins modérés se sont séparés pour former l'Aube d'argent. L'Aube accueille toutes les races et se concentre sur la défense de la terre contre le Fléau plutôt que sur des purges indiscriminées.",al={"croisade écarlate contre aube d'argent","la croisade écarlate et l'aube d'argent sont-elles les mêmes","différence entre la croisade écarlate et l'aube"}},ca88b6f6={q="Attaquent-ils aussi les joueurs vivants ?",a="Oui. La Croisade écarlate croit que quiconque n'est pas vêtu de leur tabard cramoisi héberge secrètement la peste ou collabore avec les Morts-vivants. Que vous soyez un Orc, un Tauren, un Elfe de la nuit ou un soldat humain de Hurlevent, leurs fanatiques vous traiteront de porteur de corruption et vous attaqueront à vue.",al={"la croisade écarlate attaque-t-elle l'alliance","les écarlates attaquent-ils les vivants","croisade écarlate hostile aux vivants"}},["861c7602"]={q="Que fait la Société royale des apothicaires là-dessous ?",a="Opérant depuis l'Apothicarium de Fossoyeuse, cette sinistre guilde d'alchimistes réprouvés et d'anciens mages travaille sans relâche selon le décret de Dame Sylvanas. Leur mandat principal est de développer une « nouvelle peste » catastrophique capable d'anéantir à la fois le Fléau et les races vivantes, menant des expériences impitoyables pour assurer la suprématie des Réprouvés.",al={"que fait la société royale des apothicaires","but de la société royale des apothicaires","apothicaires de fossoyeuse"}},["3c47ce18"]={q="Font-ils des expériences sur des gens ?",a="Oui. Au plus profond de l'Apothicarium, des croisés de la Croisade écarlate capturés, des goules du Fléau et diverses bêtes sont enfermés dans des cages de fer. Les apothicaires soumettent ces prisonniers à des cocktails chimiques douloureux et à des souches de peste virulentes, évaluant la rapidité avec laquelle la chair pourrit et comment la contagion affecte la physiologie vivante et nécrotique.",al={"apothicaire faisant des expériences sur des humains","expériences de la société royale des apothicaires","les apothicaires de fossoyeuse torturent-ils des gens"}},["1b77984b"]={q="Quel est cet endroit, les Ruines de Lordaeron ?",a="Vous vous tenez dans les restes brisés de la capitale, autrefois le joyau de la civilisation humaine et le cœur du royaume de Lordaeron. Durant la Troisième guerre, le prince Arthas a trahi son royaume, massacré son père, le roi Terenas, dans la salle du trône au-dessus, et déchaîné le Fléau mort-vivant dans ses rues. Aujourd'hui, ses arches brisées et ses tours calcinées surplombent la souterraine Fossoyeuse, servant de triste mémorial au royaume déchu.",al={"que sont les ruines de lordaeron","histoire ruines de lordaeron","ce qu'était cet endroit"}},eb89374f={q="Qui vivait ici avant que ce ne soit en ruines ?",a="Cette ville était le foyer du plus grand royaume du nord de l'humanité, gouverné par la dynastie Menethil. Des nobles, des prêtres de la Lumière sacrée, des soldats et des centaines de milliers de gens du peuple arpentaient autrefois ces rues pavées. Tragiquement, nombre de ces anciens citoyens ne sont jamais vraiment partis ; fauchés par la peste, leurs cadavres réanimés constituent à la fois le Fléau sans esprit hantant les Maleterres et les Réprouvés libérés qui habitent désormais les cavernes en dessous.",al={"qui vivait ici avant","peuple originel de lordaeron","qui était ici en premier"}},["6e6195fd"]={q="Pourquoi tout est-il brisé et brûlé ?",a="Lorsque le prince Arthas revint avec Deuillegivre, il tua le roi Terenas et livra la ville au Fléau. Des horreurs mort-vivantes ont dévasté les avenues, brûlant les bâtiments et massacrant quiconque tentait de résister. Plus tard, pendant la guerre civile parmi les morts-vivants, Sylvanas Coursevent et ses Réprouvés ont combattu des seigneurs de l'effroi et les légions persistantes du Fléau à travers ces cours mêmes, démolissant ce qu'il restait de la grande architecture de la ville.",al={"pourquoi lordaeron est détruit","comment lordaeron a brûlé","pourquoi est-ce en ruines"}},dd470a5c={q="Qui a détruit Lordaeron ?",a="Le royaume a été brisé de l'intérieur par son propre prince héritier, Arthas Menethil, sous le murmure corrupteur du roi Liche. Envoyé pour arrêter le Culte des damnés et leur peste de non-mort, Arthas est devenu impitoyable, s'est emparé de la lame runique maudite Deuillegivre dans le nord glacé et a abandonné son âme. De retour chez lui en tant que chevalier de la mort, il a abattu son père et a livré la ville aux griffes du Fléau.",al={"qui a ruiné lordaeron","qui a causé la chute de lordaeron","destructeur de lordaeron"}},f5a9164f={q="Où est Arthas maintenant ?",a="Arthas a quitté le continent en ruines de Lordaeron il y a des années, naviguant à travers la Grande mer vers le Norfendre lorsque le roi Liche a été menacé par le chasseur de démons Illidan Stormrage. Il s'est frayé un chemin jusqu'au sommet de la flèche glacée du Trône de glace et a disparu de la vue de tous dans les terres désolées glacées, laissant derrière lui un royaume brisé en factions rivales de morts-vivants et de survivants.",al={"où est allé arthas","où est le prince arthas","emplacement arthas"}},["2fe0baef"]={q="Quelqu'un a-t-il réussi à fuir la ville ?",a="Quelques chanceux ont échappé au massacre. Avant l'effondrement final, la magicienne Jaina Portvaillant a tenu compte des avertissements d'un mystérieux prophète et a conduit des milliers de réfugiés humains à travers la mer jusqu'en Kalimdor, où ils ont établi le port de Theramore. D'autres ont fui vers le sud en direction du royaume de Hurlevent, ou ont pris les armes saintes pour se défendre, formant la fanatique Croisade écarlate et la vigilante Aube d'argent.",al={"des citoyens de lordaeron ont-ils survécu","quelqu'un a-t-il survécu à la chute de lordaeron","survivants de lordaeron"}},["9cf7434f"]={q="Pourquoi y a-t-il une ville de morts-vivants sous les ruines ?",a="Lorsque le pouvoir du roi Liche a décliné, Sylvanas Coursevent a brisé son contrôle mental sur une multitude de morts-vivants. Se faisant appeler les Réprouvés, ils ont renversé les seigneurs de l'effroi démoniaques qui tenaient la capitale. Les ruines au-dessus étaient trop exposées aux yeux hostiles et aux attaques constantes de la Croisade écarlate, alors Sylvanas a choisi de transformer les vastes cryptes et égouts souterrains en une forteresse lourdement fortifiée.",al={"pourquoi fossoyeuse existe","pourquoi fossoyeuse est sous lordaeron","ville de morts-vivants sous les ruines"}},["55ddf3da"]={q="Qui a construit Fossoyeuse ?",a="Les fondations ont commencé sous la capitale en tant que donjons royaux, égouts et cryptes profondes construits par les Humains de Lordaeron. Durant la Troisième guerre, Arthas et le Fléau ont commencé à étendre ces couloirs souterrains en un réseau élaboré destiné à être un centre de pouvoir du Fléau. Après avoir arraché le contrôle au seigneur de l'effroi Varimathras, Sylvanas et les Réprouvés ont fini de creuser Fossoyeuse pour en faire leur capitale permanente.",al={"qui a fait fossoyeuse","construction fossoyeuse","qui a excavé fossoyeuse"}},c0ee4f6f={q="Fossoyeuse a-t-elle toujours été là-dessous ?",a="Pas dans son état moderne et tentaculaire. À l'époque du roi Terenas, le sous-sol consistait simplement en donjons de château, aqueducs, canaux d'égout et tombeaux familiaux. Ce n'est qu'après la chute du royaume que les abominations du Fléau et les travailleurs réprouvés ont creusé les anneaux et quartiers massifs que vous voyez aujourd'hui, transformant les tunnels utilitaires en un vaste bastion souterrain des morts.",al={"fossoyeuse a-t-elle toujours été là","fossoyeuse existait avant","vieille fossoyeuse"}},dc41e367={q="Qui est aux commandes ici ?",a="Dame Sylvanas Coursevent, la reine banshee, commande ces ruines et Fossoyeuse en dessous. Autrefois général des forestiers de Lune-d'argent, elle fut tuée par Arthas, ressuscitée en banshee vengeresse, et finit par reprendre possession de son corps physique. Par sa pure volonté et sa ruse, elle a libéré ses frères morts-vivants et forgé les Réprouvés, les guidant avec une détermination impitoyable depuis son trône dans le Royal Quarter.",al={"qui dirige les ruines de lordaeron","chef de fossoyeuse","qui contrôle cet endroit"}},["3d3094f9"]={q="Sylvanas est-elle une reine ou autre chose ?",a="Son peuple la vénère comme la reine banshee et Dame des Réprouvés, mais elle n'est pas une héritière royale de Lordaeron. Le titre reflète la nature tragique de sa mort aux mains du prince Arthas, qui a arraché son âme de son corps pour servir de banshee gémissante. Bien que le titre évoque la monarchie, son autorité naît de la libération, de la survie et du commandement militaire total.",al={"sylvanas est-elle une reine","titre reine banshee","quel est le titre de sylvanas"}},ac534dbb={q="Sylvanas rend-elle des comptes à Thrall ?",a="Sur le papier, Sylvanas reconnaît le chef de guerre Thrall comme le commandant suprême de la Horde, et elle a accepté leur alliance de circonstance. En réalité, la reine banshee maintient une autonomie totale sur les Réprouvés et leurs territoires du nord. La parole de Thrall est respectée et des émissaires réprouvés circulent à Orgrimmar, mais Dame Sylvanas répond avant tout à sa propre survie et aux ambitions de son peuple.",al={"relation sylvanas thrall","sylvanas obéit-elle à thrall","sylvanas est-elle sous les ordres de thrall"}}},fp="18,278,27.503.0,22.413.0,25.302.1,48.174.0,61.277.0,23.179.0,49.228.0,61.384.1,54.227.0"}
P.entries["zone:scarlet"] = {n="Monastère écarlate",s="Perché sur les collines du nord-est des Clairières de Tirisfal, le Monastère écarlate était autrefois un sanctuaire paisible et un centre d'apprentissage pour l'Église de la Sainte Lumière. Après la chute de Lordaeron, il a été pris et lourdement fortifié par la Croisade écarlate comme base avancée principale dans l'ouest. Aujourd'hui, il se dresse comme une forteresse tentaculaire divisée en quatre ailes, où des zélotes fanatiques s'entraînent, torturent des prisonniers et mènent une guerre sans compromis contre tous les étrangers.",h="Perché sur les collines du nord-est des Clairières de Tirisfal, le Monastère écarlate était autrefois un...",kw={"armurerie","cathédrale","doan","cimetière","hérode","library","mograine","croisade écarlate","monastère écarlate","clairières de tirisfal","whitemane"},ang={["class:Mage"]="L'aile de la Bibliothèque abrite des tomes historiques et théologiques rares gardés par l'Arcaniste Doan, le plus éminent arcaniste de la Croisade.",["class:Paladin"]="Le monastère était autrefois un siège sacré du sacerdoce de Lordaeron, faisant de sa déchéance dans le fanatisme écarlate un rappel tragique de la manière dont la dévotion peut tourner à la folie.",["class:Priest"]="À l'origine siège de l'Église de la Sainte Lumière, ses grandioses chapelles démontrent à quel point la puissance sacrée peut encore être maniée par des mortels corrompus par la haine et la vengeance.",["race:Undead"]="Perché à la frontière des Clairières de Tirisfal, le Monastère écarlate représente une menace existentielle pour les Réprouvés, envoyant des espions jusqu'au Glas et torturant les morts-vivants capturés dans ses donjons."},sec={{t="Un sanctuaire déchu",b="Avant la Troisième guerre, le monastère servait de fière assise au sacerdoce de Lordaeron et de centre d'apprentissage et d'illumination. Après la dévastation causée par le Fléau, les croisés survivants ont purgé les salles des morts-vivants et des araignées qui y rôdaient encore, transformant les archives et les cours tranquilles en une garnison fortifiée. Poussée par la paranoïa et le chagrin, la Croisade écarlate en est venue à considérer tous les étrangers — vivants ou morts-vivants, humains ou autres — comme des porteurs de la peste devant être purifiés par le feu."},{t="Les quatre ailes",b="Au-delà du Grand Vestibule du monastère s'étendent quatre quartiers distincts. Le Cimetière est une terrasse à ciel ouvert profanée où les croisés déchus se relèvent sous forme d'abominations mortes-vivantes et où des tortionnaires arrachent des aveux aux prisonniers. La Bibliothèque préserve de précieux textes théologiques et des tomes historiques, gardés par le mage renégat Arcaniste Doan et ses molosses. L'Armurerie sert de terrain d'entraînement où des maîtres d'armes écarlates comme Hérode forment des recrues fanatiques en guerriers d'acier. Au plus profond se dresse la Cathédrale, le grand cœur de la place forte d'où les dirigeants de la Croisade dirigent leur croisade à travers le nord flétri."},{t="La chute de la Haute inquisitrice",b="Le sanctuaire intérieur de la cathédrale est dirigé par le Commandant écarlate Mograine et le véritable maître du monastère, le Grand Inquisiteur Whitemane. Vaincre Whitemane porte un coup critique au commandement opérationnel de la Croisade écarlate dans les Clairières de Tirisfal. Sa capacité à canaliser la Lumière sacrée aveuglante et à ressusciter les champions tombés faisait paraître la garnison invincible aux yeux de ses fidèles. La tuer brise l’aura de mandat divin qui nourrissait le fanatisme du monastère, révèle que les chefs de la Croisade écarlate sont mortels et affaiblit considérablement leur campagne contre les Réprouvés et les terres voisines."}},faq={{q="Pourquoi la Croisade écarlate est-elle hostile aux aventuriers vivants de l'Alliance ?",a="La Croisade a sombré dans une folie et une paranoïa extrêmes. À leurs yeux, quiconque ne porte pas leur tabard cramoisi est un porteur potentiel de la peste du Fléau. Ils ne font plus de distinction entre ami et ennemi, considérant tous les étrangers comme des êtres souillés devant être purgés avant de pouvoir propager la corruption.",al={"pourquoi les écarlates attaquent les humains","croisade écarlate hostile alliance","pourquoi sont-ils fous"}},{q="Que se passe-t-il lorsque vous vainquez le Grand Inquisiteur Whitemane ?",a="Vaincre le Grand Inquisiteur Whitemane décapite le commandement militaire occidental de la Croisade écarlate. En tant que guide spirituelle du monastère, ses pouvoirs miraculeux de résurrection entretenaient le moral des troupes et permettaient au Commandant Mograine de combattre à ses côtés. Sa mort prive la Croisade écarlate de sa prêtresse la plus redoutable dans les Clairières de Tirisfal, plonge la garnison dans le désordre et réduit considérablement la menace qu’elle représente pour la région environnante.",al={"que signifie tuer whitemane","lore défaite whitemane","fin cathédrale"}},{q="Qu'est-ce que la Clé écarlate et où se trouve-t-elle ?",a="La Clé écarlate est conservée au plus profond de l'aile de la Bibliothèque du monastère, enfermée dans le coffre-fort de l'Arcaniste Doan derrière son cabinet d'étude personnel. Posséder cette clé est indispensable pour déverrouiller les portes extérieures de l'aile de l'Armurerie et de celle de la Cathédrale.",al={"où est la clé écarlate","comment débloquer armurerie et cathédrale","clé du monastère"}},{q="Pourquoi l'Arcaniste Doan se trouve-t-il dans le Monastère écarlate ?",a="L'Arcaniste Doan est un puissant mage humain au service de la Croisade écarlate, convaincu que la magie profane est une arme indispensable pour purifier Lordaeron du Fléau. Il supervise la vaste aile de la Bibliothèque du monastère et garde la Clé écarlate dans son cabinet d'étude.",al={"qui est l'arcaniste doan","lore doan","mage à la bibliothèque"}},{q="Qui était Alexandros Mograine et quel est son lien avec cet endroit ?",a="Alexandros Mograine, le célèbre Porte-cendres, était un paladin légendaire de la Main d’argent et, avec le Grand Général Abbendis et le Grand Inquisiteur Isillien, l’un des fondateurs de la Croisade écarlate. Son fils Renault commande désormais la cathédrale aux côtés du Grand Inquisiteur Whitemane.",al={"histoire mograine monastère","porte-cendres monastère","père de renault mograine"}},{q="Qu'est-ce qui rend l'aile du Cimetière si différente du reste du monastère ?",a="Tandis que le reste du monastère conserve une apparence extérieure de dévotion immaculée, le Cimetière est le lieu où le fanatisme de la Croisade pourrit de l'intérieur. Il abrite leurs brutales salles de torture dirigées par l'Interrogateur Vislar, tandis que des cryptes à l'abandon et des morts sans repos sont exploités ou manipulés par des lanceurs de sorts déchus comme le Mage de sang Thalnos.",al={"pourquoi le cimetière est mort-vivant","lore thalnos","interrogateur vislar"}}},fx={["3ffc247b"]={q="Qu'est-ce que le Monastère écarlate ?",a="Perché dans le nord-est des Clairières de Tirisfal, le Monastère écarlate est un sanctuaire fortifié et le bastion principal de la Croisade écarlate dans la région. Autrefois un complexe cathédral paisible voué à la Lumière sacrée et à l'apprentissage clérical, la place forte a été transformée en un quartier général lourdement armé, un terrain d'entraînement et une redoute idéologique pour la campagne zélée de la Croisade contre les morts-vivants.",al={"qu'est-ce que le monastère écarlate","lore du monastère écarlate","à propos du monastère écarlate"}},fd7417a7={q="Le Monastère écarlate a-t-il toujours été le leur ?",a="Non. Avant la chute de Lordaeron, il était simplement connu sous le nom de Vieux monastère. Patronné à l'origine par la noble maison Godwyn, il servait de siège archiépiscopal et de séminaire sous l'archevêque Alonsus Faol. Après la dévastation de la Troisième guerre, des paladins survivants ont repris ses salles aux infestations persistantes du Fléau et l'ont rebaptisé Monastère écarlate.",al={"le monastère écarlate a-t-il toujours été la croisade","histoire du monastère écarlate","à qui appartenait le monastère écarlate"}},e7b85043={q="Qui a construit le Monastère écarlate ?",a="Le Vieux monastère a été construit comme un sanctuaire de l'Église de la Lumière sacrée sous le parrainage de la noble maison Godwyn. Ses bibliothèques et archives ont été conservées pendant des générations par des archivistes comme Blake Godwyn, se dressant comme un fier centre du sacerdoce de Lordaeron et de la formation des paladins jusqu'à l'effondrement du royaume.",al={"qui a construit le monastère","origines du monastère"}},["0c05301c"]={q="Qui est la Croisade écarlate ?",a="La Croisade écarlate est un ordre militaire fanatique de guerriers et de prêtres sacrés humains, formé à partir des restes de la Main d'argent. Consumés par le chagrin et la haine suite au Fléau de Lordaeron, ils se sont entièrement consacrés à l'éradication des morts-vivants, imposant leur mission avec une cruauté et une paranoïa extrêmes.",al={"qui est la croisade écarlate","qu'est-ce que la croisade écarlate","lore de la croisade écarlate"}},b0ef06b1={q="Les membres de la Croisade écarlate sont-ils humains ?",a="Oui, leurs rangs sont composés entièrement d'humains du royaume déchu de Lordaeron. Ils nourrissent une farouche intolérance envers toutes les races non-humaines, indépendamment de toute alliance ou lien passé, jugeant les étrangers indignes ou intrinsèquement corrompus par la peste.",al={"la croisade écarlate est-elle seulement humaine","race de la croisade","la croisade écarlate est-elle humaine"}},["1402011d"]={q="Pourquoi est-ce que j'attaque une église pleine de paladins ?",a="Bien qu'ils portent les atours des ordres sacrés et manient la Lumière, les commandants du Monastère ont sombré dans un extrémisme violent. Que vous répondiez à l'appel de Raleigh le Dévot pour purifier la direction corrompue de l'ordre, ou que vous frappiez au nom de Varimathras à Fossoyeuse pour neutraliser un voisin agressif à sa porte, vous êtes là pour briser leur puissance militaire.",al={"pourquoi attaquer le monastère écarlate","pourquoi tuer des paladins ici","raison de combattre au monastère écarlate"}},["18e8d4ac"]={q="La Croisade écarlate est-elle réellement maléfique ?",a="Ils ont commencé avec une cause noble : purger Lordaeron du Fléau des morts-vivants. Cependant, le traumatisme et la paranoïa ont complètement déformé leur objectif. Ils torturent désormais des voyageurs innocents, marquent tout étranger comme étant contaminé et massacrent quiconque ne portant pas leur tabard, perdant toute santé morale dans la poursuite de la purification.",al={"la croisade écarlate est-elle maléfique","sont-ils les méchants","les croisés sont-ils maléfiques"}},fe2faadd={q="L'Alliance soutient-elle la Croisade écarlate ?",a="Pas officiellement. Bien que certains à Hurlevent puissent nourrir de la sympathie pour les guerriers sacrés survivants de Lordaeron, l'hostilité aveugle de la Croisade a rompu les liens formels. Les aventuriers et des personnalités de l'Alliance comme Raleigh le Dévot considèrent leurs commandants actuels comme des fanatiques fous dont les atrocités ternissent l'honneur de la Lumière.",al={"l'alliance soutient-elle la croisade","la croisade écarlate est-elle de l'alliance","liens de l'alliance avec la croisade écarlate"}},ae07147f={q="Le chef du Monastère se trouve-t-il à l'intérieur de la Cathédrale ?",a="Oui. Le Commandant écarlate Mograine et la Grande inquisitrice Whitemane résident tous deux au sein de la Chapelle du croisé, au plus profond de l'aile de la Cathédrale, gardés par une suite intérieure de défenseurs zélés.",al={"où est whitemane","whitemane est-elle dans la cathédrale","emplacement du boss de la cathédrale"}},["11700a05"]={q="Pourquoi la Croisade écarlate déteste-t-elle autant les Réprouvés ?",a="Pour la Croisade, tous les morts-vivants sont des abominations nées de la peste qui a oblitéré leurs familles et leur patrie. Ils ne font aucune distinction entre les sbires écervelés du Fléau et les Réprouvés dotés du libre arbitre qui occupent la Capitale ; tous sont considérés comme des usurpateurs putréfiés qui doivent être entièrement nettoyés par le feu sacré.",al={"croisade contre réprouvés","pourquoi la croisade déteste les morts-vivants","conflit croisade écarlate réprouvés"}},["38169c8a"]={q="Les croisés écarlates et les Réprouvés étaient-ils autrefois le même peuple ?",a="Oui. La plupart des croisés et des Réprouvés étaient des citoyens, des soldats ou des prêtres du royaume de Lordaeron avant la Troisième guerre. Lorsque la peste a sévi, ceux qui sont morts et revenus à la vie sont devenus les morts-vivants, tandis que les survivants traumatisés ont fui ou se sont ralliés, transformant d'anciens voisins et parents en ennemis amers et jurés.",al={"les croisés et les réprouvés se connaissaient-ils","étaient-ils tous deux citoyens de lordaeron","vestiges de lordaeron"}},["80c0e472"]={q="D'où vient la Croisade écarlate ?",a="La Croisade est née des chevaliers de la Main d'argent survivants et des soldats de Lordaeron menés par le Haut seigneur Alexandros Mograine et le général Abbendis. Dépassés par la perte de leur royaume, les chefs survivants se sont divisés : ceux qui prônaient un zèle implacable et sans compromis ont formé la Croisade écarlate, tandis que les modérés se sont séparés pour fonder l'Aube d'argent.",al={"origine de la croisade écarlate","comment la croisade écarlate a-t-elle été fondée","qui a lancé la croisade écarlate"}},c4a70323={q="Qu'était la Main d'argent ?",a="Les chevaliers de la Main d'argent étaient l'ordre sacré légendaire de paladins fondé pendant la Deuxième guerre par l'archevêque Alonsus Faol et Uther le Porteur de Lumière. Ils ont servi de champions de première ligne de l'Alliance et de Lordaeron jusqu'à ce que le prince Arthas brise leurs rangs lors de l'invasion du Fléau.",al={"qu'était la main d'argent","chevaliers de la main d'argent","paladins de la main d'argent"}},d5472427={q="Pourquoi la Croisade écarlate tue-t-elle aussi des humains vivants ?",a="Une paranoïa profonde a érodé la prise de la Croisade sur la réalité. Ils croient que tout étranger pourrait être un porteur caché de la peste des morts-vivants. Quiconque ne portant pas leur uniforme et ne se soumettant pas à leur autorité rigide est marqué comme corrompu et condamné à la torture ou à la mort.",al={"pourquoi attaquer des humains vivants","la croisade tue des humains","pourquoi tuent-ils les leurs"}},b6568619={q="La Croisade écarlate est-elle une menace pour Hurlevent ?",a="Pas directement en termes de conquête géographique, car leurs efforts sont ancrés dans les ruines septentrionales de Lordaeron. Cependant, leur folie et leur volonté de assassiner n'importe quel voyageur font d'eux une menace active pour les citoyens, les ambassadeurs et les aventuriers de l'Alliance qui s'aventurent près de leurs territoires.",al={"la croisade écarlate est-elle une menace pour l'alliance","croisade contre hurlevent","menace de la croisade écarlate"}},["6889160e"]={q="Pourquoi tout le monde veut-il que je me rende au Monastère écarlate ?",a="Les deux factions ont des intérêts vitaux dans les Clairières de Tirisfal. Les Réprouvés ne peuvent tolérer une forteresse de fanatiques lourdement armés juste devant leur capitale, tandis que des personnalités de l'Alliance cherchent à récupérer des textes sacrés, à mater de dangereux renégats et à rendre justice face à des dirigeants devenus fous.",al={"pourquoi suis-je envoyé au monastère écarlate","qui veut la mort du monastère","raison des quêtes du monastère écarlate"}},["0c6b4a7d"]={q="À quoi sert la Library du Monastère écarlate ?",a="La Library, qui comprend l'Athénée et la Gallery of Treasures, abrite d'anciennes écritures de Lordaeron, des documents historiques et des connaissances arcaniques. Elle sert à la fois d'archive intellectuelle et de sanctuaire de recherche isolé présidé par l'Arcaniste Doan.",al={"but de l'aile de la library","que font-ils dans la library","athénée du monastère écarlate"}},["29dc31ee"]={q="À quoi servent les ailes de l'Armurerie et de la Cathédrale ?",a="L'Armurerie sert de cœur martial à The Scarlet Crusade, abritant des terrains d'entraînement, des casernes et des stocks d'armes supervisés par Hérode, le champion écarlate. La Cathédrale constitue le sanctuaire spirituel suprême et le poste de commandement, où Mograine entraîne des troupes d'élite et où Whitemane prononce ses sermons et coordonne la présence de The Scarlet Crusade dans les Clairières de Tirisfal.",al={"à quoi servent l'armurerie et la cathédrale","but de l'armurerie du monastère","but de la cathédrale du monastère"}},f04a1b7f={q="Comment ai-je fini au Monastère écarlate ?",a="Vous avez voyagé jusqu'aux collines du nord-est des Clairières de Tirisfal, en traversant les clairières brumeuses jusqu'au siège fortifié de The Scarlet Crusade. Que vous vous soyez glissé depuis Fossoyeuse sur ordre de la Horde pour démanteler une menace fanatique sur leur pas de porte, ou que vous ayez marché vers le nord depuis les Contreforts de Hautebrande en répondant à l'appel de croisés désabusés cherchant à purger les dirigeants fanatiques du Monastère, le chemin vous a inévitablement conduit devant ce complexe lourdement gardé.",al={"comment suis-je arrivé ici","comment suis-je arrivé au monastère écarlate","pourquoi suis-je venu ici"}},be779d1d={q="Que suis-je censé faire dans le Monastère écarlate ?",a="Vous êtes ici pour percer les quatre ailes de The Scarlet Crusade et briser leur emprise sur la région. Selon qui vous a envoyé, vous pourriez traquer des dirigeants déchus comme le Commandant écarlate Mograine et la Grande inquisitrice Whitemane, découvrir des tomes et des connaissances perdus dans la Library, rassembler des cœurs de zèle pour la Société royale des apothicaires, ou récupérer des artefacts sacrés et tuer des dirigeants corrompus qui traitent quiconque n'est pas dans leurs rangs comme un mort-vivant pestiféré.",al={"que fais-je ici","pourquoi suis-je ici","quelle est ma mission ici"}},fbd0569e={q="Qui est responsable du Monastère écarlate ?",a="La garnison militaire de la forteresse répond aux ordres du Commandant écarlate Renault Mograine, qui commande une troupe dévouée de guerriers. Cependant, le véritable maître spirituel et doctrinal du complexe est la Grande inquisitrice Blanchetête, une puissante prêtresse capable de ressusciter les défunts pour qu'ils combattent en son nom.",al={"qui dirige le monastère écarlate","qui gère le monastère","chef du monastère écarlate"}}},fp="17,291,18.495.0,14.492.0,31.517.1,66.284.0,55.301.1,46.170.0,46.213.0,57.280.1,74.218.0"}
P.entries["zone:searinggorge"] = {n="Gorge des Vents brûlants",s="La Gorge des Vents brûlants est un canyon désolé et calciné, au sud de Khaz Modan, qui borde le mont Rochenoire au sud. Autrefois verdoyante étendue des Carmines, elle fut dévastée il y a plus de deux siècles par l’invocation apocalyptique de Ragnaros, le seigneur du Feu. Aujourd’hui, le clan Sombrefer exploite intensément la gorge, et surveille de près ses vastes mines d’esclaves du Chaudron, tout comme la Confrérie du thorium, qui a fait sécession.",h="La Gorge des Vents brûlants est un canyon désolé et calciné, au sud de Khaz Modan, qui borde le mont...",kw={"mont rochenoire","le chaudron","clan sombrefer","ragnaros","gorge des vents brûlants","la fosse aux scories","passage de formepierre","confrérie du thorium","halte du thorium"},ang={["class:Rogue"]="Les voleurs dotés d’une solide expérience du crochetage sont des voyageurs recherchés ici, car ils peuvent franchir la porte verrouillée du Passage de Formepierre, qui relie directement le Loch Modan à la gorge.",["faction:Alliance"]="L’Alliance maintient verrouillée la porte du Passage de Formepierre pour isoler les Sombrefer des paisibles communautés naines du Loch Modan, bien que les aventuriers courageux soient autorisés à frapper au cœur de la gorge.",["faction:Horde"]="En prenant Kargath comme base de départ, la Horde a ouvert une voie terrestre vers la gorge afin de recueillir des renseignements sur le mont Rochenoire et de perturber les opérations Sombrefer dans Khaz Modan.",["profession:Mining"]="Le paysage volcanique et les profondes excavations de la Fosse aux scories font de la Gorge des Vents brûlants l’un des principaux terrains de chasse aux riches filons de mithril, de vrai-argent et de minerai de sombrefer convoité.",["race:Dwarf"]="Pour les nains de Forgefer, la Gorge des Vents brûlants rappelle amèrement la guerre des Trois Marteaux et la folie dévastatrice du clan Sombrefer, dont les excavations menacent désormais les accès méridionaux de Khaz Modan."},sec={{t="Une terre calcinée",b="Avant la guerre des Trois Marteaux, le territoire qui forme aujourd’hui la Gorge des Vents brûlants était une région montagneuse verdoyante, aux collines ondulantes, reliée à la chaîne des Carmines. Ce paysage luxuriant disparut il y a plus de deux cent trente ans, lorsque le sorcier-thane Thaurissan, désespéré de renverser le cours de la défaite, invoqua Ragnaros depuis les profondeurs du monde. L’arrivée cataclysmique du seigneur du Feu déchira la terre, fit surgir le mont Rochenoire, réduisit la grande cité sombrefer de Thaurissan en ruines fumantes et changea la vallée du nord en une étendue craquelée de cendres, de soufre et de verre volcanique."},{t="Le Chaudron et la Fosse aux scories",b="En quête de matières premières pour alimenter leur machine de guerre après la perte de leur ancienne capitale, les nains Sombrefer s’emparèrent de la gorge désolée. Au centre de la vallée se trouve le Chaudron, une excavation à ciel ouvert colossale qui plonge profondément dans la roche. Dans ses recoins inférieurs se trouve la Fosse aux scories, un complexe minier souterrain impitoyable. Ici, les surveillants Sombrefer et de lourds golems de guerre forcent les ennemis capturés à un dur labeur d’esclave, extrayant du fer, du mithril et de rares gisements de minerai de sombrefer de la roche ardente, sous la menace constante des coulées de lave et des bêtes errantes."},{t="La Confrérie du thorium et les chemins disputés",b="Perchée sur les escarpements du nord, qui surplombent l’excavation, se trouve la Halte du Thorium, l’avant-poste fortifié de la Confrérie du thorium. Après s’être séparés de leurs semblables du mont Rochenoire, ces maîtres artisans offrent un abri neutre aux voyageurs prêts à saper les opérations Sombrefer ou à leur fournir de rares composants de fonderie. L’accès à la gorge est strictement limité : l’Alliance verrouille le Passage de Formepierre derrière de lourdes portes de fer en direction du Loch Modan, tandis que les expéditions de la Horde venues du Kargath voisin ont tracé un sentier étroit à travers les Terres Ingrates orientales pour explorer la région."}},faq={{q="Pourquoi la Gorge des Vents brûlants est-elle brûlée et couverte de cendres ?",a="Il y a plus de deux cent trente ans, pendant la guerre des Trois Marteaux, le sorcier-thane Sombrefer Thaurissan tenta d’invoquer une puissance surnaturelle pour éviter la défaite. À la place, il invoqua Ragnaros, le seigneur du Feu. L’éruption cataclysmique brisa le sud des Carmines, créa le volcan du mont Rochenoire et incinéra les vallées alentour, donnant naissance à la Gorge des Vents brûlants et aux Steppes Ardentes.",al={"pourquoi est-elle brûlée","histoire de la gorge des vents brûlants","comment la gorge des vents brûlants s’est-elle formée"}},{q="Qui sont les nains qui vivent à la Halte du Thorium ?",a="Ils appartiennent à la Confrérie du thorium, une faction indépendante de nains Sombrefer qui a rompu les liens avec ses semblables impériaux sous le mont Rochenoire. Depuis leur camp au sommet de la Halte du Thorium, ils œuvrent comme maîtres forgerons et artisans, échangeant savoir et secrets de fabrication avec tout voyageur qui les aide contre les forces Sombrefer en contrebas.",al={"nains de la halte du thorium","qui est la confrérie du thorium","histoire de la confrérie du thorium"}},{q="Que se passe-t-il au Chaudron ?",a="Le Chaudron est une immense excavation à ciel ouvert dominée par le clan Sombrefer, qui abrite la Fosse aux scories souterraine. Les surveillants Sombrefer et les golems de guerre réduisent les prisonniers capturés en esclavage pour en extraire des minerais précieux, dont le très prisé minerai de sombrefer, destiné aux grandes forges du mont Rochenoire.",al={"qu’est-ce que le chaudron","histoire de la fosse aux scories","que minent les sombrefer"}},{q="Comment rejoindre la Gorge des Vents brûlants depuis le Loch Modan ?",a="Le passage depuis le Loch Modan, par le Passage de Formepierre, est barré par une lourde porte verrouillée, gardée par des montagnards de Forgefer. Les voyageurs doivent soit obtenir la Clé de la gorge des Vents brûlants en accomplissant une mission officielle pour le Conservateur en chef Thorius, soit demander à un voleur expérimenté de crocheter le mécanisme, soit contourner entièrement la porte en empruntant le sentier ouvert au sud de Kargath, dans les Terres Ingrates.",al={"porte du passage de formepierre","comment ouvrir la porte de la gorge des vents brûlants","clé de la gorge des vents brûlants"}},{q="Pourquoi la Horde s’intéresse-t-elle à la Gorge des Vents brûlants ?",a="Depuis la forteresse voisine de Kargath, dans les Terres Ingrates, les commandants de la Horde ont taillé un passage de montagne menant à la gorge pour surveiller les mouvements des troupes Sombrefer et sécuriser des routes stratégiques vers le mont Rochenoire, d’une immense importance stratégique.",al={"pourquoi la horde est-elle ici","liaison entre kargath et la gorge","présence de la horde"}},{q="Y a-t-il des donjons ou des entrées de raid dans la Gorge des Vents brûlants ?",a="Il n’y a pas de portail d’instance directement dans la gorge, mais l’entrée sud mène tout droit au mont Rochenoire. Cette montagne abrite les Profondeurs de Rochenoire, le Pic Rochenoire et les passages profonds qui conduisent au Cœur du Magma.",al={"instances de la gorge des vents brûlants","donjons dans la gorge des vents brûlants","où se trouve le cœur du magma"}}},fp="13,249,20.456.0,29.498.0,39.549.0,51.376.0,44.359.0,33.260.0,50.303.0,45.225.0,62.207.0"}
P.entries["zone:shadowfang"] = {n="Donjon d'Ombrecroc",s="Perché sur les falaises escarpées surplombant Bois-du-Bûcher, le Donjon d'Ombrecroc est le sombre bastion du mage renégat du Kirin Tor, l'archimage Arugal. Autrefois domaine ancestral du Baron d'Argelaine, la forteresse grouille désormais de bêtes worgens férales et des fantômes tourmentés de ses défenseurs massacrés. Pour les aventuriers traversant le sud de la Forêt des Pins-Argentés, le donjon représente le sombre épicentre du fléau bestial qui ronge la région.",h="Perché sur les falaises escarpées surplombant Bois-du-Bûcher, le Donjon d'Ombrecroc est le sombre bastion du...",kw={"arugal","fenrus","bois-du-bûcher","sfk","ombrecroc","argelaine","forêt des pins-argentés","printeval","worgen"},ang={["class:Mage"]="La tragédie d'Ombrecroc sert de sombre avertissement sur ce qui survient lorsqu'un mage du Kirin Tor se mêle d'invocations extradimensionnelles hors de tout contrôle mortel.",["class:Paladin"]="L'esprit tourmenté du Commandant Printeval rappelle tristement le sort des défenseurs paladins déchus dont les serments sacrés furent dénaturés par la mort.",["class:Warlock"]="Les sombres énergies, les marcheurs du Vide et la magie noire au sein du donjon attirent l'intérêt des érudits cherchant à récupérer d'anciennes reliques telles que l'Orbe de Soran'ruk.",["faction:Horde"]="Les Réprouvés considèrent les meutes envahissantes d'Arugal comme une menace immédiate pour leur jeune territoire dans la Forêt des Pins-Argentés, faisant du donjon une cible prioritaire pour les agents Deathstalkers et la Société royale des apothicaires."},sec={{t="La chute de la dynastie d'Argelaine",b="Avant d'être plongé dans le cauchemar, Ombrecroc était connu sous le nom de donjon d'Argelaine, une noble demeure gardée par le pieux Commandant Printeval. Lorsque le Fléau déferla sur Lordaeron durant la Troisième guerre, les mages de Dalaran tombèrent en masse. Désespéré d'endiguer la marée des morts qui s'élevait, l'archimage Arugal défia les dirigeants du Kirin Tor et plongea dans les recherches du mage Ur, invoquant des worgens extradimensionnels pour inverser le cours de la bataille. Les bêtes invoquées massacrèrent les morts-vivants, mais échappèrent rapidement à tout contrôle mortel, faisant irruption dans le sud de la Forêt des Pins-Argentés et prenant le bastion d'assaut. Le Baron d'Argelaine et toute sa cour furent massacrés, condamnés à hanter les salles de pierre aux côtés des monstres féraux qui avaient envahi leur demeure."},{t="Les enfants d'Arugal",b="Brisé par la culpabilité et la folie, Arugal se retrancha derrière les remparts tachés de sang, adoptant les hommes-loups voraces comme ses « enfants » bien-aimés et rebaptisant le château Donjon d'Ombrecroc. Au plus profond des perchoirs de pierre, des meutes lupines et des chiens d'ombre prospèrent sous la tutelle de dresseurs tels que Wolf Master Nandos, surveillés par l'imposante bête lupine d'Arugal, Fenrus le Dévoreur. Hors des murs, la malédiction ne s'arrêta pas : le village voisin de Bois-du-Bûcher demeure prisonnier d'un terrifiant cycle nocturne, ses résidents vivant comme des hommes le jour et chassant comme des worgens voraces sous la lune, inexorablement liés au fou archimage perché sur les hauteurs."},{t="La frappe des Réprouvés",b="Consciente de la terrible menace qu'Arugal fait peser sur leur souveraineté dans la Forêt des Pins-Argentés, Dame Sylvanas Coursevent a dépêché la Société royale des apothicaires et des Deathstalkers d'élite pour éradiquer la source de la malédiction worgen. Les équipes d'infiltration ont essuyé de lourdes pertes dans les donjons, mais les héros de la Horde répondant à l'appel depuis Le Sépulcre finissent par investir la plus haute tour. Terrasser l'archimage met un terme définitif au règne du maître de la meute, anéantissant l'esprit qui orchestrait la propagation des bêtes à travers la région et permettant de réclamer sa tête en preuve de la vengeance de Lordaeron."}},faq={{q="Que se passe-t-il lorsque l'archimage Arugal est vaincu ?",a="Terrasser Arugal décapite la force centrale qui contrôle les meutes de worgens dans le sud de la Forêt des Pins-Argentés. Les aventuriers de la Horde apportent sa tête coupée à Dalar Tisselaube au Sépulcre, sur ordre de Dame Sylvanas Coursevent. Bien que sa mort brise la volonté directe guidant la meute d'Ombrecroc, les bêtes férales et les vestiges fantomatiques qui subsistent dans le donjon et les bois environnants demeurent un danger permanent pour les voyageurs.",al={"conséquences de la mort d'arugal","histoire de la mort d'arugal","que se passe-t-il après la mort d'arugal"}},{q="Pourquoi Arugal a-t-il invoqué les worgens ?",a="Durant la Troisième guerre, les armées de Dalaran subissaient des défaites désastreuses face au Fléau. Les mages déchus se relevaient continuellement sous la forme de soldats morts-vivants pour le Roi-liche. Cherchant une arme pour inverser la tendance, Arugal utilisa les recherches arcaniques du mage Ur afin d'invoquer des worgens extradimensionnels, convaincu que leur férocité pourrait arrêter le Fléau.",al={"pourquoi les worgens ont été invoqués","motivations d'arugal","invocation des worgens de dalaran"}},{q="Qui était le Baron d'Argelaine ?",a="Le Baron d'Argelaine était le noble humain qui dirigeait le donjon et veillait sur le hameau voisin de Bois-du-Bûcher avant la Troisième guerre. Lorsque les bêtes invoquées par Arugal échappèrent à tout contrôle, elles prirent la forteresse d'assaut et massacrèrent le baron, sa maisonnée et ses gardes. Le fantôme vengeur d'Argelaine hante toujours les grandes salles de banquet, maudit à errer aux côtés des monstres qui l'ont abattu.",al={"histoire du baron d'argelaine","seigneur originel d'ombrecroc"}},{q="Pourquoi les villageois de Bois-du-Bûcher sont-ils amicaux pendant la journée ?",a="Arugal a soumis les habitants du village voisin de Bois-du-Bûcher à sa magie sombre. Le jour, ils conservent leur forme humaine, leur esprit et une attitude pacifique envers les voyageurs de l'Alliance. Au coucher du soleil, la malédiction prend le dessus, transformant toute la population en féroces worgens loyaux envers le fou archimage retranché dans le donjon.",al={"humains de bois-du-bûcher","malédiction de bois-du-bûcher","pourquoi bois-du-bûcher se transforme en worgens"}},{q="Qui est le Commandant Printeval ?",a="Le Commandant Printeval était un paladin et l'officier militaire chargé de défendre le donjon d'Argelaine. Lorsque les worgens ont envahi la forteresse, il s'est battu jusqu'à la mort. Son esprit tourmenté patrouille toujours dans les couloirs supérieurs, s'accrochant à son devoir martial jusque dans la non-mort.",al={"histoire de printeval","boss paladin fantomatique"}},{q="Qu'est-ce que Le Livre d'Ur ?",a="Le Livre d'Ur est un tome renfermant les recherches d'Ur, un archimage de Dalaran qui étudiait les entités extradimensionnelles, notamment les worgens. Arugal s'est servi des écrits d'Ur pour accomplir ses désastreuses invocations. La Société royale des apothicaires de Fossoyeuse recherche ce livre pour percer la nature de ces créatures lupines et leur étrange magie.",al={"quête du livre d'ur","histoire d'ur"}}},fx={c6ee2849={q="Que sont les The Deathstalkers ?",a="Les The Deathstalkers sont les assassins et voleurs d'élite des Réprouvés. Spécialisés dans la furtivité, l'espionnage et la mort subite, ils agissent comme les lames silencieuses de Fossoyeuse sur les frontières de Lordaeron.",al={"qu'est-ce qu'un the deathstalker","qui sont les the deathstalkers","the deathstalkers réprouvés"}},["40c5e48b"]={q="À qui les The Deathstalkers rendent-ils des comptes ?",a="Ils obéissent à une stricte chaîne de commandement dirigée par des officiers et commandants Réprouvés postés sur tout le territoire, servant en fin de compte la volonté du conseil dirigeant de Fossoyeuse.",al={"commandement the deathstalkers","qui commande les the deathstalkers","qui dirige les the deathstalkers"}},["63a10ab0"]={q="Les The Deathstalkers travaillent-ils directement pour Sylvanas ?",a="Oui. Chaque The Deathstalker a prêté serment à la reine banshee, Dame Sylvanas Coursevent. Ils forment son réseau de renseignement personnel, traquant les menaces pesant sur ses morts-vivants dotés du libre arbitre à travers tout Lordaeron.",al={"les the deathstalkers servent-ils sylvanas","sylvanas et les the deathstalkers","the deathstalkers reine banshee"}},f68cd02f={q="Pourquoi tout le monde m'envoie-t-il au Donjon d'Ombrecroc ?",a="Parce que la reconnaissance initiale des Réprouvés a complètement échoué avec la capture de leurs The Deathstalkers d'élite. L'antre d'Arugal est trop dangereuse pour l'infanterie standard et nécessite des aventuriers chevronnés capables de se frayer un chemin parmi les bêtes et les esprits vengeurs.",al={"pourquoi m'envoyer à ombrecroc","pourquoi je fais ça","pourquoi un héros à ombrecroc"}},ebbfbfb0={q="Suis-je le seul à pouvoir le faire ?",a="Les ressources des Réprouvés dans la Forêt des Pins-Argentés sont au plus bas à cause des combats contre les gnolls Peau-de-Putréfaction, les poches de résistance du Fléau et les patrouilles de Dalaran. Leurs propres éclaireurs étant compromis, vous et vos alliés êtes la seule force capable de pénétrer dans le donjon.",al={"suis-je le seul","personne d'autre pour nettoyer ombrecroc","seul choix"}},["0f7e4add"]={q="D'autres ont-ils essayé de pénétrer dans le donjon avant moi ?",a="Oui. Au-delà des éclaireurs The Deathstalkers qui ont échoué, des enquêteurs du Kirin Tor, tel que le sorcier Ashcrombe, sont entrés dans le donjon pour évaluer Arugal, pour finir capturés ou piégés dans ses salles maudites.",al={"d'autres ont-ils essayé ombrecroc","tentatives précédentes ombrecroc","qui a essayé avant"}},["13386e7c"]={q="Qu'est-il arrivé à la Forêt des Pins-Argentés ?",a="La Forêt des Pins-Argentés était autrefois un royaume verdoyant de pins aux écorces argentées, protégé par l'Alliance. Lorsque le Fléau a déferlé sur Lordaeron pendant la Troisième guerre, la peste a flétri les bois, les récoltes ont été brûlées et ses habitants ont été massacrés ou chassés derrière Le mur de Greymane.",al={"histoire des pins-argentés","qu'est-il arrivé aux pins-argentés","pourquoi les pins-argentés sont comme ça"}},["7c8f83a0"]={q="La Forêt des Pins-Argentés faisait-elle partie de Lordaeron ?",a="Oui. La Forêt des Pins-Argentés formait la limite ouest accidentée du royaume de Lordaeron, bordant Gilnéas au sud. Ses domaines et ses colonies étaient liés à l'Alliance avant que la peste ne détruise le royaume.",al={"était-ce lordaeron","histoire de lordaeron aux pins-argentés","lordaeron possédait-il les pins-argentés"}},["91da6ffd"]={q="Pourquoi la Forêt des Pins-Argentés est-elle si déserte maintenant ?",a="Entre l'invasion du Fléau, la fermeture du grand mur de Gilnéas et la malédiction dévastatrice des worgens d'Arugal, la population vivante a été massacrée, maudite ou a fui à l'étranger. Les rares qui restent s'accrochent désespérément à des hameaux contestés comme Pyrewood.",al={"pourquoi les pins-argentés sont vides","pins-argentés désertés","pourquoi les ruines des pins-argentés"}},["2ee73ad9"]={q="Pourquoi Arugal a-t-il amené des worgens dans la Forêt des Pins-Argentés au départ ?",a="Lorsque le Fléau mort-vivant a marché vers le sud, les sorciers de Dalaran mouraient en masse, pour revenir à la vie au service du roi-liche. Arugal pensait que des alliés invoqués depuis une autre dimension pourraient submerger les morts-vivants là où les armées mortelles conventionnelles avaient échoué.",al={"pourquoi amener des worgens aux pins-argentés","raison de l'invocation des worgens par arugal","pourquoi invoquer des worgens ici"}},["671a79f5"]={q="Qui Arugal essayait-il d'arrêter ?",a="Il les a invoqués spécifiquement pour anéantir les armées de morts-vivants du Fléau, qui grossissaient en massacrant et en relevant chaque soldat et sorcier tombé au combat.",al={"qui arugal combattait-il","ennemi d'arugal","contre qui arugal a-t-il invoqué les worgens"}},eeb57b84={q="Le plan d'Arugal a-t-il fonctionné contre le Fléau ?",a="Tactiquement, oui : les worgens ont mis les morts-vivants en pièces sans effort. Mais stratégiquement, ce fut une catastrophe. Les loups-garous sauvages ne pouvaient pas être contrôlés, ils se sont retournés contre les soldats et les sorciers humains, et ont répandu une malédiction mortelle dans toute la région.",al={"les worgens ont-ils battu le fléau","l'invocation a-t-elle fonctionné","succès des worgens contre le fléau"}},["2bfe7e75"]={q="Les worgens du donjon sont-ils les mêmes que ceux qui ont envahi Pyrewood ?",a="Oui. Les meutes d'Arugal, y compris les meutes Shadowfang et Moonrage, partagent la même origine maudite. Les bêtes qui rôdent dans les couloirs du château sont la progéniture personnelle d'Arugal, étroitement liée à la malédiction qui afflige les villageois en contrebas.",al={"les worgens d'ombrecroc viennent-ils de pyrewood","worgens de pyrewood ombrecroc","même meute de worgens"}},b78b86f3={q="Qu'est-il arrivé aux villageois de Pyrewood ?",a="Les villageois ont survécu à la Troisième guerre pour finir piégés par la Shadow Magic d'Arugal. Bien qu'ils apparaissent comme des humains normaux à la lumière du jour, le coucher du soleil les transforme en worgens sauvages et sanguinaires fidèles à l'archimage fou.",al={"qu'est-il arrivé aux habitants de pyrewood","sort de pyrewood","villageois de pyrewood"}},["39fbc1b5"]={q="Les villageois de Pyrewood sont-ils maudits eux aussi ?",a="Oui. Ils sont victimes de la malédiction lycanthrope des worgens. Le jour, ils conservent leur esprit et commercent paisiblement avec les voyageurs de l'Alliance ; la nuit, la malédiction leur ôte leur humanité, les transformant en bêtes voraces.",al={"pyrewood est-elle maudite","malédiction de pyrewood","les villageois sont-ils infectés"}},d6e89a88={q="Qui sont les fantômes à l'intérieur du Donjon d'Ombrecroc ?",a="Ce sont les esprits agités du Baron d'Argelaine, du Commandant Printeval et de l'ancienne maisonnée du château. Tués lors de l'attaque surprise des worgens, leurs âmes restent liées aux pierres en ruine par le tourment et le chagrin.",al={"fantômes dans ombrecroc","qui sont les esprits à ombrecroc","spectres ombrecroc"}},["0a399272"]={q="Les fantômes sont-ils les anciens serviteurs du donjon ?",a="Oui. Des cuisiniers fantomatiques et des serviteurs spectraux aux anciens gardes, les défenseurs spectraux qui errent dans les couloirs sont les serviteurs massacrés qui servaient autrefois le Baron d'Argelaine de son vivant.",al={"les fantômes sont-ils d'anciens serviteurs","fantômes des serviteurs du château","serviteurs du baron d'argelaine"}},["3f532512"]={q="Pourquoi les fantômes ne peuvent-ils pas reposer en paix ?",a="L'horreur pure de leur massacre, combinée à la lourde Shadow Magic qui sature le donjon, empêche leur libération. Dans leur angoisse perpétuelle, ils s'attaquent avec une haine impie à tout intrus vivant qui dérange leurs tombes.",al={"pourquoi les fantômes sont agités","pourquoi les esprits hantent ombrecroc","agitation des fantômes ombrecroc"}},["59c03d52"]={q="Arugal travaille-t-il pour le Fléau ?",a="Non. Arugal méprise le Fléau ; il a invoqué les worgens précisément pour les détruire. Bien qu'il soit devenu fou, sa loyauté va à ses « enfants » plutôt qu'au roi-liche.",al={"arugal fait-il partie du fléau","arugal travaille-t-il pour le fléau","arugal sert-il le fléau"}},["99eb22e3"]={q="Le roi-liche contrôle-t-il Arugal ?",a="Non. La folie d'Arugal est entièrement auto-infligée, née de la culpabilité et de la magie planaire plutôt que de l'emprise télépathique du Trône de glace. Il opère indépendamment en tant que maître de son propre domaine sombre.",al={"le roi-liche contrôle-t-il arugal","roi-liche arugal","contrôle mental arugal"}},["4bfedcc6"]={q="Qu'est-ce que le Donjon d'Ombrecroc ?",a="Le Donjon d'Ombrecroc est un château hanté perché sur les hautes falaises du sud de la Forêt des Pins-Argentés, surplombant Bois-du-Bûcher. Connu à l'origine sous le nom de donjon d'Argelaine, il servait autrefois de bastion de l'Alliance protégeant les frontières près de Gilnéas. Aujourd'hui, il est corrompu et enveloppé de brumes sombres, servant de forteresse à l'archimage Arugal et à sa progéniture worgen sauvage.",al={"qu'est-ce que le donjon d'ombrecroc","parle-moi du donjon d'ombrecroc","lore du donjon d'ombrecroc"}},["1d3b32c5"]={q="Qui a construit le Donjon d'Ombrecroc ?",a="La forteresse était le siège du Baron d'Argelaine, un noble dont la famille a longtemps exercé sa seigneurie sur les terres environnantes et Bois-du-Bûcher avant la Troisième guerre. Sous son règne, c'était un fier bastion humain, gardé par le Commandant Printeval et les soldats jurés du royaume.",al={"qui a construit le donjon d'ombrecroc","origine du donjon d'ombrecroc","qui a créé le donjon d'ombrecroc"}},efb02893={q="Pourquoi le Donjon d'Ombrecroc est-il rempli de worgens ?",a="Lorsque les worgens invoqués se sont libérés du contrôle du Kirin Tor, ils ont saccagé la forêt et assiégé le château. Ils ont massacré le Baron d'Argelaine et sa maisonnée. Devenu fou de culpabilité pour ce qu'il avait libéré, l'archimage Arugal a adopté les bêtes comme ses propres « enfants », a revendiqué la ruine pour lui-même et l'a rebaptisée Donjon d'Ombrecroc.",al={"pourquoi y a-t-il des worgens ici","pourquoi des worgens au donjon d'ombrecroc","pourquoi des worgens à l'intérieur"}},["7d419eb0"]={q="Pourquoi la Horde s'intéresse-t-elle à ce château ?",a="Les worgens qui rôdent hors du donjon sont une peste incontrôlée menaçant l'emprise des Réprouvés sur la Forêt des Pins-Argentés. Depuis leur base au Sépulcre, les chefs Réprouvés ont réalisé que tant qu'Arugal commande ses horreurs lupines depuis les hauteurs du château, les terres environnantes ne seront jamais en sécurité.",al={"pourquoi la horde s'intéresse-t-elle au donjon d'ombrecroc","intérêt de la horde pour le donjon d'ombrecroc","pourquoi venir au donjon d'ombrecroc"}},d6cbfc07={q="Qui m'a envoyé ici ?",a="Les commandants Réprouvés au Sépulcre ont ordonné l'assaut pour éliminer Arugal et découvrir le sort de leurs éclaireurs disparus. Pendant ce temps, la Société royale des apothicaires à Fossoyeuse a envoyé des agents pour récupérer les recherches magiques d'Ur dans la bibliothèque de l'archimage.",al={"qui m'a envoyé au donjon d'ombrecroc","donneur de quête du donjon d'ombrecroc","qui veut la mort d'arugal"}},a794fece={q="Est-ce une terre Réprouvée maintenant ?",a="Les Réprouvés revendiquent le nord de la Forêt des Pins-Argentés, mais leur emprise sur le sud est vivement contestée. Le Donjon d'Ombrecroc reste fermement sous la domination d'Arugal, tandis que des restes du Fléau, des bêtes sauvages et des colonies humaines survivantes contestent le règne de la Dame noire sur toute la région.",al={"la forêt des pins-argentés est-elle une terre réprouvée","est-ce que sylvanas possède ceci","territoire réprouvé du donjon d'ombrecroc"}},b918d1de={q="Qui est aux commandes au Donjon d'Ombrecroc ?",a="Le château répond entièrement à l'archimage Arugal. Devenu fou à cause de la Troisième guerre, il règne sur les tours supérieures, flanqué de ses worgens monstrueux et de son énorme worg de compagnie, Fenrus, commandant le donjon par la magie noire.",al={"qui dirige le donjon d'ombrecroc","qui est aux commandes à l'intérieur","maître du donjon d'ombrecroc"}},ecad974c={q="Arugal est-il le boss du donjon ?",a="Oui. Arugal est le maître du Donjon d'Ombrecroc. Il orchestre l'infestation worgen dans la Forêt des Pins-Argentés et siège au sommet de la tour du donjon en tant qu'autorité ultime.",al={"arugal est-il le boss","boss final du donjon d'ombrecroc","maître arugal"}},["3b086809"]={q="Y avait-il quelqu'un aux commandes avant lui ?",a="Le Baron d'Argelaine dirigeait le donjon quand c'était une redoute de l'Alliance. Lui et sa famille ont gouverné le château jusqu'à ce que les worgens d'Arugal franchissent les murs et massacrent tout le monde à l'intérieur pendant la Troisième guerre.",al={"qui dirigeait avant arugal","précédent maître du donjon d'ombrecroc","ancien seigneur du donjon"}},["7f02160f"]={q="D'où viennent les worgens ?",a="Ce sont des êtres extra-dimensionnels voraces arrachés à un autre plan. Désespéré d'arrêter le Fléau pendant la Troisième guerre, Arugal s'est tourné vers les recherches interdites du mage de Dalaran Ur et a invoqué ces bêtes d'un autre monde en Azeroth.",al={"d'où viennent les worgens","origine des worgens","source des worgens"}},["4fa8e666"]={q="Arugal a-t-il invoqué les worgens seul ?",a="Arugal a effectué l'invocation contre l'avis explicite de ses pairs du Kirin Tor de Dalaran. S'appuyant fortement sur les écrits du Livre d'Ur, il a forcé les entités à traverser les frontières planaires.",al={"arugal a-t-il agi seul","qui a aidé à invoquer les worgens","invocation d'arugal"}},a6a018be={q="Les worgens peuvent-ils être contrôlés ?",a="À peine, et seulement par la magie noire. Bien qu'invoqués pour servir d'alliés contre les morts-vivants, ils se sont immédiatement retournés contre leurs invocateurs. Arugal ne parvient à en diriger certains que parce que son esprit brisé les traite comme sa famille, utilisant des enchantements pour imposer une obéissance fragile.",al={"les worgens peuvent-ils être contrôlés","contrôler les worgens","les worgens sont-ils apprivoisés"}},["24ed31c3"]={q="Qu'est-il arrivé aux The Deathstalkers Adamant et Vincent ?",a="The Deathstalkers Adamant et Vincent se sont glissés dans le Donjon d'Ombrecroc sur ordre du Sépulcre pour évaluer la force d'Arugal. Ils ont été capturés par les défenseurs du donjon ; Vincent a été emprisonné et exécuté dans la cour, tandis qu'Adamant est piégé dans les cachots en attendant d'être secouru.",al={"adamant et vincent","qu'est-il arrivé aux the deathstalkers","éclaireurs réprouvés au donjon d'ombrecroc"}},cc7bdeae={q="Pourquoi les The Deathstalkers ont-ils été envoyés dans le Donjon d'Ombrecroc ?",a="Le commandement Réprouvé avait besoin de renseignements précis sur l'infestation bestiale menaçant leur front sud. Adamant et Vincent ont été chargés d'infiltrer le donjon, de déterminer les effectifs réels d'Arugal et de préparer le terrain pour une frappe décisive.",al={"pourquoi envoyer des the deathstalkers","repérage du donjon d'ombrecroc","mission des the deathstalkers"}},["4cfa60a4"]={q="Les The Deathstalkers sont-ils toujours en vie ?",a="Vincent est mort, tué après sa capture. Adamant, cependant, reste emprisonné au fond des cellules inférieures du donjon, assez vivant pour aider tout aventurier de la Horde qui parviendra jusqu'à lui.",al={"vincent et adamant sont-ils en vie","les the deathstalkers ont-ils survécu","sort des the deathstalkers"}},["501c4a9b"]={q="La malédiction prend-elle fin après la mort d'Arugal ?",a="Non. Abattre Arugal décapite la direction du Donjon d'Ombrecroc, mais la malédiction des worgens a déjà infecté le sang des mortels à travers toute la forêt. L'affliction persiste bien après la chute de l'archimage.",al={"la malédiction worgen prend-elle fin","la malédiction worgen va-t-elle disparaître","bois-du-bûcher est-il guéri"}},["6cb01af1"]={q="Les Réprouvés prendront-ils le Donjon d'Ombrecroc ?",a="Pour l'heure, les Réprouvés se contentent d'éliminer la menace qui pèse sur leur frontière sud et de récupérer le Livre d'Ur. La ruine demeure une sinistre coquille hantée surplombant les bois plutôt qu'un avant-poste garni.",al={"les réprouvés prendront-ils ombrecroc","les réprouvés capturent-ils ombrecroc","qui contrôle le donjon après"}},["3f22b397"]={q="Comment ai-je fini au Donjon d'Ombrecroc ?",a="Vous avez suivi la trace de terreur à travers la Forêt des Pins-Argentés jusqu'aux falaises surplombant Bois-du-Bûcher. Si vous servez la Horde, vous avez probablement été envoyé au sud depuis Le Sépulcre ou Fossoyeuse pour enquêter sur la menace worgen qui étouffe la région. Si vous vous battez pour l'Alliance, les rumeurs sur les bois maudits, les reliques sacrées perdues ou la chute du Kirin Tor vous ont mené au cœur du territoire hostile des Réprouvés. En gravissant les escarpements sinueux au-delà des portes de Bois-du-Bûcher, vous avez dépassé des bêtes-loups voraces et forcé l'antique entrée du donjon pour pénétrer dans l'antre de l'archimage fou.",al={"comment suis-je arrivé ici","comment atteindre le donjon d'ombrecroc","comment ai-je trouvé cet endroit"}},["31a8c552"]={q="Que suis-je censé faire au Donjon d'Ombrecroc ?",a="Votre objectif ultime est de combattre à travers les salles hantées et d'abattre l'archimage Arugal, mettant fin à son règne corrompu sur la Forêt des Pins-Argentés. En chemin, vous devez occire les worgens qui traquent dans les cours et apaiser les esprits agités du Baron d'Argelaine et des membres de sa maisonnée massacrés. Si vous agissez au nom des Réprouvés, vous êtes chargé de récupérer le Livre d'Ur et de découvrir le sort des Traque-morts portés disparus à l'intérieur. Les champions, paladins et démonistes de l'Alliance recherchent des artefacts de pouvoir perdus, des armements sacrés et veulent obtenir réparation contre la magie noire qui empoisonne la terre.",al={"que fais-je ici","pourquoi suis-je ici","quel est mon but au donjon d'ombrecroc"}}},fp="15,249,31.608.0,17.575.0,19.531.1,46.300.1,33.314.0,26.353.0,59.258.0,28.263.0,23.300.0"}
P.entries["zone:shendralas"] = {n="Shen’dralas",s="Shen’dralas est une contrée sauvage, escarpée et disputée, située entre Féralas, Mulgore et le sud-est de Désolace. Dominée par d'anciens vestiges elfiques de la nuit et des frontières troublées, elle sert de carrefour instable où se heurtent centaures envahisseurs, renégats déplacés et hérissards menaçants.",h="Shen’dralas est une contrée sauvage, escarpée et disputée, située entre Féralas, Mulgore et le sud-est de...",kw={"retraite des dos-hirsute","désolace","evenshade overlook","féralas","lake dumont","front des magram","mulgore","planque des renégats","shendralas","vallée des ossements"},ang={["faction:Alliance"]="Une étendue sauvage reculée et disputée, offrant des routes alternatives entre Féralas et le centre de Kalimdor, semée de périls qui exigent une vigilance constante.",["faction:Horde"]="Situé juste à l'extérieur des confins méridionaux de Mulgore, contenir les Magram et les hérissards dans cette région est vital pour protéger les frontières de la Horde.",["race:NightElf"]="Ce nom évoque les traditions anciennes des Bien-nés d'Eldre'Thalas, attirant l'attention des sentinelles méfiantes envers les arcanes incontrôlées dans le sud de Kalimdor.",["race:Tauren"]="La région bordant Mulgore et Désolace, l'agressivité des hérissards et des centaures le long de ces crêtes représente une menace directe pour les terrains de chasse ancestraux voisins."},sec={{t="Une frontière en plein tumulte",b="Nichée sur les hauteurs au sud-est de Désolace et bordée par Mulgore et Féralas, Shen’dralas est une zone frontalière brute, très éloignée des capitales des grandes factions. Ses cols escarpés et ses enclaves secrètes abritent des groupes désespérés qui tentent de survivre en marge des terres sauvages de Kalimdor. Des points de vue isolés comme Evenshade Overlook aux refuges sans foi ni loi comme la Planque des renégats, la zone est définie par ceux qui souhaitent observer sans être vus ou rester oubliés."},{t="Centaures, hérissards et ruines antiques",b="La région porte l'empreinte distincte de l'héritage bien-né qui lui a donné son nom, mais elle est loin d'être paisible. Les conflits des centaures débordent à travers le Front des Magram, maintenant de vieilles vendettas bien vivantes le long de ses frontières. Dans le même temps, des hérissards conquérants tiennent des redoutes fortifiées comme la Retraite des Dos-hirsute, transformant chaque ravin ombragé en territoire contesté pour tout voyageur de passage."},{t="La Vallée des Ossements",b="S'ouvrant au nord-ouest vers Désolace s'étend la Vallée des Ossements, un sinistre couloir qui sert de principale voie d'accès terrestre à Shen’dralas. Blanchi par le soleil et le vent, ce passage rappelle brutalement les luttes violentes qui agitent continuellement ces crêtes."}},faq={{q="Où se trouve Shen’dralas ?",a="Shen’dralas se trouve au sud-est de Désolace, nichée entre les frontières de Féralas et de Mulgore. Les voyageurs arrivant à pied y pénètrent généralement depuis Désolace en passant par la Vallée des Ossements.",al={"où se trouve shendralas","emplacement de shendralas","comment aller à shendralas"}},{q="Shen’dralas est-elle contrôlée par l'Alliance ou la Horde ?",a="Aucune faction n'y exerce son autorité. Shen’dralas est une frontière disputée, peuplée de centaures errants, d'hérissards hostiles, de renégats et de campements isolés.",al={"shendralas est-elle horde","shendralas est-elle alliance","à qui appartient shendralas"}},{q="Quels sont les lieux d'intérêt ou colonies majeurs ici ?",a="Parmi les points de repère notables figurent la Vallée des Ossements, la Retraite des Dos-hirsute, Evenshade Overlook, le Front des Magram, la Planque des renégats et l'étendue centrale de Shen’dralas elle-même.",al={"sous-zones de shendralas","points de repère à shendralas","points d'intérêt à shendralas"}},{q="Pourquoi y a-t-il des centaures ici ?",a="Les guerres de territoire des centaures s'étendent des plaines de Désolace jusqu'à cette région le long du Front des Magram, où le clan affronte les défenseurs locaux et les factions rivales.",al={"centaures à shendralas","front des magram","pourquoi les magram sont-ils là"}},{q="Qu'est-ce que la Retraite des Dos-hirsute ?",a="La Retraite des Dos-hirsute est un avant-poste fortifié tenu par les hérissards Dos-hirsute, qui ont établi un solide point d'ancrage le long des limites de la zone.",al={"retraite des dos-hirsute","hérissards à shendralas"}},{q="Quel est le lien entre cette zone et Lake Dumont ?",a="Géographiquement, les étendues sauvages de Shen’dralas s'étendent sur le territoire montagneux où le Lake Dumont, isolé, figure sur d'anciennes cartes d'arpentage.",al={"lake dumont","histoire de la carte de shendralas"}}},fp="11,141,23.322.0,36.313.0,19.222.0,29.144.0,55.152.0,45.155.0,27.159.0,28.132.0,57.115.0"}
P.entries["zone:silithus"] = {n="Silithus",s="Silithus est un désert désolé, balayé par les vents, situé dans l'extrême sud-ouest de Kalimdor. Sous ses sables arides reposent de vastes colonies de silithides insectoïdes et les anciennes ruines d'Ahn'Qiraj, scellées il y a un millénaire derrière le Mur du scarabée. Aujourd'hui, les druides du Cercle cénarien maintiennent une veille acharnée contre les nuées rampantes et les cultistes apocalyptiques.",h="Silithus est un désert désolé, balayé par les vents, situé dans l'extrême sud-ouest de Kalimdor.",kw={"ahn'qiraj","fort cénarien","ruche'ashi","ruche'regal","ruche'zora","l'estrade du scarabée","le mur du scarabée","silithide","silithus","marteau du crépuscule"},ang={["class:Druid"]="En tant que centre des opérations du Cercle cénarien dans le sud de Kalimdor, Silithus appelle les druides à stopper la corruption de la terre et à affronter les couvées contre-nature qui menacent l'équilibre de la nature.",["profession:Herbalism"]="Malgré le terrain désertique hostile, des merveilles botaniques rares y prospèrent, notamment la Sauge-argent des montagnes, le Feuillerêve, la Soleillette et le très prisé Lotus noir.",["profession:Mining"]="Les roches arides et les tunnels d'insectes de Silithus abritent certains des gisements de thorium les plus riches au monde, y compris des filons rares recouverts de limon cachés à l'intérieur des ruches silithides.",["race:NightElf"]="Silithus est le sinistre champ de repos où vos ancêtres ont versé leur sang durant la guerre des sables changeants, sacrifiant des milliers de vies pour sceller les portes d'Ahn'Qiraj."},sec={{t="La frontière du désert",b="Pour atteindre Silithus, vous devez traverser la jungle primitive du Cratère d'Un'Goro et gravir un large col rocheux niché dans son coin nord-ouest. La transition est saisissante : la végétation primordiale luxuriante laisse place à une vaste étendue de dunes mouvantes, de pierres déchiquetées et de ruches imposantes contre-nature. L'eau y est pratiquement inexistante, et les vents portent le bourdonnement d'ailes d'insectes et le murmure des sables. Le Cercle cénarien entretient le Fort cénarien près du centre du désert, servant de seul bastion de civilisation et de refuge pour les voyageurs, les chercheurs et les guerriers qui bravent ces terres hostiles."},{t="Échos des sables changeants",b="Il y a mille ans, cette étendue aride a servi de champ de bataille pour la guerre des sables changeants. Une armée alliée d'elfes de la nuit et de grands dragons a lutté désespérément pour repousser les Qiraji, un empire insectoïde insidieux né de l'ancienne civilisation Aqiri. Lorsqu'une victoire totale s'est révélée impossible, les défenseurs ont enfermé les nuées dans leur bastion en utilisant le Mur du scarabée et l'Estrade du scarabée enchantée. Bien que les portes monumentales aient tenu, des tunnels souterrains ont permis aux silithides bestiaux de creuser vers l'extérieur, établissant des colonies tentaculaires telles que Ruche'Ashi, Ruche'Zora et Ruche'Regal à travers les sables."},{t="Une tempête convergente",b="Le culte apocalyptique du Marteau du crépuscule s'est retranché dans plusieurs avant-postes fortifiés, invoquant des terreurs élémentaires et vénérant la puissance obscure qui sommeille sous Ahn'Qiraj. Les observateurs du Cercle cénarien surveillent la prolifération des colonies de silithides dans le désert et l'ancienne menace derrière le Mur du scarabée."}},faq={{q="Comment se rendre à Silithus à pied ?",a="Rendez-vous dans le coin nord-ouest du Cratère d'Un'Goro. Près du méandre de la rivière, entre deux piliers de pierre naturels proéminents, un chemin de terre incliné mène à travers la paroi montagneuse du cratère, directement dans le désert de Silithus.",al={"entrée de silithus","comment aller à silithus","chemin vers silithus"}},{q="Qu'est-ce que le Mur du scarabée ?",a="Le Mur du scarabée est une immense barrière enchantée située au sud de Silithus. Il a été érigé il y a mille ans par les elfes de la nuit et les dragons durant la guerre des sables changeants pour emprisonner l'empire malveillant des Qiraji au sein d'Ahn'Qiraj.",al={"porte d'ahn'qiraj","le mur du scarabée","le grand mur de silithus"}},{q="Qui dirige le Fort cénarien ?",a="Le Fort cénarien est un avant-poste établi et dirigé par le Cercle cénarien. Ses druides et gardiens alliés observent les nuées de silithides envahissantes, étudient les ruines anciennes et accueillent les voyageurs neutres de l'Alliance comme de la Horde.",al={"qui est au fort cénarien","faction du fort cénarien","fort cénarien amical"}},{q="Que sont ces monticules d'insectes géants dans toute la zone ?",a="Il s'agit des principales ruches souterraines des silithides : Ruche'Ashi, Ruche'Zora et Ruche'Regal. Chaque ruche est un réseau tentaculaire de tunnels abritant des castes distinctes de créatures insectoïdes au service des volontés enfermées derrière Ahn'Qiraj.",al={"ruches de silithus","ruches d'insectes silithus","ruche'ashi ruche'zora"}},{q="Que fait le Marteau du crépuscule ici ?",a="Le culte du Marteau du crépuscule maintient plusieurs bases fortifiées à Silithus, notamment le Campement du crépuscule et le Poste du Crépuscule. Ils pratiquent des rituels impies pour invoquer des élémentaires et vénèrent les anciennes entités malveillantes enterrées derrière le Mur du scarabée.",al={"cultistes du crépuscule silithus","avant-poste du crépuscule silithus","pourquoi le marteau du crépuscule est à silithus"}}},fp="8,245,19.408.0,28.509.0,18.272.0,33.207.0,24.219.0,23.205.0,49.212.0,41.243.0"}
P.entries["zone:silverpine"] = {n="Forêt des Pins-Argentés",s="La Forêt des Pins-Argentés est une forêt étrange, chargée de brume, qui s'étend le long de la côte occidentale de Lordaeron, entre les Clairières de Tirisfal et le mur de Grisetête scellé. Hantée par les stigmates persistants de la peste du Fléau, elle sert de frontière sud contestée aux Réprouvés. Les voyageurs y affrontent des worgens sauvages errant dans les ombres, des gnolls malades et des enclaves d'Humains hostiles.",h="La Forêt des Pins-Argentés est une forêt étrange, chargée de brume, qui s'étend le long de la côte...",kw={"moulin-de-l'ambre","arugal","ile de fenris","le mur de grisetête","bois-du-bûcher","rot hide","le sépulcre","donjon d'ombrecroc","forêt des pins-argentés"},ang={["class:Mage"]="La présence de Moulin-de-l'Ambre et la chute de l'archimage Arugal dans la folie lupine font de la Forêt des Pins-Argentés une sombre mise en garde contre la magie du Kirin Tor ayant désastreusement tourné court.",["faction:Alliance"]="Les explorateurs de l'Alliance découvriront une forêt profondément hostile, ponctuée seulement par une fragile garnison de Dalaran à Moulin-de-l'Ambre et par les villageois tragiques et maudits de Bois-du-Bûcher.",["race:Undead"]="La Forêt des Pins-Argentés représente la ligne de front immédiate de l'expansion des Réprouvés au sud des Clairières de Tirisfal, où la Société royale des apothicaires teste de nouvelles concoctions et où la Deathguard combat les agents résiduels du Fléau."},sec={{t="Une frontière hantée",b="Autrefois célébrée comme une merveille luxuriante de Lordaeron à travers laquelle les nobles voyageurs se rendaient à Capital City, la Forêt des Pins-Argentés a dépéri sous l'effet de la Troisième guerre. Des brouillards fantomatiques serpentent entre des pins mourants à l'écorce argentée, et des fermes en ruine gisent abandonnées à la nature sauvage. Au nord se trouvent les Clairières de Tirisfal, tandis que la rive orientale borde le Lac Lordamere. Au sud se dresse l'imposant mur de Grisetête fermé, isolant le royaume isolationniste de Gilnéas du chaos environnant. Les Réprouvés maintiennent leur avant-poste central au Sépulcre, s'efforçant de sécuriser les bois contre des ennemis venant de toutes parts."},{t="Enclaves rivales et le Fléau",b="La revendication de la Forêt des Pins-Argentés par les Réprouvés est âprement disputée par des factions de vivants tout comme de Morts-vivants. À l'est, sur l'Ile de Fenris, Thule Ravenclaw mène une force de vestiges du Fléau tout en commandant aux gnolls Rot Hide rongés par la peste qui infestent les terres agricoles du nord. Au sud, des mages humains de Dalaran tiennent la colonie fortifiée de Moulin-de-l'Ambre, menant des recherches mystiques et s'opposant à l'expansion des Réprouvés. La Société royale des apothicaires et le Grand exécuteur Hadrec au Sépulcre mènent une campagne brutale et multiforme pour éliminer ces menaces et tester de nouvelles pestes virulentes."},{t="Les worgens et Ombrecroc",b="Le péril le plus tristement célèbre de la Forêt des Pins-Argentés est la malédiction des worgens. Bien au-dessus des bois du sud-ouest se dresse le Donjon d'Ombrecroc, l'ancien siège du Baron d'Argelaine, désormais dominé par l'archimage fou de Dalaran, Arugal. Cherchant à repousser le Fléau pendant la Troisième guerre, Arugal a invoqué des bêtes-loups extradimensionnelles. Les créatures se sont retournées contre leurs invocateurs, propageant une malédiction lycanthropique à travers les bois méridionaux. À Bois-du-Bûcher, des villageois humains d'apparence ordinaire vaquent à leurs occupations le jour, mais se transforment en worgens sauvages sous le ciel nocturne."}},faq={{q="Qu'est-ce que le mur de Grisetête à la frontière sud ?",a="Le mur de Grisetête est une imposante barrière de pierre bâtie par le roi Genn Grisetête afin d'isoler totalement son royaume de Gilnéas du reste de Lordaeron. Lorsque le Fléau a ravagé le continent pendant la Troisième guerre, Gilnéas a verrouillé ses portes et refusé toute aide extérieure, laissant les terres situées au nord du mur — y compris le sud de la Forêt des Pins-Argentés — livrées à elles-mêmes.",al={"pourquoi y a-t-il un mur géant","histoire du mur de grisetête","porte vers gilnéas"}},{q="Pourquoi les villageois de Bois-du-Bûcher attaquent-ils la nuit ?",a="Les habitants de Bois-du-Bûcher souffrent de la malédiction worgen de l'archimage Arugal. De jour, ils conservent une forme humaine et poursuivent leurs routines quotidiennes, restant amicaux envers l'Alliance. Lorsque la lune se lève, la malédiction prend le dessus, transformant l'ensemble de la population en worgens sauvages et sanguinaires qui attaquent violemment quiconque s'approche.",al={"mystère de bois-du-bûcher","worgens de bois-du-bûcher","pourquoi les humains de bois-du-bûcher sont hostiles la nuit"}},{q="Qui est Thule Ravenclaw ?",a="Thule Ravenclaw est un puissant nécromancien au service du Fléau. Opérant depuis le Donjon de Fenris sur l'Ile de Fenris au sein du Lac Lordamere, il commande des légions de Morts-vivants et exerce son influence sur les gnolls malades Rot Hide à travers l'est de la Forêt des Pins-Argentés, menaçant directement le flanc est des Réprouvés.",al={"qui dirige l'ile de fenris","histoire de thule ravenclaw","le fléau sur l'ile de fenris"}},{q="Pourquoi Dalaran occupe-t-elle Moulin-de-l'Ambre ?",a="Moulin-de-l'Ambre est tenue par des sorciers de Dalaran dirigés par l'archimage Ataeric. Opérant depuis le village, ces mages humains surveillent les mouvements des Réprouvés, étudient les afflictions magiques qui frappent la forêt et cherchent à contenir la flambée voisine de worgens rayonnant depuis le Donjon d'Ombrecroc.",al={"mages de moulin-de-l'ambre","pourquoi l'alliance est à moulin-de-l'ambre","dalaran dans les forêt des pins-argentés"}},{q="Qu'est-ce que le Sépulcre ?",a="Le Sépulcre est le principal avant-poste militaire et carrefour de voyage des Réprouvés dans la Forêt des Pins-Argentés. Sous le commandement du Grand exécuteur Hadrec, il sert de base d'opérations pour les patrouilles de la Deathguard, les éclaireurs de la Deathstalker et la Société royale des apothicaires alors qu'ils luttent pour sécuriser la forêt.",al={"ville de la horde dans les forêt des pins-argentés","où se trouve la trajectoire de vol","histoire du sépulcre"}},{q="Les joueurs de l'Alliance peuvent-ils accomplir des quêtes dans la Forêt des Pins-Argentés ?",a="La Forêt des Pins-Argentés ne possède aucun centre de quêtes ni aucune ville amicale de l'Alliance ; toutes les quêtes locales sont réservées exclusivement à la Horde. Les aventuriers de l'Alliance n'entrent généralement dans la forêt que lorsqu'ils voyagent depuis Austrivage pour explorer le Donjon d'Ombrecroc ou pour combattre les forces hostiles des Réprouvés.",al={"la forêt des pins-argentés est-elle réservée à la horde","quêtes de l'alliance dans la forêt des pins-argentés","l'alliance peut-elle aller dans la forêt des pins-argentés"}}},fx={bd044bca={q="Pourquoi Hadrec veut-il lancer un assault sur l'Ile de Fenris ?",a="Hadrec reconnaît que l'Ile de Fenris est le cœur battant de la menace du Fléau dans l'est de la Forêt des Pins-Argentés. Laisser Thule Ravenclaw retranché dans le Donjon de Fenris donne au Fléau une base d'opérations inattaquable pour lever des gnolls morts-vivants, piller les caravanes de ravitaillement et menacer l'approche orientale des Clairières de Tirisfal. Frapper l'île est crucial pour briser le pouvoir de Thule et sécuriser le lac.",al={"pourquoi attaquer l'ile de fenris","motif d'hadrec pour l'ile de fenris","raison de l'assaut sur l'ile de fenris"}},["574e415e"]={q="Les mages de Dalaran à Moulin-de-l'Ambre travaillent-ils avec l'Alliance ?",a="Oui. Alors que Dalaran se concentre principalement sur la reconstruction de sa cité dévastée, les forces du Kirin Tor stationnées à Moulin-de-l'Ambre restent ouvertement amicales envers l'Alliance et farouchement hostiles à la Horde. Dalaran envoie fréquemment de l'aide aux enclaves humaines survivantes de la Forêt des Pins-Argentés, s'opposant à l'expansion des Réprouvés et travaillant en étroite collaboration avec les restes du sud.",al={"dalaran alliance moulin-de-l'ambre","dalaran est-il avec l'alliance ici","kirin tor alliance pins-argentés"}},fd7851b2={q="Qui est Arugal et qu'est-ce que « la Folie d'Arugal » ?",a="L'archimage Arugal était un mage de Dalaran qui, désespéré de devoir se défendre contre le Fléau pendant la troisième guerre, se tourna vers la magie interdite et invoqua des bêtes-loups monstrueuses connues sous le nom de worgens. Cependant, les bêtes sauvages se retournèrent contre les mages du Kirin Tor et les habitants innocents, propageant une malédiction lycanthropique dévorante à travers le sud de la Forêt des Pins-Argentés. Devenu fou de culpabilité et d'horreur face à ce qu'il avait libéré, Arugal se retira dans le Donjon d'Ombrecroc, adoptant les worgens comme ses « enfants ».",al={"arugal","folie d'arugal","qui était arugal","lore archimage arugal"}},f38b73fd={q="D'où viennent les worgens ?",a="Les worgens sont des bêtes-loups d'un autre monde, attirées à travers les dimensions par l'archimage Arugal. Cherchant une arme pour renforcer Dalaran contre le Fléau pendant la troisième guerre, Arugal conjura ces créatures dans la Forêt des Pins-Argentés, où elles se retournèrent rapidement contre leurs invocateurs et répandirent une malédiction transformatrice.",al={"d'où viennent les worgens","origine des worgens pins-argentés","comment les worgens sont arrivés ici"}},fc903f13={q="Arugal est-il toujours en vie ?",a="Oui, l'archimage Arugal est bien vivant. Enveloppé dans la folie, il réside au sommet des tours du Donjon d'Ombrecroc, surplombant le Bois-du-Bûcher. Depuis sa forteresse, il dirige sa meute de worgens d'Ombrecroc et garde son domaine lupin torturé contre quiconque est assez audacieux pour forcer ses portes.",al={"arugal est-il vivant","où est arugal maintenant","statut d'arugal"}},["5dc043c6"]={q="Qu'est-ce que le Bois-du-Bûcher ?",a="Le Bois-du-Bûcher est une colonie humaine nichée dans le sud-ouest de la Forêt des Pins-Argentés, directement sous les falaises imposantes du Donjon d'Ombrecroc. Elle fut laissée à l'extérieur lorsque Gilnéas scella le mur de Greymane avant la troisième guerre. Ses habitants survivants luttent pour maintenir une apparence de vie normale pendant la journée, bien qu'une obscurité ancienne les consume une fois le soleil couché.",al={"lore du bois-du-bûcher","qu'est-ce que le bois-du-bûcher","ville du bois-du-bûcher"}},["20eec241"]={q="Où tout cela mène-t-il après la Forêt des Pins-Argentés ?",a="Une fois que vous avez stabilisé la Forêt des Pins-Argentés en affrontant Thule Ravenclaw et en purgeant Arugal dans le Donjon d'Ombrecroc, votre périple vous mène généralement vers l'est, à travers les montagnes, dans les Contreforts de Hautebrande pour soutenir les Réprouvés au Moulin-de-Tarren. Alternativement, de nombreux voyageurs de la Horde prennent un zeppelin vers Kalimdor pour faire campagne à travers les vastes plaines des Tarides.",al={"où aller après les pins-argentés","prochaine zone après les pins-argentés","prochaine étape pins-argentés"}},da147569={q="Comment ai-je fini dans la Forêt des Pins-Argentés ?",a="Vous avez probablement suivi la route vers le sud depuis les Clairières de Tirisfal, en passant par le col de montagne au sud-ouest des ruines de Fossoyeuse. Les Réprouvés terminent de sécuriser leur foyer septentrional à Tirisfal et poussent naturellement vers le sud dans la Forêt des Pins-Argentés pour étendre leur empire naissant. Alternativement, les voyageurs de la Horde venant d'autres continents arrivent via zeppelin à l'extérieur de Fossoyeuse avant de descendre la côte, tandis que les rares aventuriers venant du sud pourraient traverser les Contreforts de Hautebrande pour atteindre ces bois dévastés.",al={"comment suis-je arrivé ici","comment atteindre la forêt des pins-argentés","chemin vers la forêt des pins-argentés"}},["97a9302a"]={q="Que suis-je censé faire dans la Forêt des Pins-Argentés ?",a="Vous êtes ici pour aider les Réprouvés à sécuriser leur frontière sud contre des périls croissants. En vous présentant au Grand exécuteur Hadrec et aux The Deathstalkers au Sépulcre, vous devez contrer les gnolls Rot Hide malades qui pillent depuis The Dead Fields et l'Ile de Fenris, débusquer les nécromanciens du Fléau comme Thule Ravenclaw, et surveiller de près les mages de Dalaran retranchés à Moulin-de-l'Ambre. Plus au sud, vous enquêterez également sur les bêtes-loups dévorantes qui terrorisent le Bois-du-Bûcher et sur l'ombre projetée par le Donjon d'Ombrecroc.",al={"quelle est ma mission ici","pourquoi ai-je été envoyé dans les pins-argentés","que faisons-nous dans la forêt des pins-argentés"}},["21fc6836"]={q="Qu'est-ce que la Forêt des Pins-Argentés ?",a="La Forêt des Pins-Argentés est une vaste et ancienne région boisée le long de la côte ouest accidentée de Lordaeron, située directement au sud des Clairières de Tirisfal et bordée à l'est par le Lac Lordamere. Jadis un bois luxuriant et verdoyant protégé par l'Alliance, il est aujourd'hui enveloppé de brumes fantomatiques, de pins au teint maladif et d'un silence étrange, seulement rompu par des hurlements lointains. Les Réprouvés dominent le nord depuis Le Sépulcre, mais leur revendication est constamment contestée par les restes du Fléau, les sauvages gnolls Rot Hide, les mages de Dalaran et les worgens maudits du Donjon d'Ombrecroc.",al={"qu'est-ce que la forêt des pins-argentés","parlez-moi de la forêt des pins-argentés","lore de la forêt des pins-argentés"}},["01503e92"]={q="Que s'est-il passé dans la Forêt des Pins-Argentés ?",a="La Forêt des Pins-Argentés ressemblait autrefois à la nature sauvage immaculée des Hinterlands, mais la Troisième Guerre l'a ruinée. Lorsque le Fléau du roi-liche s'est abattu vers le sud, des armées de morts-vivants ont incendié les fermes, massacré la population rurale et souillé la terre avec la peste des morts-vivants. Le roi Genn Greymane a scellé Gilnéas derrière son mur massif, abandonnant les terres du nord comme Bois-du-Bûcher et Moulin-de-l'Ambre. Pour repousser le Fléau, l'archimage Arugal a libéré des worgens sauvages, mais la malédiction s'est propagée sans contrôle. Lordaeron étant en ruine, les bois dévastés sont devenus un champ de bataille contesté.",al={"histoire de la forêt des pins-argentés","que s'est-il passé ici dans la forêt des pins-argentés","chute de la forêt des pins-argentés"}},b9edb2aa={q="Qui vivait ici avant les Réprouvés ?",a="Avant la Troisième Guerre, la Forêt des Pins-Argentés était habitée par des fermiers, des mineurs et des soldats humains de Lordaeron et de Gilnéas. Les colonies du sud telles que Bois-du-Bûcher et Moulin-de-l'Ambre furent laissées à l'extérieur lorsque Gilnéas se scella derrière le mur de Greymane. L'Ile de Fenris abritait une garnison militaire animée de Lordaeron au Donjon de Fenris. La plupart de ces anciens habitants ont péri lors de l'invasion du Fléau, ont fui vers le sud jusqu'au mur scellé, ou ont succombé à la non-mort et à la malédiction worgen.",al={"qui vivait dans la forêt des pins-argentés auparavant","anciens résidents de la forêt des pins-argentés","anciens habitants de la forêt des pins-argentés"}},["5b2addb4"]={q="Pourquoi la forêt a-t-elle l'air si morte ?",a="La forêt porte les cicatrices profondes et persistantes de la Troisième Guerre. La Forêt des Pins-Argentés marque l'étendue la plus au sud où la peste des morts-vivants du Fléau a visiblement corrompu la flore, drainant la vitalité du sol et laissant les anciens pins à écorce argentée pâles, maladifs et perdant des aiguilles flétries. Lordaeron ayant été détruit et Gilnéas muré, aucun gardien ne restait pour soigner les bosquets ravagés ou entretenir les terres agricoles calcinées, laissant les brumes froides et la pourriture s'installer sur les bois.",al={"pourquoi la forêt des pins-argentés meurt-elle","pourquoi la forêt des pins-argentés semble-t-elle morte","arbres flétris de la forêt des pins-argentés"}},["67376895"]={q="La Forêt des Pins-Argentés est-elle dangereuse ?",a="Extrêmement dangereuse. Des prédateurs sauvages comme des ours flétris, des araignées géantes et des worgs féroces rôdent sous les arbres. Des gnolls Rot Hide infestés par la peste massacrent violemment les voyageurs le long des routes, tandis que des mages humains de Dalaran fortifient Moulin-de-l'Ambre contre l'intrusion de la Horde. Au sud, les worgens sauvages de la Rage de Lune terrorisent les vallées sous la coupe de l'archimage Arugal. En dehors du sanctuaire fortifié du Sépulcre, la survie exige une vigilance constante.",al={"quel est le danger dans la forêt des pins-argentés","menaces dans la forêt des pins-argentés","est-ce sûr ici"}},["6dcc337b"]={q="Pourquoi la Horde m'a-t-elle envoyé dans la Forêt des Pins-Argentés ?",a="Vous avez été envoyé au sud depuis les Clairières de Tirisfal pour renforcer la frontière des Réprouvés. Fossoyeuse considère la Forêt des Pins-Argentés comme vitale pour sécuriser sa frontière sud, mais son emprise est fragile et limitée. Le grand exécuteur Hadrec et la Garde de la Mort ont besoin de champions capables de repousser les nécromanciens du Fléau envahissants, d'éliminer les gnolls hostiles, de surveiller les manœuvres secrètes de Dalaran et de contenir les worgens assoiffés de sang qui menacent de submerger les bois.",al={"pourquoi suis-je dans la forêt des pins-argentés","arrivée de la horde dans la forêt des pins-argentés","pourquoi m'envoyer ici"}},ab9ff98b={q="Est-ce toujours le territoire des Réprouvés ?",a="Les Réprouvés revendiquent la Forêt des Pins-Argentés comme territoire souverain de Fossoyeuse, mais leur contrôle est fortement contesté. Bien qu'ils maintiennent une domination ferme sur le nord de la Forêt des Pins-Argentés et sur le havre fortifié du Sépulcre, ils n'ont pas une mainmise incontestée sur l'ensemble de la forêt. Des gnolls Rot Hide hostiles règnent sur les eaux orientales, des mages de Dalaran occupent Moulin-de-l'Ambre, et les worgens sauvages d'Arugal dominent les étendues du sud-ouest.",al={"les réprouvés possèdent-ils la forêt des pins-argentés","qui contrôle la forêt des pins-argentés","territoire réprouvé de la forêt des pins-argentés"}},["858ebaa5"]={q="Qui a construit Le Sépulcre ?",a="Avant la Troisième Guerre, Le Sépulcre était simplement un grand cimetière humain calme et une crypte en bord de route construits par le peuple de Lordaeron pour enterrer leurs morts le long de l'autoroute ouest. Après la chute de Lordaeron, les Réprouvés survivants se sont emparés du cimetière et ont réaménagé la crypte en un avant-poste militaire fortifié, une station de caravanes et un quartier général logistique pour leurs opérations dans le sud.",al={"qui a construit le sépulcre","origine du sépulcre","histoire du sépulcre"}},f51f7d3d={q="Pourquoi les Réprouvés sont-ils basés au Sépulcre ?",a="Niché de manière défensive dans les collines de l'ouest, Le Sépulcre offre aux Réprouvés un point de vue naturel surplombant la côte et la route principale. Positionné entre le Fléau à l'est, Dalaran au sud-est et les worgens sauvages au sud, il sert de seul avant-poste sécurisé où les patrouilles de la Garde de la Mort et les chercheurs de la Société royale des apothicaires peuvent coordonner les défenses et protéger la route vers Tirisfal.",al={"pourquoi les réprouvés sont-ils au sépulcre","pourquoi le sépulcre est-il une base réprouvée","importance du sépulcre"}},["0581536d"]={q="Qui est le grand exécuteur Hadrec ?",a="Le grand exécuteur Hadrec est le commandant militaire des opérations des Réprouvés dans la Forêt des Pins-Argentés, stationné au Sépulcre. Sévère et pragmatique, il dirige la Garde de la Mort et les éclaireurs des Traque-morts pour pacifier la nature sauvage, découvrir les menaces cachées et orchestrer des frappes contre les forces hostiles telles que Thule Ravenclaw et les gnolls Rot Hide.",al={"hadrec","qui est hadrec","grand exécuteur hadrec de la forêt des pins-argentés"}},ff53d58c={q="À qui le grand exécuteur Hadrec rend-il des comptes ?",a="Hadrec rend compte directement à Dame Sylvanas Coursevent, la reine banshee des Réprouvés, et à son haut commandement à Fossoyeuse. En tant qu'officier supérieur de la Garde de la Mort, son mandat est de sécuriser les frontières de son nouveau royaume et d'éliminer toute puissance qui pourrait compromettre la souveraineté des Réprouvés.",al={"qui est le patron de hadrec","supérieur de hadrec","à qui hadrec rend-il des comptes"}},["6c73f41e"]={q="Qui sont les gnolls Rot Hide et pourquoi sont-ils ici ?",a="Les Rot Hide sont un clan vicieux de gnolls habitant la Forêt des Pins-Argentés, opérant principalement depuis l'Ile de Fenris et rôdant sur les rives du Lac Lordamere. Contrairement aux gnolls communs, ils sont affligés par la peste des morts-vivants, arborant une fourrure grise clairsemée et des yeux jaunes larmoyants. Ils mènent une guerre de guérilla brutale contre les Réprouvés, pillent les champs de bataille et assaillent férocement quiconque s'approche de leurs camps.",al={"gnolls rot hide","pourquoi les gnolls sont-ils dans la forêt des pins-argentés","gnoll rot hide de la forêt des pins-argentés"}},ad054bc9={q="Qui contrôle les gnolls Rot Hide ?",a="Les gnolls Rot Hide sont sous l'emprise de Thule Ravenclaw, un nécromancien traître aligné sur le Fléau. Depuis sa forteresse sur l'Ile de Fenris, Thule utilise la magie noire pour manipuler ces bêtes flétries, les envoyant sur des champs de bataille exhumés pour récolter des cadavres frais pour ses légions croissantes de morts-vivants.",al={"qui commande les rot hide","maître des rot hide","qui dirige les rot hide"}},["97f89d60"]={q="Que sont The Dead Fields ?",a="Le Champ des morts est une étendue de terres agricoles flétries au centre de la Forêt des Pins-Argentés, le long de la route menant au Lac Lordamere. Jadis une exploitation agricole paisible, c'est devenu un lieu de massacre de masse pendant la Troisième Guerre, lorsque le Fléau a envahi Lordaeron. Aujourd'hui, c'est un cimetière à ciel ouvert jonché de tombes peu profondes et de terre remuée.",al={"champs des morts de la forêt des pins-argentés","le champ des morts","que sont les champs des morts"}},d487a8f2={q="Pourquoi les gnolls creusent-ils dans Le Champ des morts ?",a="Les gnolls Rot Hide excavent Le Champ des morts pour déterrer les cadavres humains qui y ont été enterrés pendant la Troisième Guerre. Agissant sur les ordres de Thule Ravenclaw, ils déterrent des corps et des restes préservés pour fournir au nécromancien de la matière première pour construire des créations du Fléau et renforcer son armée de morts-vivants sur l'Ile de Fenris.",al={"pourquoi les rot hide creusent-ils","pourquoi les gnolls sont-ils dans les champs des morts","gnolls déterrant des cadavres"}},["3bca491d"]={q="Qu'y a-t-il sur l'Ile de Fenris ?",a="L'Ile de Fenris est une grande île située dans le Lac Lordamere, au large de la rive est de la Forêt des Pins-Argentés. Elle est dominée par le Donjon de Fenris, une ancienne forteresse militaire de Lordaeron tombée dans un sombre délabrement. Aujourd'hui, l'île sert de redoute lourdement fortifiée grouillante de gnolls Rot Hide et des serviteurs morts-vivants de Thule Ravenclaw.",al={"ile de fenris","qu'y a-t-il sur l'ile de fenris","donjon de fenris"}}},fp="17,230,18.551.0,30.531.1,25.482.1,49.319.0,57.270.1,23.261.1,35.243.0,22.247.0,48.232.0"}
P.entries["zone:stockade"] = {n="La Prison",s="La Prison est le complexe pénitentiaire de haute sécurité de Hurlevent, niché sous le quartier des canaux de la ville, près du Quartier des Mages. Conçu pour détenir les coupe-jarrets les plus dangereux, les insurgés politiques et les ennemis de l'État capturés, l'établissement a récemment sombré dans une anarchie violente. Le Gardien Thelwater a été repoussé jusqu'à l'entrée et recrute désespérément des aventuriers compétents pour mater l'émeute de l'intérieur avant qu'elle ne se propage dans la capitale.",h="La Prison est le complexe pénitentiaire de haute sécurité de Hurlevent, niché sous le quartier des canaux de...",kw={"bazil thredd","bruegal poing-de-fer","canaux","défias","dextren ward","hamhock","kam furie-du-fond","émeute","la prison","hurlevent","targorr","gardien thelwater"},ang={["class:Mage"]="Située juste au bord du canal du Quartier des Mages, la prison contient des bagarreurs physiques vulnérables aux sorts de ralentissement, tandis que l'ogre mage Hamhock peut déclencher une Chaîne d'éclairs.",["class:Rogue"]="La disposition de la prison présente un réseau complexe de cellules en fer verrouillées et de liens avec la Confrérie défias, offrant une pratique unique du crochetage et un aperçu du syndicat criminel de Bazil Thredd.",["faction:Alliance"]="La rébellion menace le cœur même de la capitale ; mettre fin au soulèvement préserve la sécurité intérieure de Hurlevent tout en honorant les primes officieuses pour les Carmines, le Bois de la Pénombre et Forgefer.",["race:Dwarf"]="La présence de Kam Furie-du-fond dans les cellules de Hurlevent est un affront pour Dun Modr ; le royaume de Forgefer exige sa tête pour venger les vies naines perdues dans les Paluns."},sec={{t="Une prison en état de siège",b="Sous les canaux tranquilles de Hurlevent, la Prison est devenue une zone de guerre. Lorsque l'armée régulière est partie combattre sur des fronts lointains, la prison, en sous-effectif, a dû compter sur des recrues inexpérimentées — dont des jeunes de quatorze ans — pour maintenir l'ordre. Cela n'a pas tenu. Les détenus ont déclenché une rébellion sanglante et coordonnée, déchirant leurs couvertures en laine pour en faire des foulards de gang et abattant les gardes restants. Le Gardien Thelwater a péniblement conservé le contrôle de l'entrée, laissant les cellules, les couloirs et les blocs de détention aux mains impitoyables des condamnés."},{t="Nobles et assassins",b="L'émeute a mis à nu la face sombre de la machine politique de Hurlevent. Les territoires extérieurs étaient depuis longtemps frustrés par le refus de la House of Nobles de procéder aux exécutions, conservant les détenus comme moyen de pression. Le garde Berton, des Carmines, voulait que l'orc Targorr le Terrifiant soit exécuté pour ses atrocités, mais il a vu les nobles geler la sentence. Le conseiller Millstipe, de Sombre-Comté, a vu le pilleur de tombes Dextren Ward échapper à la potence bien qu'il ait profané des sépultures pour le nécromancien Morbent Lagangrène. Même les nains de Dun Modr ont envoyé un message exigeant la mort du saboteur Sombrefer Kam Furie-du-fond. Avec la Prison en plein chaos, les autorités locales ont discrètement engagé des aventuriers pour exécuter les sentences que les tribunaux de la capitale refusaient d'appliquer."},{t="Le cerveau et les émeutiers",b="Derrière l'effondrement synchronisé de la prison se trouve Bazil Thredd, un criminel rusé lié à La Confrérie défias qui a orchestré le soulèvement depuis sa cellule. Parmi les émeutiers se trouve Bruegal Poing-de-fer, un dangereux bagarreur nain. Il est l'un des nombreux condamnés endurcis que les aventuriers peuvent rencontrer en aidant Thelwater à reprendre la prison."}},faq={{q="Pourquoi la Prison est-elle en pleine rébellion ?",a="La Confrérie défias a orchestré une émeute dans toute la prison alors que l'établissement était gravement en sous-effectif. Avec l'armée de Hurlevent déployée sur des fronts lointains, des volontaires adolescents ont été laissés à garder des tueurs endurcis. Les détenus ont pris les gardes en embuscade, se sont emparés d'armes et ont forcé le Gardien Thelwater à quitter les blocs de cellules.",al={"pourquoi émeute","que s'est-il passé à la prison","cause émeute prison"}},{q="Qui dirige le soulèvement à l'intérieur ?",a="Le cerveau derrière la révolte est Bazil Thredd, un criminel influent de la Confrérie défias incarcéré dans le bloc de cellules est. Parmi les autres prisonniers dangereux figurent Bruegal Poing-de-fer, Hamhock et Kam Furie-du-fond.",al={"boss de la prison","qui dirige l'émeute","qui gère la prison"}},{q="Pourquoi des prisonniers comme Targorr et Dextren Ward sont-ils encore en vie ?",a="Tous deux étaient condamnés à mort, mais des politiciens corrompus au sein de la House of Nobles ont placé des blocages bureaucratiques sur leurs exécutions pour les utiliser comme levier politique. Cette ingérence a indigné les alliés de Comté-du-Lac et de Sombre-Comté, les poussant à envoyer des aventuriers pour éliminer les prisonniers pendant le chaos.",al={"pourquoi targorr n'a pas été exécuté","procès dextren ward","corruption house of nobles"}},{q="Que signifie la défaite de Bruegal Poing-de-fer pour la prison ?",a="Bruegal Poing-de-fer est un dangereux bagarreur nain parmi les émeutiers. Le vaincre élimine une menace de la prison pendant que les aventuriers s'efforcent de mater le soulèvement.",al={"lore bruegal poing-de-fer","tuer bruegal","qui est bruegal"}},{q="Pourquoi y a-t-il des nains Sombrefer et des orcs dans une prison humaine ?",a="La Prison sert de centre de détention de haute sécurité pour les prisonniers de guerre de grande valeur. Targorr le Terrifiant a mené des attaques d'orcs du clan Rochenoire dans les Carmines, tandis que Kam Furie-du-fond a mené des sabotages pour le clan Sombrefer dans les Paluns avant d'être capturés et transférés dans la capitale.",al={"pourquoi nains sombrefer ici","lore kam furie-du-fond","targorr prison"}},{q="Les joueurs de la Horde peuvent-ils entrer dans la Prison ?",a="Oui, mais c'est extrêmement dangereux. L'entrée du donjon se trouve directement à l'intérieur de Hurlevent, près des canaux du Quartier des Mages. Les infiltrés de la Horde doivent se faufiler devant les gardes de la ville et les défenseurs de la capitale pour atteindre le portail.",al={"la horde peut-elle faire la prison","la horde dans la prison de hurlevent"}}},fx={["07af5e0b"]={q="Qu’est-ce que la Prison ?",a="La Prison est le complexe pénitentiaire de haute sécurité de Hurlevent, construit sous le quartier des Canals de la capitale. Il sert de lieu de détention pour les petits voleurs, les coupe-jarrets, les insurgés politiques et les ennemis importants du royaume en attente de jugement.",al={"qu'est-ce que la stormwind stockade","prison de la prison","prison de hurlevent"}},["2fc364a6"]={q="La Prison est-elle réservée à la Confrérie défias ?",a="Non. Bien que la Confrérie défias constitue le cœur de l’insurrection, les cellules abritent des petits voleurs, des pilleurs de tombes comme Dextren Ward, des orcs Rochenoire capturés comme Targorr le Terrifiant, et même des saboteurs Sombrefers comme Kam Furie-du-fond.",al={"la prison est-elle réservée aux défias","qui est dans la prison","tous les prisonniers sont-ils des défias"}},["0d433487"]={q="Pourquoi y a-t-il autant de membres de la Confrérie défias enfermés ici ?",a="Les autorités de Hurlevent ont capturé des agents de la Confrérie à travers la Marche de l’Ouest, la Forêt d’Elwynn et la ville elle-même. Plutôt que de les exécuter sur-le-champ, la Couronne les a traînés jusqu’à la Prison, concentrant un réseau instable d’insurgés juste sous le plancher de la ville.",al={"pourquoi tant de défias ici","pourquoi des défias dans la prison","prisonniers de la confrérie défias"}},e96a18b2={q="Qui est responsable de cette prison ?",a="Le Gardien Thelwater préside l’établissement. Lorsque l’insurrection a éclaté, ses gardes ont été submergés et chassés des quartiers de détention. Thelwater a péniblement réussi à tenir l’entrée, ce qui l’oblige à recruter désespérément des aventuriers capables pour reprendre le contrôle des couloirs.",al={"qui dirige la prison","gardien de la prison","gardien thelwater"}},["06cbacdc"]={q="Pourquoi les gardes du Gardien Thelwater ne peuvent-ils pas maîtriser l’émeute ?",a="La garde de la prison était déjà en sous-effectif, allant même jusqu’à employer des volontaires de quatorze ans pour surveiller les détenus dangereux. Lorsque la Confrérie défias s’est unie pour attaquer, le personnel a été pris totalement au dépourvu, massacré ou contraint de fuir vers le hall d’entrée.",al={"pourquoi les gardes ne peuvent-ils pas arrêter l'émeute","où sont les gardes de la prison","gardes de la prison"}},["7c158547"]={q="Pourquoi Hurlevent m’envoie-t-elle à l’intérieur au lieu de l’armée ?",a="Une grande partie de l’armée de Hurlevent est déployée sur des fronts lointains, et la bureaucratie corrompue de la Chambre des Lords paralyse toute action municipale rapide. De plus, les responsables de la ville cherchent désespérément à garder le secret sur l’émeute pour éviter toute panique dans les rues.",al={"pourquoi envoyer des aventuriers","pourquoi pas l'armée dans la prison","où est l'armée de hurlevent"}},a2006c52={q="Les gardes à l’extérieur savent-ils ce qui se passe à l’intérieur ?",a="Les gardes contiennent les émeutiers au seuil du donjon, et le Gardien Thelwater cherche de l’aide pour rétablir l’ordre à l’intérieur. Les responsables de la ville étouffent l’affaire pour éviter d’alarmer les citoyens ordinaires.",al={"les gardes extérieurs sont-ils au courant","hurlevent est-elle au courant de l'émeute","secret de la prison"}},b1798127={q="Quelle est la différence entre les prisonniers, les condamnés et les insurgés présents ici ?",a="Les détenus vont des criminels et voleurs à la tire ramassés dans les rues aux criminels condamnés et aux insurgés de la Confrérie défias purs et durs. Alors que les condamnés ordinaires ont profité de l’occasion pour piller, les insurgés suivent activement les ordres de Bazil Thredd pour renverser la prison.",al={"condamnés insurgés prisonniers","types d'ennemis dans la prison","qui sont les détenus"}},["378bbf14"]={q="Comment les détenus ont-ils obtenu des armes et se sont-ils organisés ?",a="L’insurrection a été méticuleusement préparée par le chef de la Confrérie défias, Bazil Thredd. Sous sa direction, les prisonniers ont déchiré leurs couvertures en laine pour en faire des foulards de gang rouges, ont sauté sur les gardes en sous-effectif, ont volé leurs armes et leurs clés, et ont méthodiquement libéré les cellules de chaque aile.",al={"comment les prisonniers ont-ils obtenu des armes","comment les défias se sont-ils organisés","qui a armé les prisonniers"}},["855deb71"]={q="Pourquoi installer une prison juste sous la ville ?",a="Le complexe pénitentiaire se trouve sous les Canals de Hurlevent. Son emplacement d’origine n’est pas expliqué.",al={"pourquoi une prison sous hurlevent","pourquoi cet emplacement pour la prison","prison sous les canals"}},caa2e4bf={q="Comment me suis-je retrouvé dans la Prison ?",a="Vous avez franchi les lourdes portes de fer situées près des Canals nord de Hurlevent. Une émeute massive a éclaté sous les rues et les gardes restants du Gardien Thelwater ont été repoussés au seuil de la prison, laissant le contrôle aux détenus. Désespéré de cacher ce chaos aux citoyens au-dessus, le gardien a recruté des aventuriers valides pour marcher directement dans les blocs de cellules et reprendre l’établissement par la force.",al={"comment suis-je arrivé ici","pourquoi suis-je venu ici","comment suis-je entré dans la prison"}},["45edc40e"]={q="Que suis-je censé faire dans la Prison ?",a="Votre mission principale est de briser la rébellion et de mettre fin à son chef, le cerveau de la Confrérie défias Bazil Thredd. Cependant, des alliés à travers tout le royaume ont saisi ce moment de chaos pour régler de vieilles dettes : Sombre-Comté cherche à obtenir vengeance contre le pilleur de tombes Dextren Ward, le Comté-du-Lac veut la mort de l’impitoyable orc Targorr le Terrifiant, et Forgefer exige la tête du saboteur Kam Furie-du-fond.",al={"quelle est ma mission ici","que dois-je faire ici","pourquoi suis-je ici"}}},fp="12,345,20.476.0,20.680.1,30.277.1,38.302.0,35.174.0,60.285.0,60.151.0,61.253.0,37.213.0"}
P.entries["zone:stonetalon"] = {n="Les Serres-Rocheuses",s="Les Serres-Rocheuses sont une chaîne escarpée de pics rocheux façonnés par le vent, bordant Orneval, les Tarides et Désolace. Vénérées comme un sanctuaire sacré par les elfes de la nuit et les taurens, les hauteurs sacrées de la région contrastent vivement avec la fumée et les machines qui étouffent ses canyons inférieurs. Aujourd'hui, les montagnes sont déchirées par la déforestation, les ravages d'éléments instables et des hostilités frontalières latentes.",h="Les Serres-Rocheuses sont une chaîne escarpée de pics rocheux façonnés par le vent, bordant Orneval, les...",kw={"le val calciné","gerenzo siffleclef","malaka'jin","les serres-rocheuses","pic des serres-rocheuses","retraite de roche-soleil","col de talondeep","combe des cisailles"},ang={["class:Druid"]="La profanation de la Combe des Cisailles et la corruption calcinée du Val calciné constituent un appel pressant pour les druides cherchant à apaiser les esprits de la nature courroucés et à protéger les nids sacrés.",["class:Shaman"]="Le cri des esprits de la montagne attaqués par les foreuses gobelines retentit jusqu'à Orgrimmar, appelant les chamans à calmer les élémentaires de pierre déchaînés et à restaurer l'équilibre des sommets.",["faction:Alliance"]="Postée au sommet du Pic des Serres-Rocheuses et dans des camps dissimulés autour de la Combe des Cisailles, l'Alliance défend d'anciens terriers kaldorei contre les machines gobelines et les rivaux territoriaux menaçants.",["faction:Horde"]="Les aventuriers de la Horde s'appuient sur le refuge isolé de la Retraite de Roche-Soleil et l'avant-poste troll méridional de Malaka'jin pour endiguer la pollution industrielle de la KapitalRisk et débusquer les traîtres hors-la-loi Totem-sinistre."},sec={{t="Les Vents mauvais et les pics",b="S'élevant abruptement du centre de Kalimdor, la chaîne des Serres-Rocheuses retient l'humidité venue des mers occidentales, provoquant de soudaines averses et rendant les sentiers de grès traîtres et glissants. La caractéristique dominante des vallées inférieures est la bourrasque incessante et décapante connue sous le nom de Vents mauvais, capable d'aveugler les voyageurs avec de la poussière ou de précipiter les imprudents du haut des falaises abruptes. Plus haut, des forêts de conifères recouvrent les crêtes entourant le Pic des Serres-Rocheuses, où les elfes de la nuit veillent sur des terriers ancestraux et des clairières, protégeant les nids sacrés de wyvernes et d'hippogriffes qui nichent le long du lac Mirkfallon."},{t="Industrie et intrusion",b="La solitude paisible de la chaîne a été violemment perturbée par l'arrivée de la KapitalRisk. Établissant d'immenses camps de bûcherons et creusant de profondes mines à ciel ouvert dans la Combe des Cisailles, les gobelins — aidés par le gnomeregan lépreux dérangé Gerenzo Siffleclef — ont rasé des forêts séculaires, noirci le ciel avec la fumée de leurs fourneaux et déversé des boues industrielles dans les ruissellements de montagne. Leur cupidité a provoqué une riposte rapide : des chamans locaux d'Orgrimmar ont répondu aux cris d'agonie des esprits de la montagne, tandis que de petits camps de l'Alliance établis à proximité luttent contre les profanateurs pour protéger ce qui subsiste des hautes terres."},{t="Les cicatrices du passé",b="Au sud s'étend le Val calciné, autrefois une nature sauvage florissante, aujourd'hui réduit à une étendue désolée couverte de cendres où s'agitent des élémentaires de feu renégats, des drakônides noirs et des harpies. Alors que les sommets furent le lieu historique où la Horde et l'Alliance forgèrent une trêve fragile durant la Troisième guerre sous la direction du mystérieux Oracle, les relations actuelles s'effritent. Des taurens Totem-sinistre renégats opèrent depuis des campements occupés, et les trolls Sombrelances de Malaka'jin affrontent les incursions de l'Alliance venues des Tarides et d'Orneval."}},faq={{q="Comment se rendre aux Serres-Rocheuses ?",a="La plupart des voyageurs arrivent par le col de Talondeep, un sentier de montagne qui s'enfonce dans la chaîne depuis le sud-ouest d'Orneval. Il existe également de hauts sentiers menant au sud vers Désolace et des chemins descendant vers l'est directement dans les étendues septentrionales des Tarides.",al={"entrée des serres-rocheuses","comment aller aux serres-rocheuses","route des serres-rocheuses"}},{q="Pourquoi le Val calciné est-il brûlé et dévasté ?",a="Le Val calciné était autrefois un havre verdoyant, mais une dévastation cataclysmique a consumé la vallée par les flammes. Il a été réduit à une ruine fumante infestée d'élémentaires de feu agressifs, de drakes sauvages et de redoutables harpies.",al={"incendie val calciné","qu'est-il arrivé au val calciné","pourquoi le val calciné a brûlé"}},{q="Que fait la KapitalRisk dans la Combe des Cisailles ?",a="La KapitalRisk pratique une coupe à blanc impitoyable et fore profondément le flanc de la montagne en quête de richesses minières. Ses activités ont souillé le lac de la Combe avec de la graisse de moteur, dénudé les vallées et rendu furieux les esprits locaux ainsi que les habitants indigènes.",al={"kapitalrisk serres-rocheuses","goblins combe des cisailles","pourquoi les gobelins coupent les arbres"}},{q="Où se trouvent les principaux maîtres de vol ?",a="Les héros de l'Alliance utilisent le maître de vol perché dans le haut sanctuaire du Pic des Serres-Rocheuses au nord, tandis que les aventuriers de la Horde s'établissent dans le village montagnard central de la Retraite de Roche-Soleil.",al={"trajet aérien serres-rocheuses","où est le maître de vol serres-rocheuses","vol serres-rocheuses"}},{q="Que s'est-il passé au Pic des Serres-Rocheuses durant la Troisième guerre ?",a="Guidés par les visions du prophète Medivh, Thrall et Jaina Portvaillant ont gravi les cavernes du Pic des Serres-Rocheuses à la recherche de l'Oracle. C'est là que les deux chefs de faction ont conclu l'alliance temporaire historique qui s'est unie contre la Légion ardente au mont Hyjal.",al={"histoire du pic des serres-rocheuses","l'oracle des serres-rocheuses","troisième guerre serres-rocheuses"}},{q="Qui sont les Totem-sinistre dans les Serres-Rocheuses ?",a="Les Totem-sinistre sont une tribu impitoyable de taurens renégats hostiles à toute influence extérieure. Dans les Serres-Rocheuses, ils ont investi un avant-poste montagnard près de la frontière des Tarides, terrorisant les voyageurs des environs et capturant des prisonniers.",al={"poste totem sinistre","totem-sinistre serres-rocheuses"}}},fx={["4946a833"]={q="Que sont Les Serres-Rocheuses ?",a="Les Serres-Rocheuses sont une chaîne de montagnes escarpée, sculptée par le vent, dans le centre de Kalimdor, située à l'ouest des Tarides, au sud d'Orneval et au nord de la Désolace. Connue pour ses vents extrêmes, ses gouffres profonds et ses pics de grès abrupts créés lors de la Fracture, la région forme une zone frontalière historique où les Elfes de la nuit et les Taurens ont coexisté pendant des générations. Ses sommets élevés et sacrés restent verdoyants avec des conifères, tandis que les vallées inférieures sont sèches, rocheuses et fortement marquées par l'industrie.",al={"zone des serres-rocheuses","que sont les serres-rocheuses","à propos des serres-rocheuses"}},["4e995438"]={q="Les Serres-Rocheuses sont-elles dangereuses ?",a="Oui, les voyageurs sont confrontés à des périls naturels et à des ennemis féroces. Les vents violents et les pluies soudaines peuvent rendre les falaises de grès élevées assez glissantes pour faire tomber les gens vers leur mort. Au-delà de la météo, les montagnes grouillent d'harpies Bloodfury agressives, de wyvernes prédatrices, d'araignées, de kobolds et d'élémentaires enragés. De plus, les machines impitoyables et les hommes de main armés de la KapitalRisk rendent les vallées contestées comme la Combe des Cisailles exceptionnellement périlleuses.",al={"danger des serres-rocheuses","les serres-rocheuses sont-elles sûres","dangers des serres-rocheuses"}},["9d849e11"]={q="Qui vit dans Les Serres-Rocheuses ?",a="La région abrite des factions dispersées plutôt qu'un seul pouvoir gouvernemental. Les Elfes de la nuit détiennent le Pic des Serres-Rocheuses et gardent des sites sacrés sur les hauteurs, tandis que la Horde maintient des colonies à la Retraite de Roche-Soleil et au village troll de Malaka'jin. Les harpies Bloodfury natives nichent dans les rochers, des Taurens Grimtotem hostiles occupent des postes à proximité, et la KapitalRisk gérée par des gobelins occupe des zones déboisées autour de la Combe des Cisailles.",al={"qui vit dans les serres-rocheuses","factions des serres-rocheuses","habitants des serres-rocheuses"}},a4f73e64={q="Pourquoi la KapitalRisk exploite-t-elle le bois dans la Combe des Cisailles ?",a="La KapitalRisk est un conglomérat marchand impitoyable cherchant le profit par une exploitation effrénée des ressources. Dans la Combe des Cisailles, ils rasent des forêts anciennes en utilisant des machines lourdes comme le Super Reaper 6000 et font exploser la terre pour extraire des minerais précieux. Leur mépris pour la nature remplit l'air de suie et empoisonne les eaux locales avec des boues et du pétrole, gagnant la furieuse opposition des druides locaux et de la Horde.",al={"exploitation forestière kapitalrisk","pourquoi les gobelins coupent des arbres","bois de la kapitalrisk serres-rocheuses"}},["66935983"]={q="Qui dirige la KapitalRisk dans la Combe des Cisailles ?",a="Les opérations locales d'exploitation forestière et minière dans la Combe des Cisailles sont dirigées par un gnome lépreux nommé Gerenzo Wrenchwhistle. Supervisant la coupe à blanc depuis une plate-forme construite haut au-dessus du Lac de la Combe, Gerenzo emploie son expertise mécanique pour maximiser la destruction. Ses opérations malhonnêtes ont même attiré la colère d'inventeurs gobelins rivaux du Syndicat des mécaniciens, qui cherchent à l'éliminer.",al={"qui dirige la combe des cisailles","gerenzo wrenchwhistle","chef de la kapitalrisk serres-rocheuses"}},ff0da62d={q="Qui sont les harpies Bloodfury ?",a="Les harpies Bloodfury sont une tribu vicieuse de femmes-oiseaux originaires des Serres-Rocheuses. Historiquement, ces montagnes étaient leur cœur ancestral avant qu'elles ne se répandent dans les Tarides et au-delà. Elles défendent agressivement leur territoire contre les étrangers, capturant des bêtes locales et s'affrontant violemment avec les pèlerins taurens et les machines gobelines envahissantes dans des endroits comme le Val calciné.",al={"harpies bloodfury","harpies des serres-rocheuses","qui sont les harpies ici"}},["66599fe7"]={q="Qu'est-ce que la Retraite de Roche-Soleil ?",a="La Retraite de Roche-Soleil est une colonie paisible de la Horde nichée dans une vallée de montagne isolée au sud du Lac Mirkfallon. Elle sert de base principale pour les Taurens et les Orcs dans la région, abritant des chamans et des druides dédiés à restaurer la terre de la pollution de la KapitalRisk et à combattre les menaces empiétant sur les montagnes sacrées.",al={"lore de la retraite de roche-soleil","qu'est-ce que la retraite de roche-soleil","taurens de roche-soleil"}},["5a5a6e9c"]={q="Pourquoi les Taurens ont-ils établi la Retraite de Roche-Soleil ?",a="Depuis des générations, les Taurens révèrent cette vallée comme un lieu ayant une connexion profonde avec le royaume des esprits. Les légendes anciennes disent que le dieu solaire An'she a embrassé le pic sur lequel se trouve la retraite. Les Taurens ont longtemps fait des pèlerinages sacrés ici pour communier avec les esprits et allumer de grands feux de joie rituels pour illuminer les montagnes dans l'ombre.",al={"pourquoi les taurens s'installent à roche-soleil","histoire de la retraite de roche-soleil","an'she roche-soleil"}},["51d42c77"]={q="Qu'est-ce que la Combe des Cisailles ?",a="La Combe des Cisailles était autrefois une forêt ancienne verdoyante, mais elle a été dévastée par l'exploitation industrielle. La KapitalRisk a réduit la vallée en une étendue stérile de souches, de terre et de machines fumantes. Entre la déforestation de la KapitalRisk, les écoulements fétides dans le Lac de la Combe et les kobolds infestant la mine locale, elle se dresse comme un monument en ruine à la cupidité sans retenue.",al={"à propos de la combe des cisailles","zone de la combe des cisailles","lore de la combe des cisailles"}},d850bc0a={q="Qu'y a-t-il dans la Mine des Cisailles ?",a="La Mine des Cisailles, située dans les falaises sud-est de la Combe des Cisailles, est envahie par des kobolds agressifs de la Combe des Cisailles. Chassés ou abandonnés par les mineurs réguliers, les kobolds excavent maintenant furieusement des filons de lingots de fer fumant, attaquant férocement quiconque tente d'intriguer dans leurs fouilles souterraines.",al={"kobolds de la mine des cisailles","qu'y a-t-il dans la mine des cisailles","fer fumant de la mine des cisailles"}},d3863c46={q="Qu'est-ce que L'antre des Serres sur le Pic des Serres-Rocheuses ?",a="L'antre des Serres est un ancien terrier de tumulus elfe de la nuit sculpté dans les hauteurs du Pic des Serres-Rocheuses. Il est entretenu par des druides du Cercle cénarien qui communient avec les esprits de la nature et le Rêve d'émeraude. Au plus profond, les druides ont traditionnellement dormi dans une contemplation sacrée, gardés par des dryades, des gardiens et les protections magiques du pic.",al={"l'antre des serres","l'antre sur le pic des serres-rocheuses","terrier de tumulus serres-rocheuses"}},a547ffd6={q="Est-ce qu'Orneval est relié aux Serres-Rocheuses ?",a="Oui. La rude Perce des Serres relie directement le sud-ouest d'Orneval au nord-est des Serres-Rocheuses par un passage montagneux caverneux. Les voyageurs et aventuriers passent fréquemment entre les forêts immaculées et disputées d'Orneval et les hauteurs arides des Serres-Rocheuses tout en traquant les menaces de la KapitalRisk ou les conflits de faction en cours.",al={"comment orneval est relié aux serres-rocheuses","perce des serres orneval","frontière orneval serres-rocheuses"}},a5c2784c={q="Comment suis-je arrivé aux Serres-Rocheuses ?",a="La plupart des voyageurs atteignent ces hauteurs escarpées par la Perce des Serres, un ancien tunnel montagneux creusé dans le sud-ouest d'Orneval. D'autres vagabonds grimpent le long des sentiers accidentés menant à l'ouest des Tarides, gravissant les cols balayés par les vents vers les rochers escarpés. Que vous ayez été envoyé au sud par les commandants elfes de la nuit à Astranaar ou dépêché vers l'ouest à travers la frontière calcinée depuis la Croisée, les hauts canyons et les hurlements des Vents maléfiques accueillent quiconque entreprend l'ardent périple dans cette chaîne.",al={"comment suis-je arrivé ici","comment aller aux serres-rocheuses","arrivée aux serres-rocheuses"}},["4abc7ef6"]={q="Que suis-je censé faire dans les Serres-Rocheuses ?",a="Vous êtes ici pour faire face aux menaces croissantes qui dévastent ces hauteurs sacrées. À la Combe des Cisailles, les impitoyables gobelins de la KapitalRisk rasent les forêts anciennes et polluent les rivières avec leurs machines, s'attirant la colère des deux factions. Pendant ce temps, la tribu Totem-sinistre sème la discorde le long de la frontière orientale, tandis que des harpies vicieuses et des élémentaires de feu déchaînés infestent le bassin brûlé du Val calciné. Vous devez aider vos alliés à repousser ces pollueurs et ces monstres pour protéger la terre.",al={"que dois-je faire ici","pourquoi suis-je ici","ma mission dans les serres-rocheuses"}}},fp="20,167,27.462.0,22.461.0,17.474.0,41.202.0,42.194.0,52.224.0,42.161.0,54.229.0,36.181.0"}
P.entries["zone:stormwind"] = {n="Hurlevent",s="À Hurlevent, la couronne revient à un jeune prince tandis que le roi Varian a disparu. Rebâtie après la Première guerre, la cité est aujourd’hui le cœur de la Grande Alliance, bien que les dettes et les troubles politiques agitent ses quartiers de pierre blanche.",h="À Hurlevent, la couronne revient à un jeune prince tandis que le roi Varian a disparu.",kw={"anduin","bolvar","cathédrale","tram des profondeurs","prestor","maçons","hurlevent","vancleef","wrynn"},ang={["class:Paladin"]="En tant que paladin, vous trouverez la Cathédrale de la Lumière, principal sanctuaire de votre foi dans le sud. Elle forme les chevaliers de la Main d’argent et défend la justice.",["class:Rogue"]="En tant que voleur, vous trouverez le quartier général du SI:7 sous les rues pavées de la Vieille ville. Il dirige le principal réseau de renseignement et d’espionnage de l’Alliance.",["faction:Alliance"]="En tant que membre de l’Alliance, vous pouvez compter sur Hurlevent pour sa puissance navale, son ancrage spirituel et son rôle diplomatique essentiel. C’est la métropole la plus peuplée de la Grande Alliance.",["race:Dwarf"]="En tant que nain, vous pouvez emprunter le Tram des profondeurs pour rejoindre les vôtres au Quartier des Nains. Ils entretiennent des liens commerciaux et militaires étroits avec le royaume des humains.",["race:Human"]="En tant qu’humain, Hurlevent est le dernier grand siège de pouvoir souverain de votre peuple, après la chute de Lordaeron, d’Alterac et de Dalaran dans le nord."},sec={{t="Renaître de ses cendres",b="Hurlevent fut fondée il y a plus de mille ans par des descendants des Arathi. Pendant des générations, ce fut un royaume florissant et autosuffisant. La Horde des Orcs franchit la Porte des ténèbres et ravagea le continent méridional, détruisant la capitale durant la Première guerre. Les survivants suivirent sir Anduin Lothar vers le nord, au-delà de la Grande mer, jusqu’à Lordaeron. Après la défaite de la Horde lors de la Deuxième guerre, le roi Terenas Menethil II et l’Alliance financèrent la reconstruction de la cité. La Guilde des maçons bâtit la nouvelle Hurlevent en pierre blanche polie, avec des canaux traversant ses quartiers."},{t="Une cour divisée",b="La grandeur de Hurlevent dissimule un royaume endetté et une cour divisée. La Maison des nobles et la Guilde des maçons s’affrontèrent au sujet des salaires, et leur différend plongea le royaume dans une dette paralysante. Les ouvriers de la guilde se révoltèrent et furent chassés de la cité qu’ils avaient bâtie. Le roi Varian Wrynn a disparu alors qu’il se rendait à un sommet diplomatique. Pour éviter la panique, la couronne fut confiée à son fils de dix ans, le prince Anduin Wrynn. Le généralissime Bolvar Fordragon gouverne désormais comme régent et commandant militaire, avec à ses côtés la conseillère royale dame Katrana Prestor."},{t="Cœur de la Grande Alliance",b="Lordaeron étant envahie par le Fléau, Hurlevent est devenue le plus grand refuge de l’humanité et le centre de l’Alliance. Le Tram des profondeurs souterrain du grand mécanicien Gelbin Mekkanivelle relie directement la cité à Forgefer, le royaume des nains. De l’autre côté de la Vallée des héros, d’imposantes statues rendent hommage aux fils de Lothar, disparus au-delà de la Porte des ténèbres. La Cathédrale de la Lumière accueille les fidèles, tandis que le Sanctum des mages abrite les études arcaniques. Le commerce, la culture et la défense des mers du Sud convergent tous à Hurlevent."},{t="Le sort des maçons",b="Les maçons se rassemblèrent de nouveau en Marche de l’Ouest sous la direction de leur maître de guilde, Edwin VanCleef. Ils devinrent la Confrérie défias, des bandits au masque rouge qui étranglent désormais les terres agricoles du royaume. Les bâtisseurs des murs blancs de Hurlevent ont juré de faire payer à la Maison des nobles chaque pierre."},{t="Un allié à la cour",b="La Confrérie défias trouva de l’aide au sein du Donjon de Hurlevent. Le seigneur Gregor Lescovar, de la Maison des nobles, traitait secrètement avec la Confrérie et lui transmettait les plans du royaume, tout en siégeant parmi les seigneurs qui avaient trompé les maçons."},{t="Ombres au donjon",b="Dame Katrana Prestor a secrètement guidé les décisions de la Maison des nobles. Elle a attisé son conflit avec les maçons et ignoré les appels à l’aide militaire de localités comme la Marche de l’Ouest et les Carmines. Elle a aussi murmuré son venin au généralissime Bolvar, maintenant les légions de Hurlevent inactives et divisées, tandis que les troubles au-delà des murs de la cité menacent le trône."}},faq={{q="Qui gouverne Hurlevent en ce moment ?",a="Le prince Anduin Wrynn, âgé de dix ans, détient la couronne de Hurlevent, tandis que le généralissime Bolvar Fordragon gouverne comme régent et commande ses forces armées. Bolvar s’appuie sur les conseils de la conseillère royale dame Katrana Prestor, alors que le roi Varian Wrynn reste porté disparu.",al={"roi actuel","qui est le roi","qui dirige hurlevent","roi de hurlevent"}},{q="Qu’est-il arrivé au roi Varian Wrynn ?",a="Le roi Varian a disparu dans des circonstances suspectes alors qu’il naviguait vers un sommet diplomatique à Theramore. Sa disparition fut tenue secrète pour préserver la stabilité, bien que des rumeurs se soient répandues dans les rues et les campagnes.",al={"où est varian","roi disparu","varian a disparu","varian wrynn a disparu"}},{q="Pourquoi la cité a-t-elle été rebâtie, et par qui ?",a="La Horde des Orcs rasa la cité d’origine durant la Première guerre. Après la Deuxième guerre, l’Alliance de Lordaeron finança la reconstruction, et le maître artisan Edwin VanCleef dirigea la Guilde des maçons dans l’édification de la capitale en pierre blanche.",al={"qui a rebâti hurlevent","guilde des maçons","nouvelle hurlevent","reconstruction de la cité"}},{q="Pourquoi les maçons se sont-ils révoltés contre la couronne ?",a="La Maison des nobles s’endetta lourdement en renforçant l’armée de Hurlevent, puis refusa de verser à la Guilde des maçons les salaires promis. Quand Edwin VanCleef exigea le paiement, les nobles dissolurent la guilde. Les ouvriers se révoltèrent et furent chassés de la cité.",al={"origine des défias","pourquoi les défias sont en colère","révolte des maçons"}},{q="Qui représentent les immenses statues de la Vallée des héros ?",a="La Vallée des héros rend hommage aux fils de Lothar : le général Turalyon, la capitaine forestière Alleria Coursevent, l’archimage Khadgar, Kurdran Marteau-Hardi et Danath Trollemort. Les statues commémorent les héros qui franchirent la Porte des ténèbres vers Draenor pour sceller la faille et protéger Azeroth.",al={"statues à l’entrée","statues de la vallée des héros","statues des fils de lothar"}},{q="Comment Hurlevent est-elle reliée à Forgefer ?",a="Le Tram des profondeurs, une voie ferrée souterraine, relie Hurlevent à Forgefer. Le grand mécanicien Gelbin Mekkanivelle le construisit à la demande du roi Magni Barbe-de-Bronze, afin que les capitales puissent commercer rapidement et se prêter main-forte en temps de guerre.",al={"tram des profondeurs","train pour forgefer","comment aller à forgefer"}},{q="Pourquoi Hurlevent n’envoie-t-elle pas de soldats aider la Marche de l’Ouest et les Carmines ?",a="La cour royale, guidée par dame Katrana Prestor, affirme que Hurlevent ne peut détacher de soldats de ses murs et de ses frontières proches. Les finances du royaume sont mises à mal, et les luttes politiques ont paralysé la Maison des nobles, laissant les villes régionales dépendre de leurs milices locales.",al={"armée de hurlevent absente","pourquoi pas d’aide pour la marche de l’ouest","renforts refusés"}}},fx={["9beefbfb"]={q="Qu'est-ce que Hurlevent ?",a="Hurlevent est la capitale du royaume humain de Hurlevent et le plus grand bastion de l'humanité encore debout en Azeroth. Construite au nord de la Forêt d’Elwynn le long du littoral, elle sert de cœur battant, de port principal et de centre culturel de la Grande Alliance. Reconstruite à partir des cendres de la Première Guerre, ses remparts de pierre fortifiés abritent artisans, érudits, soldats et réfugiés qui voient en cette ville un symbole de la persévérance humaine.",al={"à propos de hurlevent","hurlevent capitale","qu'est-ce que hurlevent"}},edb1c1aa={q="Qu'est-il arrivé à Hurlevent par le passé ?",a="Fondé à l'origine il y a plus de mille ans par les descendants de la lignée d'Arathor, le royaume a prospéré pendant des siècles malgré les conflits avec les gnolls et les trolls de la jungle. Cependant, pendant la Première Guerre, la Horde orque a assiégé la capitale. Après le meurtre tragique du roi Llane Wrynn, la ville fut percée, mise à sac et brûlée jusqu'au sol. Sir Anduin Lothar mena les réfugiés survivants vers le nord, à travers la mer, jusqu'en Lordaeron, et ne revint qu'après la Deuxième Guerre pour reprendre leur terre natale et la reconstruire.",al={"histoire de hurlevent","destruction de hurlevent","hurlevent première guerre"}},d0a4b7c8={q="Hurlevent est-elle dangereuse ?",a="Derrière ses portes colossales et sa garde vigilante, Hurlevent est l'un des sanctuaires les plus fortifiés au monde. Cependant, des dangers invisibles subsistent à l'intérieur. Le Stockade a connu des émeutes violentes, des cultistes et des voleurs rôdent dans les canaux ombragés, et les troubles politiques agités par The Defias Brotherhood maintiennent la Maison des Nobles sur le qui-vive. Bien que la guerre ouverte ne franchisse que rarement les murs, la corruption, la trahison et les complots cachés chuchotent à la fois dans le Donjon et dans les ruelles sombres.",al={"hurlevent est-elle sûre","danger à hurlevent","menaces sur hurlevent"}},["163d181d"]={q="Qui est The Defias Brotherhood ?",a="The Defias Brotherhood est une impitoyable guilde de hors-la-loi, brigands, voleurs et pirates qui menace ouvertement la stabilité du royaume. Ils sont reconnaissables à leurs bandanas rouges caractéristiques, portés pour symboliser le sang versé par leur cause. Bien qu'ils opèrent principalement depuis la Marche de l’Ouest, les Carmines et les Mortemines, leur influence s'étend directement jusqu'à Hurlevent, où leurs espions et sympathisants minent l'autorité de la couronne et sèment la discorde parmi les classes laborieuses.",al={"confrérie défias","qui est the defias brotherhood","gang des defias"}},b1d432aa={q="Qu'est-ce que la Cathédrale de la Lumière ?",a="Dominant la Place de la Cathédrale, la Cathédrale de la Lumière est le centre spirituel prééminent de l'humanité et de la Grande Alliance. Reconstruite après la Deuxième Guerre sous l'impulsion de l'archevêque Alonsus Faol et de l'évêque d'alors, Benedictus, elle sert de siège à l'Église de la Lumière sacrée et de quartier général pour l'Ordre de la Main d’argent. Paladins et prêtres voyagent de tous les royaumes pour s'entraîner, chercher la sagesse et méditer au sein de ses salles grandioses et paisibles.",al={"cathédrale de la lumière","cathédrale de hurlevent","église de la lumière hurlevent"}},["3414b788"]={q="Comment suis-je arrivé à Hurlevent ?",a="Si vous avez commencé votre périple au Comté-du-Nord et que vous avez progressé à travers la Forêt d’Elwynn, la route principale vous a mené directement à travers la Vallée des héros jusqu'aux portes fortifiées de la capitale. Si vous venez de Dun Morogh ou de Forgefer, vous avez probablement emprunté le Tram des profondeurs, merveille de l'ingénierie gnome qui relie directement le bastion nain au Quartier des Nains sous les montagnes. Les voyageurs venant d'autres contrées d'Azeroth arrivent aux portes de Hurlevent après de longs trajets à travers les royaumes du sud, à la recherche du dernier grand bastion de l'humanité.",al={"comment suis-je arrivé ici","comment suis-je arrivé à hurlevent","comment aller à hurlevent"}},["68c43aeb"]={q="Que suis-je censé faire à Hurlevent ?",a="Hurlevent est le cœur battant de l'Alliance et un havre pour se reposer, s'entraîner et se ravitailler. Sous ses remparts blancs étincelants, cependant, le royaume est profondément fracturé. Le roi Varian Wrynn a disparu dans des circonstances mystérieuses, laissant le jeune roi Anduin et le Généralissime Bolvar Fordragon lutter contre la paralysie politique dans le Donjon. Pendant ce temps, les frontières environnantes de la Marche de l’Ouest et des Carmines réclament de l'aide contre le banditisme rampant, et The Defias Brotherhood complote dans l'ombre. Vous êtes ici pour perfectionner votre art, faire votre rapport à vos chefs de faction et prêter main-forte à un royaume assiégé.",al={"pourquoi suis-je ici","que faire ici","quel est mon objectif à hurlevent"}}},fp="14,142,19.590.0,15.532.0,27.258.0,21.287.1,17.236.1,19.351.2,30.238.0,35.216.0,38.251.1,48.261.1,50.272.0,40.223.0,65.267.0"}
P.entries["zone:stranglethorn"] = {n="Vallée de Strangleronce",s="La Vallée de Strangleronce est une jungle dense et sauvage qui domine la pointe sud des Royaumes de l'est, au sud du Bois de la Pénombre. Autrefois siège du grand empire Gurubashi, cette forêt tropicale est désormais parsemée de ruines de trolls en ruine, de bêtes féroces et de campements rivaux de gobelins, de pirates et de soldats. Le contrôle de la région est âprement disputé par les tribus locales de trolls, la KapitalRisk et des factions rivales qui tentent de s'implanter sous cette chaleur étouffante.",h="La Vallée de Strangleronce est une jungle dense et sauvage qui domine la pointe sud des Royaumes de l'est, au...",kw={"la voile sanglante","baie-du-butin","grom'gol","gurubashi","kurzen","nesingwary","revilgaz","vallée de strangleronce","kapitalrisk","zul'gurub"},ang={["class:Hunter"]="La berge nord abrite le célèbre chasseur de grand gibier Hemet Nesingwary, qui met au défi les tireurs d'élite d'éprouver leur courage en traquant les raptors, panthères et crocolisques les plus féroces de la jungle.",["faction:Alliance"]="Les tentatives historiques de Hurlevent pour conquérir et pacifier la jungle ont lourdement endetté le royaume, et ses intérêts ne sont aujourd'hui défendus que par des mutins mis à rude épreuve au Camp rebelle.",["faction:Horde"]="Le Campement Grom'gol offre à la Horde un bastion stratégique indispensable sur le continent sud, ravitaillé directement par des zeppelins depuis Durotar et Fossoyeuse.",["profession:Herbalism"]="La canopée humide nourrit une flore précieuse, faisant des berges et des côtes un terrain idéal pour cueillir de l'Aciérite sauvage, du Pâlerette, de la Dorépine et du Lotus pourpre.",["race:Troll"]="Strangleronce est le berceau ancestral des trolls des jungles, dont l'ancien empire Gurubashi a sombré dans la guerre civile après avoir vénéré Hakkar l'Écorcheur d'âmes, poussant des tribus comme les Sombrelance à traverser les mers."},sec={{t="Ruines d'un empire",b="Pendant des millénaires, la vallée fut gouvernée par le puissant empire Gurubashi depuis sa capitale, Zul'Gurub. Cette domination s'est effondrée lorsque des prêtres radicaux ont invoqué Hakkar l'Écorcheur d'âmes, plongeant la région dans une guerre civile catastrophique. Bien que les Zandalari soient intervenus pour écraser le soulèvement du dieu du sang, l'empire s'est brisé de manière irréversible. Aujourd'hui, la jungle est envahie par des factions rivales issues de cette scission — principalement les Scalp-rouges au nord-ouest et les Tranche-tête à l'est —, toutes deux massacrant farouchement les intrus pour reconquérir leur terre ancestrale."},{t="Pirates et profiteurs",b="Là où les ruines antiques deviennent silencieuses, la cupidité commerciale comble le vide. À la pointe sud se trouve Baie-du-Butin, un havre animé bâti par le Cartel Gentepression et dirigé par les Gentepression sous le commandement du Baron Revilgaz. Le port constitue la plaque tournante majeure du commerce méridional et du transport maritime, bien qu'il soit perpétuellement assiégé par les rivaux de La Voile sanglante ancrés le long de la côte. Plus à l'intérieur des terres, la KapitalRisk dépouille agressivement la jungle de son bois et exploite les collines pour en extraire de rares cristaux chantants."},{t="Une contrée sauvage disputée",b="La Vallée de Strangleronce constitue l'une des zones frontalières les plus instables du monde. La Horde contrôle le Campement Grom'gol sur la côte ouest, relié par des zeppelins gobelins à Durotar et aux Clairières de Tirisfal, tandis que les loyalistes de l'Alliance opèrent depuis le Camp rebelle pour traquer le renégat Colonel Kurzen. Au cœur du feuillage dense, le légendaire chasseur Hemet Nesingwary mène d'audacieuses expéditions de grand gibier, entraînant les voyageurs dans de périlleuses confrontations avec des panthères en maraude, d'immenses singes et des soldats ennemis."},{t="La folie dans la jungle",b="Toutes les menaces du nord de Strangleronce ne sont pas des bêtes sauvages. Le Colonel Kurzen, autrefois un commandant décoré envoyé par Hurlevent, a sombré dans la folie au cœur des taillis et a établi une redoute de mercenaires tyrannique. En réalité, l'esprit de Kurzen a été envoûté par la sorcellerie de la Vue de l'esprit, un artefact manié par le mage ogre Mai'Zoth du Tertre des ogres Mosh'Ogg tout proche, plongeant l'expédition dans une démence totale et poussant ses anciens hommes à faire sécession pour fonder le Camp rebelle."}},faq={{q="Qui contrôle la Vallée de Strangleronce ?",a="Aucune puissance unique ne règne sur la vallée. La jungle est partagée entre des tribus rivales de trolls des jungles comme les Scalp-rouges et les Tranche-tête, des campements dissidents comme la Base de Kurzen, les mercenaires de la KapitalRisk, ainsi que des avant-postes militaires dispersés de la Horde et de l'Alliance. La plus grande colonie urbaine est le port gobelin neutre de Baie-du-Butin, administré par le Baron Revilgaz et les Gentepression.",al={"qui possède strangleronce","qui dirige la vallée de strangleronce","factions de strangleronce"}},{q="Qu'est-ce que Baie-du-Butin ?",a="Baie-du-Butin est une vaste cité portuaire bâtie sur les falaises méridionales du cap Strangleronce. À l'origine un campement humain connu sous le nom de Crique des Flots noirs, elle a été capturée par les trolls avant d'être finalement sécurisée par le Cartel Gentepression. Aujourd'hui, le Baron Revilgaz et l'Amiral Corne-de-mer la gèrent comme un port de commerce neutre reliant les voyageurs à Cabestan à travers La Grande mer.",al={"qu'est-ce que baie-du-butin","port de baie-du-butin","qui dirige baie-du-butin"}},{q="Pourquoi le Colonel Kurzen est-il devenu un renégat ?",a="Le Colonel Kurzen a mené une expédition dans la jungle pour le compte de Hurlevent, mais son esprit a succombé à l'emprise de Mai'Zoth, un mage ogre maniant une puissante relique appelée la Vue de l'esprit. Kurzen est devenu de plus en plus erratique et despotique, forçant des soldats loyaux comme le lieutenant Doren à faire sécession et à fonder le Camp rebelle pour l'arrêter.",al={"pourquoi kurzen est mauvais","qu'est-il arrivé à kurzen","histoire de kurzen"}},{q="Qu'est-ce que Zul'Gurub ?",a="Zul'Gurub est l'ancienne capitale aux multiples temples de l'empire Gurubashi, nichée dans le nord-est de Strangleronce. Elle fut l'épicentre de la guerre civile qui mit fin à l'empire il y a quinze siècles, après que des prêtres radicaux eurent invoqué le dieu du sang Hakkar l'Écorcheur d'âmes. Bien que longtemps abandonnée à la végétation et aux ruines, de sombres rituels continuent de menacer ses salles.",al={"qu'est-ce que zg","histoire de zul'gurub","capitale des gurubashi"}},{q="Qu'était la Pierre des Marées ?",a="La Pierre des Marées est une relique légendaire de l'histoire ancienne des Gurubashi, découverte sur la côte par un guerrier troll. Elle conférait à son porteur la maîtrise de l'eau et des invocations élémentaires comparables à celles d'un puissant mage, valant à son détenteur le titre de « Porteur des marées ». Cependant, elle portait une malédiction qui poussait son porteur à s'effacer lentement du royaume physique, conduisant chacun d'eux à marcher dans la mer et à disparaître.",al={"pierre des marées","légende du porteur des marées","pierre de l'eau gurubashi"}},{q="Comment voyager vers la Vallée de Strangleronce ?",a="Les voyageurs peuvent marcher vers le sud en traversant la frontière fluviale depuis le Bois de la Pénombre pour entrer dans le nord de Strangleronce. La Horde entretient des tours de zeppelin directes reliant le Campement Grom'gol à Durotar et aux Clairières de Tirisfal. Les voyageurs venant de Kalimdor peuvent également monter à bord du navire marchand régulier qui fait la navette entre Cabestan dans Les Tarides et Baie-du-Butin.",al={"comment aller à la vallée de strangleronce","se rendre à strangleronce","voyage vers strangleronce"}}},fp="18,166,18.455.0,22.346.0,22.414.0,25.340.1,32.270.0,18.322.0,32.268.1,18.294.0,32.328.0,38.256.0"}
P.entries["zone:swampofsorrows"] = {n="Marais des Chagrins",s="Le Marais des Chagrins est une zone humide saumâtre et trouble coincée entre le Défilé de Deuillevent et les arides Terres Foudroyées. Autrefois étendue septentrionale de l'ancien Black Morass, ses tourbières encroûtées de sel abritent une faune dangereuse, des dragonnets verts et les ruines du temple d'Atal'Hakkar englouti sous le Bassin des larmes. Alors que la Horde maintient la garnison fortifiée de Pierrêche, l'Alliance ne dispose d'aucun refuge au sein du bourbier, laissant ces terres sauvages largement indomptées.",h="Le Marais des Chagrins est une zone humide saumâtre et trouble coincée entre le Défilé de Deuillevent et les...",kw={"black morass","roués","le havre boueux","perdus","bassin des larmes","noirchagrin","pierrêche","temple englouti","marais des chagrins","le temple d'atal'hakkar"},ang={["faction:Alliance"]="Sans aucun avant-poste où se regrouper, voyager à travers le marais est une entreprise isolée et hostile qui requiert une préparation minutieuse depuis Sombre-Comté ou Rempart-du-Néant.",["faction:Horde"]="Pierrêche sert de redoute avancée essentielle sur le continent sud, proposant des trajets directs en wyverne vers Kargath, la Corniche des Flammes, le Campement Grom'gol, Baie-du-Butin et Rog’mar dans les Rives Claires.",["profession:Blacksmithing"]="Les aventuriers endurcis peuvent récolter du fer, de l'or, du mithril et du vrai-argent le long des crêtes montagneuses qui bordent les lisières nord et sud du marais.",["profession:Herbalism"]="Le marécage est l'un des rares endroits d'Azeroth riches en aveuglette, aux côtés de généreuses pousses de vietérule, de pâlerette et d'étouffante.",["race:Troll"]="Les ruines englouties d'Atal'Hakkar rappellent cruellement la sombre magie du sang qui a brisé l'Empire Gurubashi et provoqué la colère des Aspects draconiques."},sec={{t="Une histoire engloutie",b="Bien avant l'arrivée de la Horde des Orcs, ces marais formaient la moitié nord d'une gigantesque zone humide connue sous le nom de Black Morass. À la suite de la dislocation de l'Empire Gurubashi, les trolls Atal'ai fanatiques s'enfuirent dans le bourbier pour y ériger le temple d'Atal'Hakkar, avec l'intention d'invoquer leur sanguinaire loa, Hakkar the Soulflayer. Pressentant la catastrophe, l'Aspect Ysera déchaîna ses pouvoirs, noyant la pyramide maudite sous les eaux du Bassin des larmes. Des gardiens du Vol draconique vert menés par Eranikus furent postés là afin de veiller sans relâche sur l'édifice submergé. Lorsque le cataclysme de la Porte des ténèbres calcina plus tard le marécage méridional pour en faire les Terres Foudroyées, ce marais du nord gagna son nom affligé actuel."},{t="Avant-postes et exilés Roués",b="Pierrêche constitue le principal point d'ancrage civilisé du marais. Établi à l'origine durant la Première Guerre aux côtés des colonies aujourd'hui ruinées de Rockard et Kyross, l'avant-poste a été reconstruit sous la direction de Thrall pour servir de base avancée la plus méridionale de la Horde dans les Royaumes de l'est. Au-delà des palissades de Pierrêche, d'étranges vagabonds arpentent le marécage. Un groupe de traînards draeneï échoués sur Azeroth a sombré dans le mal du pays et la folie, dégénérant en Perdus sauvages. Cependant, une petite enclave d'exilés Roués lucides subsiste au Havre boueux, méfiante mais disposée à commercer pacifiquement avec les voyageurs."},{t="Le bourbier mouvant",b="Survivre dans le marais exige une vigilance constante face à sa faune prédatrice. Les tourbières profondes dissimulent des crocolis bondissants, des araignées venimeuses, des jaguars des marais en maraude et des bêtes des tourbières errantes recouvertes de débris marécageux. Les cavernes côtières et la Grève de Brumejonc grouillent de murlocs vicieux, tandis que la marée chargée de sel s'infiltre continuellement à l'intérieur des terres, préservant les troncs pourris sous d'épaisses croûtes salines. Plus à l'est s'étend Noirchagrin, où d'agressifs dragonnets d'élite gardent farouchement les abords du Temple englouti, attaquant quiconque s'égare à proximité de leur faction."}},faq={{q="Comment se rendre au Marais des Chagrins ?",a="L'itinéraire terrestre le plus emprunté part vers l'est depuis Sombre-Comté dans le Bois de la Pénombre, traverse le périlleux défilé hanté du Défilé de Deuillevent, et descend tout droit dans le marais. Les voyageurs venant du sud peuvent également marcher vers le nord en suivant la route principale qui quitte les Terres Foudroyées.",al={"comment aller au marais des chagrins","route du marais des chagrins","aller à pierrêche"}},{q="Pourquoi le temple d'Atal'Hakkar est-il sous l'eau ?",a="Il y a des siècles, le sacerdoce atal'ai tenta d'invoquer Hakkar the Soulflayer en Azeroth. Ysera, l'Aspect draconique du Vol vert, découvrit leurs rites de sang démoniaques et noya l'intégralité du temple dans le marécage pour conjurer le désastre, laissant des dragonnets verts pour garder les salles submergées.",al={"pourquoi le temple englouti est englouti","qui a coulé le temple","lore du temple englouti"}},{q="Qu'est-ce que Pierrêche ?",a="Pierrêche était l'une des premières colonies bâties par la Horde des Orcs après avoir franchi la Porte des ténèbres durant la Première Guerre. Bien que ravagée pendant les combats, elle a été récemment reprise et reconstruite sur ordre de Thrall pour ancrer la logistique de la Horde près des Terres Foudroyées.",al={"histoire de pierrêche","base orc dans le marais","qui a construit pierrêche"}},{q="Y a-t-il des campements de l'Alliance ici ?",a="Non. L'Alliance ne maintient aucune ville, aucun garde ni aucun maître de vol dans le Marais des Chagrins. Les aventuriers de l'Alliance opérant dans la région doivent s'établir à Sombre-Comté dans le Bois de la Pénombre à l'ouest ou à Rempart-du-Néant dans les Terres Foudroyées au sud.",al={"base alliance marais des chagrins","trajet aérien alliance marais","où est le camp de l'alliance"}},{q="Qui sont les étranges humanoïdes mutants du marais ?",a="Ce sont des draeneï restés bloqués sur Azeroth à la suite de l'effondrement de la Porte des ténèbres. Coupés de leur monde, la plupart ont sombré dans la folie sous le coup du désespoir et sont devenus des Perdus hostiles. Une petite poche d'exilés Roués sains d'esprit a trouvé refuge au nord-ouest au Havre boueux, préférant une survie neutre à une fureur aveugle.",al={"qui sont les perdus","qu'est-ce que le havre boueux","draeneï dans le marais"}},{q="Qu'est-ce que Noirchagrin ?",a="Noirchagrin est l'étendue dense de marécages située directement à l'est du Bassin des larmes. Elle sert de zone de patrouille à des dragonnets verts d'élite et des dragonnets qui repoussent violemment les mortels afin de protéger les secrets du Temple englouti.",al={"zone des dragons marais des chagrins","dragons de noirchagrin","dragonnets verts marais"}}},fp="16,249,17.556.0,26.487.0,16.475.0,36.188.0,44.259.0,16.248.0,40.179.0,51.307.0,19.185.0"}
P.entries["zone:tanaris"] = {n="Tanaris",s="Tanaris est un vaste désert étouffant qui s'étend sur les confins méridionaux de Kalimdor, caractérisé par des dunes de sable ondulantes et une chaleur torride. En son cœur se trouve Gadgetzan, un avant-poste commercial neutre dirigé par les gobelins du Cartel Gentepression. Au-delà des colonies animées, les dunes dissimulent des trolls des sables hostiles, de dangereuses ruches de silithides et le domaine caché du Vol draconique de bronze.",h="Tanaris est un vaste désert étouffant qui s'étend sur les confins méridionaux de Kalimdor, caractérisé par...",kw={"grottes du temps","désert","southsea freebooters","gadgetzan","nozdormu","sandfury","silithide","gentepression","tanaris","uldum","zul'farrak"},ang={["faction:Alliance"]="En l'absence de bastions majeurs de l'Alliance entre le Marécage d’Âprefange et Féralas, le maître de vol de l'Alliance dans la ville neutre de Gadgetzan sert de base de transit vitale pour les voyages à travers le sud de Kalimdor.",["faction:Horde"]="Gadgetzan offre aux éclaireurs de la Horde une plaque tournante commerciale pratique reliant les trajets depuis le Poste de Librevent et le Camp Mojache directement aux étendues sauvages infestées de silithides du grand sud.",["profession:Herbalism"]="La chaleur sèche nourrit l'insaisissable Fleur de feu à travers les dunes mouvantes, tandis que les ruines ombragées et les oasis humides offrent un abri au précieux Lotus pourpre.",["profession:Mining"]="Les falaises arides et les affleurements rocheux entourant les dunes offrent de riches filons de mithril, de vrai-argent, de fer et d'or, ainsi que des gisements dispersés de petit thorium dans les profondeurs les plus reculées.",["race:Troll"]="Voir les Sandfury de Zul'Farrak offre aux trolls un regard saisissant sur leurs anciens cousins, qui se sont endurcis en une culture brutale dans l'isolement du désert."},sec={{t="Une mer de dunes",b="Tanaris est une étendue sauvage, aride et brûlée par le soleil. À l'intérieur de la cité fortifiée de Zul'Farrak, les rudes trolls Sandfury gardent leur domaine isolé. Aujourd'hui, le sol du désert est dominé par les hyènes, les basilics et les scorpides, tandis que des tunnels souterrains serpentent sous la terre brûlante."},{t="Entreprise gobeline",b="Parce que Tanaris est aussi proche de leur île natale de Kezan que le continent le permet, le Cartel Gentepression y a établi une entreprise prospère. De l'oasis fortifiée de Gadgetzan aux quais côtiers de Port Gentepression, les gobelins maintiennent une stricte neutralité, accueillant les pièces de monnaie de l'Alliance comme de la Horde. Leur paix est maintenue par la force de redoutables cogneurs, bien que des menaces d'éléments voleurs comme les Southsea Freebooters harcèlent constamment le transport maritime et les sites de fouilles le long du littoral."},{t="Mystères anciens et périls grandissants",b="Les sables dissimulent des puissances bien plus anciennes que les empires mortels. Dans les étendues orientales se trouvent les Grottes du temps, le domaine ancestral de Nozdormu et de son Vol draconique de bronze, dont on peut parfois apercevoir les drakes chevaucher les courants thermiques du désert. Au sud, d'imposantes portes de pierre marquent le complexe titan d'Uldum. Pourtant, un danger plus sombre s'agite depuis des nids souterrains tels que Le Gouffre béant et Le Repaire nuisible, où des essaims rampants de silithides ont commencé à creuser des galeries à travers les sables."}},faq={{q="Comment puis-je voyager jusqu'à Tanaris ?",a="Les voyageurs à pied traversent les Mille pointes pour se rendre dans les Salines. Un col de montagne taillé à travers les falaises à l'extrémité sud des étendues de sel mène directement au désert, vous amenant aussitôt en vue des remparts de Gadgetzan. Un navire fait également la traversée depuis le Port de Poudremèche dans les Rives Claires jusqu'au Port Gentepression sur la côte orientale.",al={"comment aller à tanaris","se rendre à tanaris","entrée de tanaris"}},{q="Pourquoi Gadgetzan est-elle neutre envers les deux factions ?",a="Gadgetzan est gouvernée par le Cartel Gentepression, dont la seule allégeance va au profit. Afin de maximiser le commerce et de protéger les routes marchandes à travers le désert, les gobelins imposent une stricte neutralité, employant des cogneurs pour rosser quiconque est assez insensé pour déclencher des rixes de factions dans l'enceinte de leur ville.",al={"pourquoi gadgetzan est neutre","la horde et l'alliance peuvent-elles aller à gadgetzan","neutralité gobeline gadgetzan"}},{q="Qu'est-ce que Zul'Farrak ?",a="Zul'Farrak est la capitale fortifiée du désert des trolls Sandfury. Longtemps isolée dans le désert, la tribu Sandfury est devenue hostile à tous les étrangers, protégeant ses bassins sacrés et ses sanctuaires mystérieux des aventuriers intrusifs.",al={"qu'est-ce que zul'farrak","qui vit à zul'farrak","cité des trolls des sables"}},{q="Quelles sont ces créatures insectoïdes qui nichent à travers le désert ?",a="Ces bêtes insectoïdes sont des silithides, de monstrueux fouisseurs coloniaux qui bâtissent de vastes ruches telles que Le Gouffre béant et Le Repaire nuisible. Leur émergence en Tanaris a troublé des observateurs tels que le Grand Géomètre Radiésthéflop, rappelant les horreurs ancestrales de la guerre des Sables mouvants.",al={"quels sont les insectes de tanaris","ruches d'insectes de tanaris","silithides à tanaris"}},{q="Qu'y a-t-il derrière les massives portes de pierre au sud ?",a="Les portes monumentales de la Vallée des guetteurs marquent l'entrée d'Uldum, un légendaire centre de recherche et domaine des anciens titans. L'entrée demeure fermement scellée, gardée par des sentinelles colossales de pierre et observée de loin par des érudits et des gobelins curieux.",al={"portes géantes au sud de tanaris","portes de ruins of uldum","porte des titans tanaris"}},{q="Qui réside à l'intérieur des Grottes du temps ?",a="Les Grottes du temps servent de repaire ancestral au Vol draconique de bronze et à leur aspect, Nozdormu. Depuis ces profondeurs sinueuses et cachées, les dragons intemporels veillent sur le cours de l'histoire, patrouillant parfois dans les cieux haut au-dessus des dunes méridionales.",al={"histoire des grottes du temps","que trouve-t-on dans les grottes du temps","dragons à tanaris"}}},fp="7,203,14.233.0,17.333.0,35.335.0,27.288.0,42.224.0,19.175.0,56.255.0,52.219.0,38.232.0"}
P.entries["zone:teldrassil"] = {n="Teldrassil",s="Teldrassil, qui signifie « Couronne de la terre », est un nouvel Arbre-Monde gargantuesque dressé au large de la côte nord-ouest de Kalimdor. Fait pousser par les druides au lendemain de la Troisième guerre, ses branches colossales abritent une contrée crépusculaire tout entière ainsi que la capitale des Elfes de la nuit, Darnassus. Pourtant, sous sa canopée paisible et baignée par la lune, une insidieuse corruption commence à s'éveiller.",h="Teldrassil, qui signifie « Couronne de la terre », est un nouvel Arbre-Monde gargantuesque dressé au large de...",kw={"cercle des anciens","la couronne de la terre","darnassus","dolanaar","fandral forteramure","rut'theran","sombrevallon","teldrassil","arbre-monde"},ang={["class:Druid"]="Malfurion étant piégé dans Le Rêve d'émeraude, l'archidruide Fandral Forteramure dirige le Cercle cénarien ici, bien que de nombreux druides craignent que Teldrassil n'ait été érigé avec trop de précipitation.",["faction:Alliance"]="Teldrassil sert de bastion le plus septentrional de l'Alliance en Kalimdor, assurant les liaisons maritimes et le commerce entre Darnassus et les royaumes du continent.",["profession:Herbalism"]="Dépourvue de minéraux et de minerai, la canopée verdoyante de l'arbre compense ce manque en offrant un véritable paradis aux cueilleurs de Pacifique, de Feuillargent et de Terrotine.",["race:NightElf"]="Cet arbre colossal représente le nouveau départ de votre peuple après la dévastation du Mont Hyjal, mais l'absence des bénédictions des Aspects fait de sa défense un devoir urgent."},sec={{t="Une canopée sur la mer",b="Teldrassil n'est pas simplement un arbre : c'est un écosystème surélevé qui se dresse au milieu des flots de la Mer voilée. Ses branches gigantesques soutiennent des collines ondulantes, des rivières alimentées par la rosée matinale, des lacs brumeux et d'antiques clairières denses. À son extrémité occidentale se trouve Darnassus, la majestueuse capitale des kaldorei. Au pied de son tronc monumental repose Rut'theran, relié à la cime par un portail mystique et servant de port principal à l'île."},{t="Le refus des Aspects",b="Après le sacrifice de Nordrassil pendant la Troisième guerre et la mystérieuse disparition de Shan'do Malfurion Hurlorage dans Le Rêve d'émeraude, l'archidruide Fandral Forteramure convainquit le Cercle des Anciens de lui faire pousser un remplaçant. Staghelm espérait ainsi rendre aux kaldorei leur immortalité perdue. Toutefois, Nozdormu et les Aspects dragons jugèrent cette entreprise empreinte d'arrogance et refusèrent leurs bénédictions. Privé de leur protection vitale, Teldrassil a vu sa croissance entachée d'imperfections contre nature."},{t="Un mal insidieux",b="Malgré sa majesté apparente, le jeune Arbre-Monde abrite un sombre mal. La faune locale est devenue violente : des tribus pacifiques de furbolgs ont sombré dans la folie, d'ignobles grells prolifèrent dans les tanières, et de vils satyres accomplissent de sombres rituels dans des recoins obscurs comme Gangreroche. Plus bas, sur les rivages de Sombrivage, des géants des mers, des batteurs et des tortues s'échouent pour fuir les eaux souillées entourant l'arbre. Naturalistes et sentinelles s'efforcent désormais d'arrache-pied, à travers les ramures, d'identifier l'ombre qui étouffe peu à peu leur nouveau foyer."}},faq={{q="Pourquoi Teldrassil a-t-il été créé ?",a="Après la dévastation de Nordrassil à la fin de la Troisième guerre, les Elfes de la nuit perdirent leur immortalité. L'archidruide Fandral Forteramure incita le Cercle des Anciens et les druides cénariens à planter un nouvel Arbre-Monde dans la mer, dans l'espoir de rendre à son peuple ce qu'il avait perdu.",al={"pourquoi cree","qui a cree teldrassil","origine de teldrassil"}},{q="Pourquoi Teldrassil n'a-t-il pas restauré l'immortalité des Elfes de la nuit ?",a="Nordrassil conférait à l'origine l'immortalité parce que Nozdormu, l'Intemporel, l'avait béni. Lorsque Teldrassil fut érigé, Nozdormu jugea le désir des Elfes de la nuit orgueilleux et refusa d'accorder sa bénédiction au nouvel arbre.",al={"immortalite","pourquoi pas immortel","benediction de nozdormu"}},{q="Comment quitte-t-on Teldrassil ?",a="Les voyageurs doivent traverser Darnassus jusqu'au portail rose situé dans Les Jardins du temple, qui les transporte en bas à Rut'theran, au pied du tronc. Depuis Rut'theran, un navire fait la traversée jusqu'à Auberdine sur le continent de Sombrivage, en plus des trajets en hippogriffe disponibles.",al={"comment sortir","quitter l'arbre","bateau teldrassil"}},{q="Pourquoi n'y a-t-il aucun gisement de minerai à Teldrassil ?",a="La zone tout entière repose sur les branches vivantes et le bois d'un Arbre-Monde colossal plutôt que sur la roche d'un continent naturel. En l'absence de croûte souterraine pierreuse, aucun filon de métal ni gisement de minerai ne s'y forme, bien que les herbes y prolifèrent en abondance.",al={"ou trouver du cuivre","pas de minerai","minage teldrassil"}},{q="Qu'est-ce qui rend les furbolgs et les bêtes sauvages fous ?",a="Une présence sinistre a commencé à s'infiltrer dans les racines non bénies de Teldrassil. Une maladie a corrompu l'eau et la flore locales, poussant de paisibles scythes et la tribu des furbolgs de Gnarlpine à une agressivité frénétique, tandis que des survivants satyres entretiennent activement cette souillure.",al={"furbolgs corrompus","gnarlpine fou","quelle est la corruption"}},{q="Qu'est-ce que Sombrevallon ?",a="Sombrevallon est un vallon abrité et isolé sur les branches orientales de Teldrassil, entourant le grand arbre Aldrassil. Il sert de sanctuaire paisible où les jeunes Elfes de la nuit commencent leur entraînement avant de s'aventurer dans le vaste monde.",al={"sombrevallon","zone de depart","zone d'aldrassil"}}},fx={["11a6d5e5"]={q="Qu'est-ce que Teldrassil ?",a="Teldrassil est un immense Arbre-Monde qui pousse sur une île au large de la côte nord-ouest de Kalimdor. Son tronc gigantesque s'élève de la mer des Voiles, s'étendant en branches si vastes qu'elles soutiennent un royaume forestier entier composé de lacs, de rivières et de la capitale Darnassus au sommet de sa canopée.",al={"qu'est-ce que cet endroit","à propos de teldrassil","parlez-moi de teldrassil"}},["313cd5a2"]={q="Que s'est-il passé à Teldrassil ?",a="Suite à la Troisième Guerre et aux dommages causés au Nordrassil du Mont Hyjal, le druide Malfurion Hurlorage a disparu. En son absence, l'archidruide Fandral Forteramure a convaincu le Cercle des Anciens de faire pousser un nouvel Arbre-Monde pour remplacer ce qui avait été perdu. Bien que la pousse ait réussi, une corruption rampante a depuis commencé à souiller ses branches.",al={"histoire de teldrassil","comment teldrassil a été créé","événements à teldrassil"}},c5e34e84={q="Qui vit ou dirige Teldrassil ?",a="Teldrassil est le refuge ancestral et la patrie actuelle des elfes de la nuit. Spirituellement et civilement, la grande prêtresse Tyrande Murmevent et l'archidruide Fandral Forteramure guident leur peuple depuis la capitale de Darnassus, soutenus par la Communauté d'Elune, les druides cénariens et les guerriers sentinelles qui gardent les colonies forestières.",al={"qui dirige teldrassil","dirigeants de teldrassil","qui vit ici"}},b86e706e={q="Teldrassil est-elle dangereuse ?",a="Bien que protégée par les Sentinelles, Teldrassil est de plus en plus périlleuse. Une sombre affliction a rendu fous les bêtes indigènes et les furbolgs locaux, tandis que des satyres malveillants, des harpies assoiffées de sang et des sylvaris rampants menacent les colonies au-delà des routes patrouillées.",al={"est-ce sûr ici","menaces à teldrassil","dangers de teldrassil"}},["2863bed2"]={q="Pourquoi l'appelle-t-on Teldrassil ?",a="Dans la langue darnassienne des elfes de la nuit, Teldrassil se traduit directement par 'couronne de la terre'. Il a été nommé en l'honneur de son rôle d'Arbre-Monde monumental destiné à bercer et à protéger leur civilisation.",al={"que signifie teldrassil","signification du nom teldrassil"}},["514d23b0"]={q="Qui est Fandral Forteramure ?",a="Fandral Forteramure est l'archidruide qui a pris la tête des druides elfes de la nuit après la disparition de Malfurion Hurlorage dans le Rêve d'émeraude. Passionné, têtu et agressif, Fandral a défendu la plantation de Teldrassil et s'oppose fréquemment à la grande prêtresse Tyrande Murmevent sur la politique à suivre.",al={"qui est l'archidruide","lore de fandral forteramure","forteramure"}},["52c333ac"]={q="Qui est Tyrande Murmevent ?",a="Tyrande Murmevent est la grande prêtresse de la déesse Elune et la chef suprême du peuple elfe de la nuit. Ayant guidé son peuple pendant dix mille ans à travers la Longue Veille et la Troisième Guerre, elle dirige désormais depuis The Temple of the Moon à Darnassus.",al={"qui est tyrande","grande prêtresse tyrande","qui dirige les elfes de la nuit"}},["29b1e9e4"]={q="Comment suis-je arrivé à Teldrassil ?",a="Si vous êtes un elfe de la nuit, cet immense Arbre-Monde est la nouvelle terre natale de votre peuple. Après avoir sacrifié Nordrassil et votre immortalité antique au sommet du Mont Hyjal pour vaincre la Légion ardente, les kaldorei se sont réinstallés au large de la côte nord-ouest de Kalimdor. L'archidruide Fandral Forteramure et le Cercle des Anciens ont fait pousser Teldrassil dans la mer des Voiles pour offrir à votre race un refuge renouvelé, et vous avez commencé votre périple au sein de ses branches verdoyantes à Sombrevallon. Si vous êtes venu de l'étranger, vous avez probablement navigué vers le port de Rut'theran à la base de l'arbre depuis Sombrivage, puis vous avez traversé le portail lumineux qui transporte directement les voyageurs vers la couronne.",al={"comment suis-je arrivé à teldrassil","comment suis-je arrivé ici","pourquoi est-ce mon point de départ"}},["8381279f"]={q="Que suis-je censé faire à Teldrassil ?",a="Vous êtes appelé à protéger le jeune Arbre-Monde et à découvrir la sombre maladie qui perturbe ses branches. Malgré ses forêts luxuriantes, une corruption sinistre s'installe : les sylvaris deviennent agressifs, les furbolgs paisibles de la tribu Gnarlpine sombrent dans la folie, et de vils satyres se cachent dans des fourrés sombres comme Gangreroche. En commençant par Sombrevallon et en aidant les colonies comme Dolanaar, vous devez aider les Sentinelles et les druides à rétablir l'équilibre. Vous régénérerez les puits de lune sacrés, éradiquerez la vermine corrompue et apprendrez l'histoire de votre peuple avant de vous aventurer dans la capitale de Darnassus et à travers la mer vers le continent de Kalimdor.",al={"que faire à teldrassil","pourquoi suis-je ici","quelle est ma mission ici"}}},fp="10,168,21.379.0,26.466.0,17.410.1,25.260.0,52.182.0,28.253.0,44.210.0,52.248.0,19.205.0"}
P.entries["zone:thousandneedles"] = {n="Mille pointes",s="Les Mille pointes forment un vaste canyon de vertigineux piliers de grès et d'étendues de sel cuites par le soleil dans le sud de Kalimdor. Les tribus taurens s'accrochent à des campements érigés au sommet d'imposantes mesas pour échapper aux meutes agressives de centaures, tandis que des bricoleurs gnomes et gobelins pilotent des fusées sur roues à toute allure à travers l'ancien fond marin asséché des Salines.",h="Les Mille pointes forment un vaste canyon de vertigineux piliers de grès et d'étendues de sel cuites par le...",kw={"garde-falaise longue-corne","cime de noir-nuage","féplouf zéboulon","poste de librevent","la grande élévation","totem sinistre","kravel koalbarbe","piste des mirages","pozzik","les salines","mille pointes"},ang={["faction:Horde"]="La Grande élévation relie les Tarides à votre bastion du Poste de Librevent, servant de frontière stratégique méridionale contre les clans centaures et les taurens rebelles.",["profession:Engineering"]="Le désert de sel est un lieu de pèlerinage pour les bricoleurs désireux d'étudier le carburant de fusée, les pièces détachées et la propulsion à grande vitesse sur la Piste des mirages.",["race:Gnome"]="La Piste des mirages dans les Salines est l'occasion rêvée pour votre faction de démontrer la précision et l'élégance de l'ingénierie gnome face aux bricolages douteux des gobelins.",["race:Tauren"]="Le Poste de Librevent rappelle à quel point votre peuple a dû s'élever pour échapper aux massacres des centaures, et sert de base d'opérations contre les traîtres Totems-sinistres de la Cime de Noir-nuage."},sec={{t="Une forêt de pierre",b="Avant que la Grande Fracture ne brise l'ancien Kalimdor, ce territoire était un canyon fluvial luxuriant alimenté par des cours d'eau intérieurs qui s'écoulaient vers la mer. Le cataclysme déchira le continent, propulsant le lit de la rivière au-dessus de la nappe phréatique et détournant son cours jusqu'à ce qu'il ne reste plus que de la roche sèche et des aiguilles de grès. Aujourd'hui, des dizaines de colonnes cylindriques élancées s'élèvent du fond du canyon telles une forêt pétrifiée. Les taurens se sont installés sur les sommets, tendant de précaires ponts de corde entre les pics pour fonder des villages hors de portée des maraudeurs centaures hostiles qui patrouillent en contrebas dans l'ombre du canyon."},{t="Péril sur les mesas",b="Au sommet de ces aiguilles rocheuses, la vie est loin d'être paisible. Au Poste de Librevent, les taurens loyaux à la Horde doivent non seulement composer avec les serpents ailés prédateurs et les wyvernes de Haut-perchoir, mais aussi avec leurs perfides congénères : le clan belliqueux des Totems-sinistres, retranché à la Cime de Noir-nuage. Le Garde-falaise Longue-corne supervise la défense du plateau, cherchant de hardis combattants pour frapper les agitateurs Totems-sinistres et sécuriser les fragiles ponts reliant les pics. Au nord, les gigantesques treuils mécaniques de la Grande élévation transportent les voyageurs depuis les Tarides du sud, bien que traverser le fond du canyon demeure un pari mortel."},{t="La Piste des mirages",b="Au sud-est, les parois du canyon s'ouvrent sur les Salines, un énorme désert de sel asséché situé sous le niveau de la mer. Dans cette étendue aride d'une blancheur aveuglante, gnomes et gobelins maintiennent une neutralité précaire autour de la Piste des mirages. Deux ingénieurs rivaux, Pozzik et Féplouf Zéboulon, y font s'affronter des bolides à fusée expérimentaux sur le sel compact pour déterminer quelle race détient la supériorité technologique. Ce relais attire des gredins, des escrocs comme Kravel Koalbarbe, ainsi que des chasseurs traquant les robustes scorpions, tortues et basilics qui arpentent ce bassin torride."}},faq={{q="D'où vient le nom des Mille pointes ?",a="La région doit son nom aux dizaines d'imposantes aiguilles cylindriques de grès qui jaillissent du fond du canyon. Façonnées à l'origine par les puissants courants fluviaux avant la Grande Fracture, ces tours géologiques ressemblent désormais à une forêt d'aiguilles géantes.",al={"pourquoi mille pointes","origine piliers aiguilles","histoire aiguilles rocheuses"}},{q="Comment descendre dans les Mille pointes depuis les Tarides ?",a="Les voyageurs empruntent la Grande élévation, un immense monte-charge à deux cabines manœuvré par des gardes de la Horde à la frontière sud des Tarides. Sauter de la falaise étant fatal, il est indispensable d'attendre la plateforme. Les voyageurs de l'Alliance peuvent également y accéder à pied par l'ouest via Thalanaar en Féralas.",al={"comment aller aux mille pointes","entree grande elevation","ascenseur mille pointes"}},{q="Pourquoi les taurens vivent-ils au sommet des mesas ?",a="Les bandes de guerre centaures ont jadis failli mener les taurens nomades à l'extinction. L'édification d'avant-postes tels que le Poste de Librevent au sommet de piliers de pierre inaccessibles les a mis à l'abri des assauts terrestres. Ils ont ensuite relié les mesas par des ponts suspendus en bois, permettant de voyager en altitude au-dessus des prédateurs et des assaillants du sol.",al={"pourquoi taurens sur piliers","histoire poste de librevent","taurens en hauteur"}},{q="Qu'est-ce que la Piste des mirages ?",a="La Piste des mirages est un terrain d'essai d'ingénierie situé dans le désert de sel des Salines. Des bricoleurs gnomes et gobelins y lancent des bolides expérimentaux propulsés par fusée sur le sol plat et salé afin de départager leur rivalité perpétuelle et prouver qui conçoit les meilleures machines.",al={"piste des salines","course gnome gobelin","circuit bolide a fusee"}},{q="Quelle est la présence des Totems-sinistres dans le canyon ?",a="Le clan Totem-sinistre occupe la Cime de Noir-nuage, un ensemble d'aiguilles fortifiées faisant directement face au Poste de Librevent. Contrairement aux autres tribus taurens qui ont prêté allégeance à la Horde, les Totems-sinistres attaquent activement leurs semblables et complotent pour asseoir leur domination sur les mesas.",al={"totem sinistre mille pointes","cime de noir nuage taurens","taurens hostiles mille pointes"}},{q="Que sont les Salines ?",a="Les Salines sont un vaste lit de lac asséché situé à l'est des mesas du canyon. La croûte de sel s'est formée lorsque l'ancienne mer intérieure s'est évaporée après la Fracture. La chaleur cuisante, le sel d'une blancheur aveuglante et les féroces prédateurs en font un désert inhospitalier principalement dévolu aux essais de véhicules à grande vitesse.",al={"desert de sel","desert blanc mille pointes","desert oriental"}}},fx={["98fcff4e"]={q="Pourquoi tout n'est-il que canyons et piliers ?",a="Il y a des éons, avant la Grande Fracture, cette région était un canyon fluvial verdoyant creusé par des eaux vives s'écoulant vers l'est, depuis Féralas jusqu'à une mer intérieure. Lorsque le monde s'est brisé, le cataclysme a soulevé le lit de la rivière et a altéré son cours. Privée d'eau, la terre s'est asséchée, laissant derrière elle d'imposants piliers de grès et un lit de sel desséché.",al={"pourquoi y a-t-il des flèches rocheuses","comment les pointes se sont-elles formées","pourquoi des piliers de grès"}},["05d5c74f"]={q="Les Mille pointes sont-elles dangereuses ?",a="C'est un endroit très dangereux. Les centaures Galak barbares patrouillent le fond du canyon en bandes de pillards, tandis que des vautours prédateurs, des scorpidés et des harpies voleuses hantent les falaises. Même les ponts de corde entre les hautes cimes comportent des risques, car les oiseaux de proie fondent souvent sur les voyageurs imprudents ou endommagent les structures.",al={"quel est le danger aux mille pointes","dangers ici","est-ce sûr"}},["1b8e8bea"]={q="Pourquoi la Horde m'a-t-elle envoyé aux Mille pointes ?",a="La Horde maintient une présence vitale ici pour aider les tribus tauren locales qui subissent des assauts incessants. Le Poste de Librevent constitue un bastion critique reliant Les Tarides aux déserts du sud, et la Horde a besoin de braves champions pour repousser les centaures maraudeurs et étouffer les menaces internes.",al={"mission de la horde aux mille pointes","pourquoi suis-je ici horde","que veut la horde ici"}},a7c3b539={q="Est-ce une terre tauren ?",a="Oui. Les canyons arides et les hauts plateaux des Mille pointes ont traditionnellement été le territoire ancestral de plusieurs tribus tauren pendant d'innombrables générations, bien que des clans de centaures vicieux les aient poussés au bord de l'extinction avant l'arrivée de la Horde.",al={"les taurens possèdent-ils les mille pointes","territoire tauren","est-ce une terre shu'halo"}},fef8bf7c={q="Qu'est-ce que le Poste de Librevent ?",a="Le Poste de Librevent est l'avant-poste principal de la Horde dans les Mille pointes. Construit au sommet d'un immense plateau dominant le fond de la vallée, il dispose d'ascenseurs en bois, d'une tour de vol et d'un réseau de ponts suspendus reliant les cimes adjacentes.",al={"poste de librevent","qu'est-ce que le poste de librevent","village de librevent"}},["6ac472b0"]={q="Qui sont les centaures Galak et pourquoi nous attaquent-ils ?",a="La tribu Galak est composée de centaures locaux qui revendiquent le fond du canyon. Comme tous les centaures, ils sont férocement territoriaux, nomades et violents. Ils traquent tous les voyageurs traversant les gorges et cherchent à éradiquer complètement les colonies tauren.",al={"centaures galak","pourquoi les centaures attaquent","tribu galak"}},["9f0b1de8"]={q="Pourquoi détestent-ils les Tauren ?",a="L'inimitié entre les Tauren et les centaures est ancienne et implacable. Pendant des générations, à travers les plaines de Kalimdor, les centaures errants ont chassé les Tauren pour le sport et lancé des guerres brutales et non provoquées qui ont forcé les tribus pacifiques à fuir constamment.",al={"pourquoi les centaures détestent les taurens","querelle centaure tauren","rancune centaure"}},["0eee4587"]={q="Pourquoi des gobelins et des gnomes font-ils la course avec des voitures-fusées dans le désert ?",a="Le sel plat et ouvert des Salines constitue le terrain d'essai idéal pour tester des moteurs à grande vitesse. Les gnomes et les gobelins ont établi la Piste des mirages pour régler définitivement le différend de longue date sur la race possédant la meilleure ingénierie.",al={"pourquoi des voitures de course","course gobelin gnome","rivalité de voiture-fusée"}},e421f132={q="Qu'en est-il de la Cime de Noir-nuage et de ces notes secrètes ?",a="La Cime de Noir-nuage est la forteresse lourdement gardée de la tribu Grimtotem sur les plateaux à l'est de La Grande élévation. Une correspondance secrète découverte sur place révèle des contacts clandestins entre les chefs Grimtotem comme Arnak Grimtotem et une puissance sombre inconnue, suggérant des ambitions traîtresses bien au-delà des simples querelles tribales.",al={"notes de la cime de noir-nuage","notes grimtotem","mystère de la cime de noir-nuage"}},["7b560411"]={q="Que préparent les Grimtotem ?",a="Les Grimtotem rejettent fondamentalement le leadership de Cairne Sabot-de-Sang et les changements culturels apportés par l'adhésion à la Horde. Ils cherchent à déposer Cairne, à saper l'autorité de la Horde et même à s'associer avec des puissances sinistres et à invoquer des entités de vengeance pour affirmer leur domination.",al={"plan des grimtotem","que veulent les grimtotem","conspiration grimtotem"}},["853c4dd1"]={q="Qu'est-ce que le Haut-perchoir et pourquoi voulons-nous des œufs de wyverne ?",a="Le Haut-perchoir est le lieu de nidification ancestral des wyvernes sauvages dans les Mille pointes. Les Tauren du Poste de Librevent grimpent jusqu'à ces hautes cimes pour récolter des œufs de wyverne fertiles afin qu'ils puissent être élevés et entraînés avec soin comme montures volantes loyales pour la Horde.",al={"wyvernes du haut-perchoir","pourquoi collecter des œufs de wyverne","œufs du haut-perchoir"}},dc3189d8={q="Comment ai-je fini aux Mille pointes ?",a="La plupart des voyageurs arrivent par le nord en traversant Les Tarides vers le sud, en passant devant le Camp Taurajo, pour finalement atteindre le bord de la falaise abrupte où l'immense La Grande élévation conçue par les Tauren vous descend directement jusqu'au fond du canyon. Alternativement, les aventuriers traversant les forêts denses de Féralas à pied entrent dans la gorge ouest, tandis que les explorateurs audacieux bravant les périls du Marécage d’Âprefange ou naviguant vers Theramore se faufilent par les failles contestées. Une longue marche terrestre vers le nord depuis les déserts de Tanaris vous mène également directement dans l'étendue de sel tentaculaire des Salines.",al={"comment suis-je arrivé ici","comment atteindre les mille pointes","se rendre aux mille pointes"}},["16801326"]={q="Que suis-je censé faire aux Mille pointes ?",a="Votre présence ici dépend de vos allégeances et de vos ambitions. Les champions de la Horde sont chargés d'aider le Poste de Librevent : repousser les bandes de centaures Galak qui errent sur le fond du canyon, surveiller les nids de harpies, collecter des œufs de wyverne du Haut-perchoir et combattre la tribu traîtresse des Grimtotem retranchée au sommet de la Cime de Noir-nuage. Pour les voyageurs non affiliés et ceux de l'Alliance, l'étendue spectaculaire sert de carrefour terrestre dangereux entre le centre et le sud de Kalimdor, menant vers Les Salines où les casse-cou gobelins et gnomes paient cher pour des pièces, du carburant et de l'aide concernant leur rivalité perpétuelle de voitures-fusées.",al={"pourquoi suis-je ici","quel est mon but ici","que faire aux mille pointes"}},d1fb42e2={q="Qu'est-ce que Mille pointes ?",a="Mille pointes est un vaste canyon aride qui divise le centre et le sud de Kalimdor. Le fond du canyon est dense, parsemé de pics de grès imposants qui s'étirent vers le ciel comme une forêt pétrifiée, reliés au-dessus par des ponts délicats de corde et de bois. À l'est, le canyon laisse place aux Salines, une plaine de sel d'un blanc aveuglant.",al={"qu'est-ce que cet endroit","à propos de mille pointes","parlez-moi de mille pointes"}}},fp="16,179,17.529.0,18.553.0,18.535.0,38.222.0,59.251.0,43.279.0,27.248.0,45.235.0,30.284.0"}
P.entries["zone:thunderbluff"] = {n="Pitons-du-Tonnerre",s="Les Pitons-du-Tonnerre sont la magnifique capitale des taurens, perchée au sommet de mesas de roche rouge balayées par les vents qui s'élèvent au-dessus des prairies de Mulgore. Fondée par le grand chef Cairne Sabot-de-Sang après avoir unifié les tribus nomades avec l'aide de la nouvelle Horde, elle constitue le cœur culturel, spirituel et marchand de son peuple. Reliée par des ponts de corde oscillants et des monte-charges en bois, la cité offre une protection contre les maraudeurs centaures ainsi qu'un sanctuaire paisible pour les voyageurs à travers Kalimdor.",h="Les Pitons-du-Tonnerre sont la magnifique capitale des taurens, perchée au sommet de mesas de roche rouge...",kw={"cairne sabot-de-sang","cime des anciens","ascenseurs","hamuul totem-runique","cime des chasseurs","magatha totem-sinistre","mulgore","les bassins de la vision","cime des esprits","pitons-du-tonnerre"},ang={["class:Druid"]="La Cime des Anciens sert de sanctuaire suprême de la magie de la nature pour la Horde, dirigée par l'archidruide Hamuul Totem-runique, le premier druide tauren formé depuis des milliers d'années.",["class:Shaman"]="La Cime des Esprits et les Bassins de la Vision souterrains offrent un lien serein où les esprits élémentaires et les esprits des ancêtres taurens sont vénérés et écoutés.",["faction:Horde"]="Bien plus paisibles et spirituels que les rudes remparts d'Orgrimmar, les Pitons-du-Tonnerre servent de point d'ancrage pastoral à l'influence méridionale de la nouvelle Horde en Kalimdor.",["race:Tauren"]="Les Pitons-du-Tonnerre représentent l'unité chèrement acquise et la renaissance de votre peuple après des générations d'errance nomade et de harcèlement par les centaures sous la conduite du grand chef Cairne Sabot-de-Sang."},sec={{t="Un havre permanent",b="Pendant d'innombrables générations, les taurens ont mené une existence nomade à travers Kalimdor, pris au piège d'une lutte brutale pour leur survie contre de féroces tribus de centaures. Cette ère désespérée prit fin lors de la Troisième guerre, lorsque Cairne Sabot-de-Sang s'allia au chef de guerre Thrall. Ensemble, les orcs et les taurens brisèrent les assauts des centaures et sécurisèrent les pâturages verdoyants de Mulgore. Afin de protéger leur avenir, Cairne guida les tribus alliées vers la sécurité de ces bastions de pierre naturels, fondant les Pitons-du-Tonnerre comme le premier foyer unifié et permanent que les taurens aient possédé depuis des siècles."},{t="Une cité dans les nuages",b="S'étendant sur plusieurs hautes mesas reliées par des ponts de corde suspendus, les Pitons-du-Tonnerre mêlent harmonieusement architecture naturelle et sens pratique des taurens. Les pitons centraux accueillent les marchés animés, la banque, l'auberge et le perchoir dominant des coursiers du vent, tandis que trois mesas spécialisées se déploient au-dessus du vide. La Cime des chasseurs sert aux éclaireurs et pisteurs de la ville ; la Cime des Anciens accueille les gardiens du savoir et le Cercle cénarien sous la direction de l'archidruide Hamuul Totem-runique ; et la Cime des Esprits est dédiée à la communion spirituelle, abritant chamans, prêtres et les mystérieuses cavernes souterraines connues sous le nom des Bassins de la Vision."},{t="Une unité fragile",b="Bien que Cairne Sabot-de-Sang inspire un immense respect à presque chaque tribu, gouverner un peuple fier et récemment sédentarisé n'est pas sans heurts. En particulier, la tribu des Totems-sinistres — dirigée par la matriarche avisée et acerbe Magatha Totem-sinistre — maintient une présence menaçante sur la Cime des Anciens. Magatha conteste ouvertement les méthodes conciliantes de Cairne et son allégeance aux races étrangères de la Horde. Même si la paix perdure sous le regard vigilant du chef, des divergences idéologiques grondent autour des feux de conseil dominant les plaines."}},faq={{q="Qui dirige les Pitons-du-Tonnerre ?",a="Le grand chef Cairne Sabot-de-Sang dirige les Pitons-du-Tonnerre et mène les tribus taurens unifiées. Vénéré pour sa sagesse, sa patience et sa force colossale, Cairne a fondé la cité après s'être allié à la Horde de Thrall et avoir chassé les centaures de Mulgore.",al={"dirigeant des pitons-du-tonnerre","qui commande","chef des pitons-du-tonnerre","cairne"}},{q="Comment monte-t-on aux Pitons-du-Tonnerre ?",a="Les visiteurs arrivant à pied ou à dos de kodo doivent emprunter les imposants ascenseurs à plateformes de bois situés sur les flancs sud-ouest et nord-est de la mesa centrale. La ville dispose également d'un perchoir de coursiers du vent proposant des trajets aériens à travers Kalimdor.",al={"ascenseur des pitons-du-tonnerre","comment entrer","entrée des pitons-du-tonnerre","monter"}},{q="Pourquoi les taurens ont-ils bâti leur cité sur de hautes mesas plutôt qu'au sol ?",a="Des siècles d'existence nomade ont été marqués par les attaques éclair incessantes de clans centaures agressifs. Les falaises abruptes des pitons de Mulgore offrent une défense naturelle, protégeant les habitations, les forges et les anciens sacrés des taurens contre les embuscades terrestres et leur permettant de s'établir définitivement en paix.",al={"pourquoi des mesas","pourquoi sur des falaises","falaises des pitons-du-tonnerre","hauteurs taurens"}},{q="Quelles sont les différentes cimes de la ville ?",a="La ville s'étend sur une mesa centrale (divisée en niveaux inférieur, intermédiaire et supérieur) entourée de trois mesas extérieures. La Cime des chasseurs est dédiée aux guerriers, aux chasseurs et aux loges de traque. La Cime des Anciens abrite les druides, les sages et la faction des Totems-sinistres. La Cime des Esprits accueille des sanctuaires dédiés à la Terre-Mère, des maîtres de chamans, de prêtres et de mages, ainsi que les cavernes des Bassins de la Vision.",al={"quartiers des pitons-du-tonnerre","quelles sont les cimes","secteurs des pitons-du-tonnerre"}},{q="Que sont les Bassins de la Vision ?",a="Les Bassins de la Vision sont des cavernes souterraines sacrées nichées sous la Cime des Esprits. Les clairvoyants, les marcheurs des esprits et les praticiens des arcanes taurens se réunissent près de ces eaux calmes et enveloppées de brume pour communier avec les éléments et interpréter les présages relatifs à l'avenir de leur peuple.",al={"les bassins de la vision","grotte de la cime des esprits","grotte des pitons-du-tonnerre"}},{q="Qui est Magatha Totem-sinistre ?",a="Magatha Totem-sinistre est la matriarche et la doyenne du redoutable clan des Totems-sinistres. Bien qu'elle réside sur la Cime des Anciens et participe en apparence au conseil de Cairne, elle est farouchement traditionaliste, se méfie des étrangers et remet discrètement en cause l'attitude complaisante de la tribu Sabot-de-Sang à l'égard de la Horde.",al={"magatha","matriarche","qui dirige les totems-sinistres"}}},fx={["7db56847"]={q="Comment ai-je atterri à Pitons-du-Tonnerre ?",a="Si vous êtes un jeune tauren, votre voyage a commencé plus au sud, sur les prairies abritées de la Mesa de Nuage rouge, et vous a fait passer par le village de Sabot-de-Sang avant de vous mener ici. La route mène au pied de ces imposantes mesas, où de grands ascenseurs à cordes en bois hissent les voyageurs à des dizaines de mètres dans les airs. Sinon, les visiteurs venant de terres lointaines à travers Kalimdor arrivent souvent en wyverne au perchoir des maîtres des wyvernes, au sommet des pitons.",al={"comment suis-je arrivé ici","comment aller à pitons-du-tonnerre","comment atteindre pitons-du-tonnerre"}},["347b5cac"]={q="Que suis-je censé faire à Pitons-du-Tonnerre ?",a="Pitons-du-Tonnerre est le cœur spirituel et culturel des tribus tauren unies. Vous pouvez y obtenir une formation avancée auprès des chamans, druides, chasseurs et guerriers aînés rassemblés sur les différents promontoires. Le grand chef Cairne Sabot-de-Sang et les anciens des tribus comptent également sur des champions compétents pour protéger Mulgore des menaces persistantes, notamment les centaures pillards, l'incursion de KapitalRisk, les harpies et les hargneuses quilboars, avant de vous envoyer vers l'est pour affronter les épreuves plus vastes de la Horde.",al={"que faire à pitons-du-tonnerre","pourquoi suis-je ici","quel est mon but ici"}},["6fa5b073"]={q="Qu'est-ce que Pitons-du-Tonnerre ?",a="Pitons-du-Tonnerre est la capitale des Tauren, perchée haut sur les plateaux balayés par les vents du nord de Mulgore. Établie par le grand chef Cairne Sabot-de-Sang après avoir repoussé les centaures avec la Horde de Thrall, elle offre un sanctuaire sûr et permanent à un peuple qui a vécu comme nomade errant pendant des générations.",al={"qu'est-ce que cette ville","parlez-moi de pitons-du-tonnerre","ville de pitons-du-tonnerre"}},fc90632b={q="Cairne Sabot-de-Sang est-il un roi ?",a="Non. Cairne Sabot-de-Sang détient le titre de grand chef des tribus tauren unies. La société tauren ne couronne pas de monarques ; Cairne gouverne grâce au profond respect, à la sagesse et à la force dont il a fait preuve au fil des décennies, plutôt que par droit divin royal héréditaire.",al={"cairne sabot-de-sang roi","cairne est-il un roi","roi tauren"}},["047fa056"]={q="Cairne Sabot-de-Sang répond-il à Thrall ?",a="Thrall est le chef de guerre de la Horde, mais son lien avec Cairne est fondé sur l'honneur mutuel et l'alliance plutôt que sur une sujétion stricte. Cairne a engagé son peuple dans la Horde par gratitude et vision partagée, se tenant comme l'un des conseillers les plus fiables et les pairs de Thrall.",al={"cairne répond-il à thrall","thrall est-il le patron de cairne","cairne et thrall"}},["85c1a10f"]={q="Pourquoi les Tauren ont-ils rejoint la Horde ?",a="Les maraudeurs centaures avaient poussé les Tauren nomades au bord de l'extinction à travers Les Tarides. Lorsque le chef de guerre Thrall et les orcs ont débarqué en Kalimdor, ils ont aidé le peuple de Cairne à briser le siège des centaures et à sécuriser Mulgore, forgeant un lien indéfectible entre leurs cultures.",al={"pourquoi rejoindre la horde","alliance tauren horde","comment les taurens ont-ils rejoint"}},["3180b5ca"]={q="Qu'en est-il de la tribu Grimtotem ?",a="Les Grimtotem sont un clan féroce et agressif dirigé par la vieille matriarche The Elder Crone Magatha. Contrairement aux pacifiques Sabot-de-Sang, ils nourrissent une profonde méfiance envers les étrangers et remettent ouvertement en question le leadership pacifique de Cairne, estimant que les Tauren devraient conquérir Kalimdor et chasser les autres races.",al={"tribu grimtotem","qui sont les grimtotem","taurens grimtotem"}},ca8246e8={q="Les Grimtotem sont-ils les ennemis de Cairne ?",a="Ouvertement, ils restent partie intégrante de la nation tauren unie, et Magatha réside même sur la Cime des Anciens. Sous la surface, cependant, une rivalité politique amère couve, car Magatha complote constamment et croit qu'elle seule possède la vision légitime pour diriger les Tauren.",al={"les grimtotem sont-ils mauvais","grimtotem contre cairne","magatha contre cairne"}},["54829977"]={q="Pitons-du-Tonnerre est-elle dangereuse ?",a="Dans la ville, les braves gardes maintiennent l'ordre et la sécurité contre les bêtes et les hurans qui rôdent dans les plaines en contrebas. Le plus gros risque immédiat pour les visiteurs est la chute abrupte : un faux pas imprudent hors des bords du plateau ou des ponts en bois s'avérera fatal.",al={"pitons-du-tonnerre est-elle sûre","menaces à pitons-du-tonnerre","danger ici"}}},fp="13,326,17.466.0,20.453.0,12.391.1,24.277.0,35.194.0,61.212.0,41.395.0,29.239.0,25.233.0"}
P.entries["zone:tirisfal"] = {n="Clairières de Tirisfal",s="Les Clairières de Tirisfal sont le territoire hanté du nord de Lordaeron, servant désormais de cœur au domaine de Dame Sylvanas Coursevent et des Réprouvés. Sous des cieux corrompus et des branches pourrissantes se trouvent des manoirs déchus, des cryptes dormantes et la vaste capitale souterraine de Fossoyeuse. Entourées par le Fléau sans esprit et les zélés membres de la Croisade écarlate, c'est un royaume périlleux où les morts-vivants dotés de libre arbitre assurent leur survie.",h="Les Clairières de Tirisfal sont le territoire hanté du nord de Lordaeron, servant désormais de cœur au...",kw={"agamand","balnir","brill","le glas","réprouvés","clairières","lordaeron","croisade écarlate","sylvanas","tirisfal","fossoyeuse"},ang={["class:Priest"]="Des lieux saints historiques comme le Repos de Faol — la tombe de l'archevêque Alonsus Faol, fondateur de la Silver Hand — se trouvent ici, déformés par la mort et disputés entre les zélotes et les prêtres de l'Ombre.",["faction:Alliance"]="Pour les nations survivantes de l'Alliance, Tirisfal est un monument tragique à la chute de Lordaeron, rempli des tombes profanées d'anciens frères et sœurs dans la foi.",["faction:Horde"]="Tirisfal est le bastion vital de la Horde dans le nord des Royaumes de l'est, ancrant les liens diplomatiques avec les Réprouvés tout en repoussant les extrémistes humains et le Fléau.",["race:Undead"]="C'est votre terre ancestrale deux fois plus : le royaume que vous avez construit de votre vivant, et le sanctuaire précaire que vous devez défendre dans votre non-mort sous les ordres de Dame Sylvanas."},sec={{t="Une terre au crépuscule",b="Autrefois berceau fertile de l'humanité, les Clairières de Tirisfal se sont flétries sous la malédiction de la peste du roi Liche. Le soleil pénètre rarement l'obscurité trouble, projetant une pâleur maladive éternelle sur les bois mourants, les champs de citrouilles négligés et les froides collines côtières. Bien que des vestiges de vieilles fermes comme les Moulins d'Agamand et la Ferme des Balnir subsistent, leurs anciens propriétaires ont été pour la plupart balayés dans des fosses communes ou revenus sous forme de morts agités. Malgré la dévastation, une sombre résilience imprègne la campagne, ancrée par des villes comme Brill et le sanctuaire isolé du Glas, où les Réprouvés récemment éveillés apprennent à endurer leur seconde vie."},{t="Une guerre sur deux fronts",b="Bien que Dame Sylvanas revendique la domination sur la région depuis les souterraines Ruines de Lordaeron, les Réprouvés restent aux prises sur tous les fronts. Des esclaves résiduels du Fléau infestent encore les creux, les champs et les cryptes délabrées, entièrement soumis au trône glacé de Northrend. À l'est, la fanatique Croisade écarlate a fait du nord de Tirisfal son principal bastion, opérant depuis le Monastère écarlate. Dévoués avec zèle à l'extermination de chaque créature mort-vivante, vivante ou non, leurs avant-postes et patrouilles mènent une guerre de guérilla constante contre les éclaireurs Réprouvés et les voyageurs civils."},{t="Échos du passé ancien",b="Bien avant que les royaumes humains ne couronnent leurs premiers monarques, les Clairières portaient un héritage ancien. Les exilés hauts-elfes ont brièvement tenté de s'installer dans ces bois avant que des énergies obscures profondément sous la terre ne commencent à les rendre fous, provoquant leur migration vers le nord. Au cours des siècles suivants, la cabale mortelle secrète connue sous le nom de Conseil de Tirisfal a choisi ces bosquets ombragés pour donner du pouvoir aux Gardiens solitaires, protégeant Azeroth contre les intrusions démoniaques."}},faq={{q="Pourquoi le ciel est-il vert et la terre en décomposition ?",a="Pendant la Troisième guerre, le Prince Arthas et le Fléau ont déclenché la Peste de non-mort à travers le royaume de Lordaeron. Le fléau magique a empoisonné non seulement la population, mais aussi le sol, les arbres et l'eau elle-même, laissant les clairières dans un état éternel de décomposition étrange et maladive.",al={"pourquoi tirisfal est corrompu","ce qui est arrivé à tirisfal","pourquoi tirisfal se meurt"}},{q="Quelle est la différence entre les Réprouvés et le Fléau ici ?",a="Les Réprouvés sont des morts-vivants qui se sont libérés de la domination télépathique du roi Liche après la bataille du Mont Hyjal, choisissant de suivre Dame Sylvanas Coursevent avec leur propre libre arbitre. Le Fléau qui erre dans les fermes et les ruines reste constitué d'esclaves sans esprit liés aux ordres du roi Liche.",al={"réprouvés contre fléau","pourquoi les zombies attaquent les morts-vivants","tous les morts-vivants sont-ils maléfiques"}},{q="Qui sont les soldats en armure rouge qui attaquent les voyageurs ?",a="Ils appartiennent à la Croisade écarlate, un ordre dissident intransigeant composé d'anciens paladins de la Silver Hand et de survivants. Convaincus que tous les morts-vivants sont des abominations irrécupérables qui doivent être purifiées par l'épée et le feu, ils exécutent à la fois les esclaves sans esprit et les Réprouvés dotés de libre arbitre avec une haine fanatique.",al={"croisade écarlate","humains rouges","humains du monastère"}},{q="D'où vient le nom Tirisfal ?",a="Le nom est plus ancien que n'importe quel royaume humain, et sa véritable origine a été perdue dans l'histoire. Il est mieux connu par le Conseil de Tirisfal, l'ordre secret de mages qui donnait le pouvoir aux Gardiens de protéger Azeroth contre les démons.",al={"signification de tirisfal","origine de tirisfal"}},{q="Où les Réprouvés nouvellement éveillés commencent-ils leur voyage ?",a="Les Réprouvés nouvellement éveillés émergent des cryptes du Tombeau des ombres à l'intérieur du Glas, une ville isolée nichée dans le sud-ouest de Tirisfal. Là, les administrateurs et les exécuteurs évaluent si les morts revenus à la vie possèdent la santé mentale et la loyauté requises pour servir la Dame noire.",al={"zone de départ des morts-vivants","où se trouve le glas","zone de départ des réprouvés"}},{q="Comment les voyageurs quittent-ils Tirisfal pour d'autres continents ?",a="Une grande tour de zeppelin exploitée par des gobelins se trouve sur le flanc de la colline au sud de Brill, juste à l'extérieur des Ruines de Lordaeron. Ces dirigeables assurent un transit direct et régulier à travers les mers vers Orgrimmar en Kalimdor et le Campement Grom'gol dans la Vallée de Strangleronce.",al={"zeppelins de tirisfal","comment aller à orgrimmar","comment aller à strangleronce"}}},fx={["6c272224"]={q="Que sont les Clairières de Tirisfal ?",a="Les Clairières de Tirisfal sont le cœur du territoire des Réprouvés, sur la côte nord de Lordaeron. Autrefois noyau fertile et paisible d'un fier royaume humain, elles furent ravagées durant la Troisième guerre par la peste du Fléau. Aujourd'hui, des bois corrompus et une pénombre verdâtre perpétuelle recouvrent les collines, encadrées par les ruines de la capitale de Lordaeron et entourées de fanatiques hostiles, de bêtes féroces et de morts-vivants persistants.",al={"qu'est-ce que tirisfal","parle-moi des clairières de tirisfal","lore de la zone de tirisfal"}},["342b65f9"]={q="Ces terres ont-elles toujours appartenu aux morts-vivants ?",a="Non. Pendant des millénaires, Tirisfal fut le berceau de la civilisation humaine et le cœur prospère du royaume de Lordaeron. Des fermes paisibles, des moulins prospères et de petits hameaux florissaient sous le règne du roi Terenas Menethil. Cette époque prit fin violemment pendant la Troisième guerre, lorsque le prince Arthas et le Culte des damnés balayèrent la région avec la peste, transformant les habitants en esclaves morts-vivants avant que Sylvanas ne brise leurs chaînes.",al={"tirisfal a-t-il toujours été aux morts-vivants","qui vivait ici avant","tirisfal avant la peste"}},["4790468d"]={q="Qui vit ou dirige les Clairières de Tirisfal ?",a="Les Réprouvés revendiquent les Clairières de Tirisfal sous le règne de la reine Sylvanas Coursevent, depuis Fossoyeuse. Cependant, leur emprise est constamment contestée. La Croisade écarlate, fanatique, contrôle des fortifications et son grand monastère au nord-est, tandis que des membres du Fléau sans esprit rôdent dans les fermes abandonnées. À la frontière orientale, à la Barricade, les Réprouvés coordonnent leurs efforts avec l'Aube d'argent pour contenir les horreurs des Maleterres.",al={"qui dirige tirisfal","qui contrôle les clairières de tirisfal","factions de tirisfal"}},["97ffdb73"]={q="Les Clairières de Tirisfal sont-elles dangereuses ?",a="Extrêmement. Au-delà des murs des avant-postes Réprouvés, vous ferez face à des restes du Fléau sans esprit, des gnolls sauvages, des arachnides géants et une faune vicieuse contaminée par la peste. Pire encore sont les fanatiques de la Croisade écarlate, qui exécutent tout mort-vivant à vue. Tout à l'est se trouvent les Maleterres de l’Ouest, où des monstres bien plus mortels que tout ce que vous trouverez à Tirisfal mettront en pièces les imprudents.",al={"à quel point tirisfal est-il dangereux","menaces de tirisfal","est-ce sûr ici"}},["30e6283a"]={q="Qui commande à Brill ?",a="Le magistrat Sevren supervise l'administration civile de Brill, gérant la reconstruction de la ville et sa survie quotidienne. L'autorité militaire et les opérations tactiques, en particulier la campagne contre la Croisade écarlate toute proche, sont commandées par l'exécuteur Zygand.",al={"chef de brill","qui dirige brill","responsable de brill"}},["3fc3649e"]={q="À qui le magistrat Sevren rend-il des comptes ?",a="Sevren sert la Dame noire, la reine Sylvanas Coursevent. En tant que magistrat de Brill, il représente l'autorité civile de la couronne Réprouvée dans la région, opérant en concertation directe avec les exécuteurs royaux et la Société royale des apothicaires basée à Fossoyeuse.",al={"patron de sevren","à qui rend compte sevren","chaîne de commandement de brill"}},["381a9b46"]={q="Où se trouve la reine banshee ?",a="Dame Sylvanas Coursevent réside dans le Royal Quarter de Fossoyeuse, profondément sous les ruines de la cité capitale, juste au sud de Brill. Depuis sa salle du trône, elle dirige les Réprouvés dans leur guerre contre le Fléau et la Croisade écarlate.",al={"où est sylvanas","trouver sylvanas","emplacement de la reine banshee"}},e7993821={q="Qu'est-ce que Brill ?",a="Brill est la principale ville Réprouvée du centre des Clairières de Tirisfal, située au carrefour au nord de la cité capitale. Autrefois un établissement vivant sous le domaine des Barov, il fut reconstruit après la Troisième guerre pour offrir aux morts-vivants fraîchement éveillés un lieu de repos, de commerce et d'organisation avant de s'aventurer plus loin dans le monde.",al={"à propos de brill","quel genre de ville est brill","lore de brill"}},["529e09c8"]={q="Des personnes vivantes vivaient-elles ici auparavant ?",a="Oui. Brill était autrefois une communauté humaine paisible au sein du royaume de Lordaeron. Ce fut le point zéro des premières expériences de peste orchestrées par Kel'Thuzad, entraînant des pertes massives et d'immenses fosses communes avant même que le prince Arthas n'arrive pour enquêter.",al={"des humains vivaient-ils à brill","histoire de brill","qui habitait à brill"}},["7b7ff5e2"]={q="Qu'est-ce que la Taverne des Pendus ?",a="La Taverne des Pendus est la salle de réunion et l'auberge principale de Brill. Elle offre un abri, des libations infectes et un répit loin des sinistres clairières extérieures. Dans ses recoins les plus sombres, les Réprouvés gardent des ennemis capturés, comme des fanatiques écarlates, pour des expériences sinistres de concoctions d'apothicaire.",al={"taverne des pendus","auberge de brill","qu'est-ce que la taverne des pendus"}},["0d8014ee"]={q="Quelle est l'histoire des Moulins d'Agamand ?",a="Les Moulins d'Agamand étaient autrefois le domaine agricole le plus riche et le plus productif des Clairières de Tirisfal, célèbre pour sa farine et ses céréales. Lorsque la peste a frappé, tout le complexe a été envahi et le massacre s'en est suivi. Aujourd'hui, ce n'est plus qu'une ruine en décomposition parsemée de moulins à vent, étouffée par les morts-vivants du Fléau qui y persistent.",al={"lore des moulins d'agamand","qu'est-il arrivé aux moulins d'agamand","moulins d'agamand"}},["001d4abe"]={q="Qui étaient les Agamand ?",a="Les Agamand étaient une noble et riche dynastie humaine qui développa les vastes moulins et possédait des propriétés dans tout Tirisfal, y compris à Brill. Durant la Troisième guerre, leur fortune ne put les sauver ; la famille tomba face au Fléau et leurs patriarches réanimés continuent de hanter le domaine.",al={"famille agamand","qui vivait aux moulins d'agamand","les agamand"}},eeb96a2c={q="Pourquoi sont-ils hostiles envers nous alors qu'ils sont morts-vivants aussi ?",a="Les morts-vivants qui hantent les Moulins d'Agamand n'ont jamais recouvré leur libre arbitre. Contrairement aux Réprouvés, qui se sont libérés de l'emprise mentale du roi-liche, ces créatures restent asservies en tant qu'esclaves du Fléau sans esprit, contraintes de détruire tout vivant ou mort-vivant rebelle qui pénètre sur leur domaine.",al={"pourquoi les agamand nous attaquent-ils","pourquoi les morts-vivants agamand sont-ils hostiles","pourquoi combattre d'autres morts-vivants"}},a357af07={q="Où cela mène-t-il après Tirisfal ?",a="La plupart des Réprouvés voyagent vers le sud à travers le col de montagne menant à la Forêt des Pins-Argentés pour aider à sécuriser la frontière sud et combattre les agents de Dalaran et les gnolls Peau-pourrie. Sinon, des zeppelins au sud de Brill permettent de se rendre à Orgrimmar ou au Campement Grom'gol, de l'autre côté de la mer.",al={"où aller après tirisfal","zone après tirisfal","après les clairières de tirisfal"}},["50336b90"]={q="Qu'est-ce que Fossoyeuse ?",a="Fossoyeuse est la tentaculaire capitale souterraine des Réprouvés, construite au sein des anciens égouts, cryptes et catacombes sous les Ruines de Lordaeron dévastées. Elle sert de forteresse à la reine Sylvanas et de centre de commandement pour les opérations des Réprouvés à travers Azeroth.",al={"qu'est-ce que fossoyeuse","lore de fossoyeuse","à propos de fossoyeuse"}},ddddba9f={q="La frontière de la Forêt des Pins-Argentés est-elle la prochaine étape ?",a="Oui. En suivant la route vers le sud depuis Tirisfal, vous arrivez directement dans la Forêt des Pins-Argentés. C'est la suite logique de votre service aux Réprouvés, où vous affronterez la menace grandissante le long des frontières sud de Lordaeron.",al={"forêt des pins-argentés ensuite","dois-je aller en forêt des pins-argentés après","frontière de la forêt des pins-argentés"}},["789ead4d"]={q="Comment ai-je atterri dans les Clairières de Tirisfal ?",a="Si vous êtes un Réprouvé nouvellement éveillé, vous êtes mort lors de la chute de Lordaeron face au Fléau et avez été enterré ici. L'emprise du roi-liche ayant été brisée, votre libre arbitre est revenu et vous vous êtes extrait de votre tombe dans la vallée isolée du Glas. Si vous appartenez aux autres nations de la Horde, vous êtes probablement arrivé par les tours de zeppelin situées entre Brill et Fossoyeuse, qui relient ce royaume dévasté directement à Orgrimmar et au Campement Grom'gol.",al={"comment suis-je arrivé ici","comment suis-je arrivé aux clairières de tirisfal"}},["89135166"]={q="Que suis-je censé faire dans les Clairières de Tirisfal ?",a="Votre objectif est d'aider les Réprouvés à sécuriser leur emprise fragile sur les terres dévastées de Lordaeron. En sortant des cryptes du Glas vers la ville de Brill, vous devez purger le Fléau sans esprit qui hante les fermes abandonnées, éliminer les fanatiques de la Croisade écarlate qui empiètent depuis le nord et décimer les bêtes pestiférées qui errent dans les bois putrides. Ce faisant, vous prouverez votre valeur à Dame Sylvanas et vous préparerez à servir son royaume grandissant sous les ruines de la cité capitale.",al={"que dois-je faire ici","pourquoi suis-je à tirisfal","quel est mon objectif ici"}}},fp="15,338,18.442.0,19.456.0,26.372.0,42.269.0,65.287.0,53.289.0,39.222.0,53.244.0,53.247.0"}
P.entries["zone:undercity"] = {n="Fossoyeuse",s="Profondément enfouie sous les ruines brisées de la capitale de Lordaeron s'étend Fossoyeuse, la sombre place forte des Réprouvés. Taillée à l'origine dans d'anciennes cryptes et geôles royales par le Fléau, elle fut conquise par Dame Sylvanas Coursevent et transformée en un impénétrable sanctuaire souterrain. Elle sert aujourd'hui de siège du pouvoir réprouvé et de bastion vital de la Horde dans le nord des Royaumes de l'est.",h="Profondément enfouie sous les ruines brisées de la capitale de Lordaeron s'étend Fossoyeuse, la sombre place...",kw={"l'apothicarium","arthas","réprouvés","lordaeron","fléau","sylvanas","terenas","tirisfal","fossoyeuse","varimathras"},ang={["faction:Horde"]="En tant que principal point d'ancrage de la Horde dans les Royaumes de l'est, Fossoyeuse garantit des liaisons par zepelin directes vers Durotar et le Campement Grom'gol.",["race:Human"]="Sous la terre de votre royaume ancestral déchu repose une sinistre perversion des cryptes royales de Lordaeron, occupée par les cadavres ambulants de vos anciens frères.",["race:Orc"]="Au plus profond de ces mêmes geôles, le légendaire chef de guerre Orgrim Marteau-du-Destin fut jadis emprisonné par l'Alliance de Lordaeron avant son évasion historique.",["race:Undead"]="Fossoyeuse est votre sanctuaire souverain et votre patrie, taillée de vos propres mains après vous être affranchi de l'emprise de fer du Roi-Liche."},sec={{t="Des cryptes royales au bastion du Fléau",b="Bien avant que la peste ne ravage Lordaeron, les catacombes, les geôles et les égouts situés sous le palais étaient collectivement connus sous le nom de Fossoyeuse. Ils abritaient les tombes de la noblesse, les prisons les plus profondes du royaume — où l'ancien chef de guerre Orgrim Marteau-du-Destin fut jadis enfermé avant son évasion — et les habitants les plus démunis du royaume. Lorsqu'Arthas Menethil assassina le roi Terenas et dévasta la capitale en l'an 20 ADP, le prince ordonna à ses serviteurs morts-vivants d'excaver et d'agrandir les galeries souterraines pour en faire un siège fortifié sous le joug du Fléau."},{t="L'avènement des Réprouvés",b="Le Fléau ne vit jamais l'achèvement de sa sombre capitale. Lorsque les pouvoirs du Roi-Liche déclinèrent après la bataille du Mont Hyjal, Dame Sylvanas Coursevent s'affranchit de la conscience collective, entraînant des milliers de morts-vivants avec elle. Elle attira Arthas dans une embuscade et le contraignit à fuir vers le Norfendre. Après une féroce guerre civile à trois camps contre les vestiges du Fléau, les seigneurs de l'effroi et la résistance humaine, Sylvanas revendiqua les catacombes à demi achevées. Nommant son peuple les Réprouvés, elle supervisa de longues années de labeur pour terminer la vaste cité souterraine."},{t="Architecture des Maudits",b="Fossoyeuse est organisée en anneaux concentriques divisés en quartiers fonctionnels. En son cœur se trouve le Quartier des Marchands, relié par d'immenses ascenseurs aux ruines du palais à la surface. Autour s'étendent le Quartier de la Guerre, le Quartier des Voleurs, le Quartier de la Magie et le toxique Apothicarium, où la Société royale des apothicaires concocte de virulentes pestes dans des canaux emplis de vase verte. Plus profondément encore se dresse le Quartier royal, où la Reine banshee tient sa cour aux côtés de son commandant seigneur de l'effroi, Varimathras, sous la garde de légions d'abominations imposantes."}},faq={{q="Qu'était Fossoyeuse avant que les morts-vivants ne s'en emparent ?",a="Sous le palais de Lordaeron se trouvaient les antiques cryptes de la royauté humaine, ainsi que le complexe carcéral et le vaste réseau d'égouts de la ville. Ils abritaient des prisonniers de guerre, dont Orgrim Marteau-du-Destin, ainsi que des citoyens indigents vivant dans les ombres souterraines. Après avoir mis la capitale à sac, le prince Arthas entreprit de transformer ces catacombes en forteresse du Fléau avant que Sylvanas ne s'en empare.",al={"origines de fossoyeuse","qu'était fossoyeuse à l'origine","histoire des égouts de lordaeron"}},{q="Pourquoi la ville est-elle bâtie sous terre plutôt qu'à la surface ?",a="La cité en surface de Lordaeron fut entièrement dévastée lors de la Troisième guerre, la rendant difficile à défendre contre la Croisade écarlate, les forces du Fléau et les survivants de l'Alliance. Les tunnels souterrains offraient des fortifications naturelles, des goulets d'étranglement et le secret, permettant aux Réprouvés d'achever les travaux initiaux du Fléau et de prospérer à l'abri des regards.",al={"pourquoi vivre sous terre","pourquoi ne pas reconstruire lordaeron","pourquoi fossoyeuse sous les ruines"}},{q="Qui dirige Fossoyeuse ?",a="La ville est dirigée par Dame Sylvanas Coursevent, la Reine banshee et reine des Réprouvés. Elle gouverne depuis le Quartier royal, protégée par les sentinelles royales réprouvées et son lieutenant asservi, le seigneur de l'effroi Varimathras.",al={"qui dirige fossoyeuse","souverain de fossoyeuse","qui commande fossoyeuse"}},{q="Qu'est-ce que le mémorial du roi Terenas dans les ruines au-dessus ?",a="Au-dessus des ascenseurs principaux de la ville se dresse un mémorial de pierre en hommage au défunt roi Terenas Menethil II. Il ne renferme pas son corps, car sa dépouille a été incinérée et ses cendres dispersées lors de la résurrection de Kel'Thuzad. Des survivants humains de l'Alliance ont courageusement érigé ce monument au milieu des ruines afin que perdure la mémoire du dernier véritable roi de Lordaeron.",al={"tombeau du roi terenas","tombe de la salle du trône de lordaeron","qui a bâti la tombe au-dessus de fossoyeuse"}},{q="D'où viennent les bruits étranges dans la salle du trône de Lordaeron ?",a="Dans la salle du trône en ruine surplombant les ascenseurs de Fossoyeuse subsistent des échos spectraux du passé. Les visiteurs qui se tiennent au centre peuvent percevoir de faibles bruits fantomatiques : les cloches de fête et les pétales de rose du retour d'Arthas, les avertissements du prophète Medivh, ainsi que l'ultime échange entre le roi Terenas et son fils parricide.",al={"bruits de fantômes salle du trône","chuchotements salle du trône","voix dans la salle du trône de lordaeron"}},{q="Pourquoi les Réprouvés autorisent-ils les autres membres de la Horde ici ?",a="Les Réprouvés ont conclu une alliance de circonstance avec la Horde du chef de guerre Thrall pour assurer leur survie, cernés qu'ils sont par les fanatiques écarlates et les légions du Fléau. Bien que les races vivantes de la Horde trouvent les émanations toxiques et les cours d'eau alchimiques étouffants, émissaires et voyageurs y sont acceptés afin d'entretenir des liens diplomatiques et militaires.",al={"pourquoi des orcs à fossoyeuse","la horde à fossoyeuse","pourquoi fossoyeuse est dans la horde"}}},fx={a590d153={q="Qu'est-ce que Fossoyeuse ?",a="Fossoyeuse est la capitale souterraine des Réprouvés, construite directement sous les ruines brisées de la cité capitale dans les Clairières de Tirisfal. Creusée à même les anciennes cryptes royales, les égouts et les catacombes, elle fut agrandie par le prince Arthas pour servir de place forte au Fléau avant que Dame Sylvanas Coursevent et ses morts-vivants renégats ne s'en emparent durant la guerre civile. Aujourd'hui, elle constitue un sanctuaire fortifié pour les morts-vivants dotés de libre arbitre, sillonné de boue toxique et gardé avec vigilance contre tout intrus vivant.",al={"qu'est-ce que fossoyeuse","parlez-moi de fossoyeuse","histoire de fossoyeuse"}},c51b16b2={q="Qu'est-il arrivé à l'ancien roi de Lordaeron ?",a="Le roi Terenas Menethil II fut assassiné dans la salle du trône située juste au-dessus de cette ville par son propre fils, le prince Arthas. Après son retour de Norfendre, corrompu par la lame runique Deuillegivre, Arthas abattit son père et déchaîna le Fléau sur le royaume. Les cendres de Terenas furent plus tard volées par le chevalier de la mort pour ressusciter Kel'Thuzad, ne laissant derrière lui que la pierre commémorative et la traînée de sang séché que vous pouvez encore voir près du trône en ruines.",al={"destin du roi terenas","qu'est-il arrivé au roi terenas","qui a tué le roi terenas"}},c11144c7={q="Qui était Arthas ?",a="Arthas Menethil était le prince héritier de Lordaeron et un célèbre paladin de la Main d'argent. Désespéré de mettre fin à la peste de non-mort qui ravageait sa patrie, sa croisade devint impitoyable et fanatique. En Norfendre, il s'empara de la lame runique maudite Deuillegivre, qui dévora son âme et fit de lui le redoutable champion du roi-liche. Il ne revint chez lui que pour massacrer son père, raser Lordaeron et finalement retourner vers le nord pour fusionner avec le Trône de glace.",al={"qui est arthas","histoire du prince arthas","arthas menethil"}},["7f6bbd49"]={q="Qui est Sylvanas Coursevent ?",a="Dame Sylvanas Coursevent était autrefois la valeureuse générale des forestiers de Lune-d'argent, défendant Quel'Thalas contre le Fléau durant la troisième guerre. Lorsqu'elle tomba, Arthas arracha son âme de son cadavre et la transforma en banshee pour la tourmenter. Quand l'emprise du roi-liche s'affaiblit, elle se libéra, récupéra sa forme physique et rallia d'autres morts-vivants indépendants au sein des Réprouvés. Elle règne désormais en tant que reine banshee depuis le Quartier royal.",al={"qui est la reine banshee","histoire de sylvanas","qui est sylvanas"}},["2a8de90f"]={q="Pourquoi Sylvanas est-elle appelée la Dame noire ?",a="Les Réprouvés honorent Sylvanas sous le nom de Dame noire car elle les a libérés de l'esclavage mental du roi-liche et leur a offert un refuge alors que le reste d'Azeroth cherchait à les exterminer totalement. Vénérée parallèlement à son titre de reine banshee, ce surnom reflète à la fois sa sombre maîtrise de la mort et la dévotion féroce et inébranlable de ses sujets morts-vivants.",al={"pourquoi la dame noire","titre dame noire sylvanas","signification dame noire"}},["84f18f47"]={q="Pourquoi les Réprouvés font-ils partie de la Horde ?",a="Entourés par les Croisés écarlates hostiles, le Fléau implacable et les vestiges vengeurs de l'Alliance, les Réprouvés ne pouvaient survivre seuls à Lordaeron. Dame Sylvanas contacta le chef de guerre Thrall par-delà la mer, forgeant une alliance pragmatique de circonstance. La Horde obtint un pied-à-terre militaire crucial dans les Royaumes de l'est, tandis que les Réprouvés s'assurèrent des renforts essentiels et une légitimité politique dans leur guerre pour la survie.",al={"pourquoi les réprouvés dans la horde","adhésion des morts-vivants à la horde","alliance réprouvés horde"}},["71200045"]={q="Qu'est-ce que le Fléau et est-il encore présent à proximité ?",a="Le Fléau est la vaste armée vorace de morts-vivants sans esprit créée par la Légion ardente et dirigée par le roi-liche depuis la Norfendre. Bien que les Réprouvés aient arraché Fossoyeuse et Tirisfal à leur emprise, le Fléau reste un danger immédiat et mortel. Leurs légions étouffent encore les Maleterres voisines sous le commandement de Kel'Thuzad et infestent les fermes abandonnées et les cryptes à travers les clairières.",al={"le fléau est-il proche","qu'est-ce que le fléau","le fléau à lordaeron"}},["501548ab"]={q="Où se trouve le roi-liche actuellement ?",a="Le roi-liche réside au sommet du Trône de glace, dans les terres glacées et lointaines de Norfendre. Après la guerre civile dans les Maleterres, le prince Arthas s'est enfui de Lordaeron pour protéger son maître affaibli, gravissant le glacier et fusionnant leurs essences en une seule entité terrifiante. Depuis ce bastion arctique, son regard glacial veille toujours sur Azeroth.",al={"où se trouve le roi-liche","emplacement du roi-liche","où est arthas"}},["4cc7f971"]={q="Qui est la Croisade écarlate ?",a="La Croisade écarlate est un ordre fanatique de zélotes humains nés des ruines de la défense de Lordaeron. Aveuglés par leur haine vertueuse des morts-vivants, ils ne font aucune distinction entre le Fléau sans esprit et les Réprouvés dotés de libre arbitre, considérant toute personne souillée par la non-mort — et tout étranger vivant qui les tolère — comme de viles abominations ne méritant que le bûcher. Leur bastion principal dans les Clairières de Tirisfal est le Monastère écarlate.",al={"qui est la croisade écarlate","croisés écarlates","histoire de la croisade écarlate"}},["271820ed"]={q="Fossoyeuse est-elle dangereuse ?",a="Elle est extraordinairement dangereuse, surtout pour les vivants. Des canaux de déchets alchimiques bruts et de boue empoisonnée parcourent les rues de la ville, remplissant les halls caverneux de vapeurs toxiques qui rendent la respiration dangereuse pour les visiteurs de chair et de sang. Sous les quartiers pavés se trouvent des égouts infestés, et plus profondément encore ont lieu des expériences secrètes où l'alchimie noire et des assassinats impitoyables sont planifiés quotidiennement.",al={"fossoyeuse est-elle sûre","danger à fossoyeuse","dangers de fossoyeuse"}},["2539a3c3"]={q="Comment ai-je fini à Fossoyeuse ?",a="En tant que Réprouvé, votre chemin vous a naturellement mené ici après votre réveil de la mort au Glas et avoir prouvé votre loyauté à travers les Clairières de Tirisfal, en suivant les routes après Brill pour descendre sous les ruines brisées de la cité capitale. Si vous venez de Kalimdor ou de terres lointaines, vous êtes probablement arrivé à bord d'un zeppelin de la Horde accostant aux tours juste à l'extérieur de la capitale, ou avez traversé la campagne flétrie. Fossoyeuse constitue la principale place forte de la Horde dans le nord de Lordaeron, offrant refuge et but sous les anciennes catacombes du palais.",al={"comment suis-je arrivé ici","comment rejoindre fossoyeuse","comment se rendre à fossoyeuse"}},b63c4cf2={q="Que suis-je censé faire à Fossoyeuse ?",a="Vous êtes ici pour aider les Réprouvés et rassembler la force de la Horde contre les périls entourant Lordaeron. Dans les quartiers concentriques de la ville, vous pouvez consulter vos maîtres de classe, acquérir des provisions et consulter les sombres chercheurs de la Société royale des apothicaires. Au-delà de votre métier, votre devoir est d'accepter des missions pour Dame Sylvanas Coursevent et ses lieutenants. Les Réprouvés mènent une guerre sur plusieurs fronts : éliminer les vestiges du Fléau sans esprit, repousser la Croisade écarlate fanatique et sécuriser un terrain sûr pour que les morts-vivants dotés de libre arbitre puissent perdurer.",al={"que fais-je ici","que faire à fossoyeuse","pourquoi suis-je ici"}}},fp="9,318,36.556.0,20.416.0,26.421.0,54.450.0,60.340.0,24.362.0,51.333.0,57.328.0,51.322.0"}
P.entries["zone:ungoro"] = {n="Cratère d’Un’Goro",s="Le Cratère d’Un’Goro est une jungle primordiale et encaissée, nichée entre les étendues arides de Tanaris et de Silithus. Dominée par des dinosaures errants, des élémentaires vivants et un volcan central, cette caldeira luxuriante regorge d'anciennes reliques des Titans et de cristaux de puissance dont les origines restent un profond mystère.",h="Le Cratère d’Un’Goro est une jungle primordiale et encaissée, nichée entre les étendues arides de Tanaris et...",kw={"diablosaure","crête de la fournaise","terres des dieux","lakkari","refuge des marshal","cristaux de puissance","torwa le guide","ungoro","cratère d'ungoro"},ang={["class:Druid"]="Les druides du Cercle cénarien étudient l'écosystème isolé d'Un'Goro et récoltent son humus fertile pour faire proliférer le morveblé, cherchant à comprendre la force vitale pure et indomptée qui nourrit la caldeira.",["faction:Alliance"]="Les naturalistes de l'Alliance se rassemblent autour de Williden Marshal et de J.D. Collie au Refuge des Marshal, rivalisant d'efforts pour déchiffrer les pylônes des Titans tout en protégeant les chercheurs de Darnassus qui prélèvent des échantillons de terre.",["faction:Horde"]="Les aventuriers de la Horde arrivent souvent par Tanaris pour mesurer leur valeur face aux diabolosaures légendaires et aider les herboristes de Pitons-du-Tonnerre à cultiver le morveblé à partir de la terre primitive d'Un'Goro.",["profession:Herbalism"]="La riche humidité du bassin subvient aux besoins d'une flore rare, faisant de la région l'un des rares endroits de Kalimdor où la feuille-aveugle, la Feuillerêve et le Sansam doré s'épanouissent ensemble aux côtés de la Fleur de feu sur les pentes du volcan.",["profession:Mining"]="Les parois abruptes du cratère et les escarpements rocheux de la Crête de la Fournaise abondent en gisements de mithril et en riches filons de thorium, faisant de la zone une destination de premier choix pour les minerais de haut niveau."},sec={{t="Les terres des Dieux",b="Pris en étau entre deux étendues désertiques, le Cratère d’Un’Goro défie la géographie du sud de Kalimdor. D'anciens écrits des Elfes de la nuit relatant la guerre des Sables mouvants indiquent que les insectoïdes qiraji furent repoussés aux abords du cratère, incapables de pénétrer ce que leur langue nommait les « terres des Dieux ». Les érudits supposent que la caldeira a servi de terrain d'essai ou d'ancienne demeure aux Titans lors du façonnement de Kalimdor. Des pylônes de pierre s'élèvent le long des crêtes en vrombissant d'énergie, tandis que des formations cristallines bleues, rouges, vertes et jaunes émergent de la terre primitive."},{t="Un écosystème sauvage",b="Un'Goro n'abrite aucune cité, aucune ville ni aucune société humanoïde indigène. La vie s'y épanouit plutôt dans un état primitif et indompté. Des diabolosaures dominants rôdent dans les plaines des Coteaux de la terreur, des pétalasangs prédatrices frappent dans La Fondrière, et des limons rampent à travers les fosses de goudron de Lakkari. Au cœur du cratère se dresse la Crête de la Fournaise, un pic volcanique actif grouillant d'élémentaires de feu hostiles menés par l'entité Blazerunner. Pour les explorateurs et les dépeceurs, le bassin offre une richesse naturelle sans égale — y compris les peaux très convoitées des diabolosaures —, pourvu que l'on survive à la chaîne alimentaire."},{t="Refuge des Marshal",b="La présence civilisée dans le cratère se limite presque exclusivement au Refuge des Marshal, un campement en hauteur niché dans les falaises septentrionales. Menée par Williden Marshal, une expédition de scientifiques, de naturalistes et de chercheurs de fortune tenta de répertorier les trésors du bassin, avant d'être malmenée par la faune monstrueuse et contrainte de se replier sur les hauteurs. Aujourd'hui, le refuge sert de base assiégée pour les voyageurs intrépides qui étudient les mystérieux cristaux de puissance du cratère, cartographient l'activité volcanique et gardent A Watchful Eye sur les essaims de silithides qui empiètent sur les crêtes méridionales."}},faq={{q="Comment entrer dans le Cratère d’Un’Goro ?",a="Les voyageurs peuvent y entrer par des rampes naturelles qui descendent le long des parois du cratère : l'une est accessible depuis le sud-ouest de Tanaris, près de la Vallée des Chardonniers, et l'autre arrive depuis le nord-est de Silithus. Bien que des aventuriers téméraires sautent parfois du haut des falaises, la chute est fatale sans assistance magique. Le Refuge des Marshal, au nord, offre des liaisons aériennes vers Gadgetzan et Fort cénarien.",al={"comment entrer dans ungoro","entrée d'ungoro","comment atteindre le cratère d'ungoro"}},{q="À quoi servent les cristaux de puissance colorés ?",a="Des cristaux de puissance rouges, bleus, verts et jaunes sont disséminés sur le sol de la jungle. Guidés par la chercheuse Gnome J.D. Collie au Refuge des Marshal, les explorateurs peuvent déchiffrer les instructions permettant d'utiliser ces cristaux aux pylônes nord, est et ouest. Combiner des couleurs spécifiques aux pylônes appropriés canalise les énergies latentes des Titans pour confectionner des talismans défensifs ou réparateurs.",al={"cristaux d'ungoro","cristaux rouges bleus verts jaunes ungoro","pylônes d'énergie"}},{q="Pourquoi Un'Goro est-il luxuriant alors qu'il est entouré de déserts ?",a="Les érudits pensent que la vitalité anormale d'Un'Goro est artificielle et provient des Titans qui ont façonné le monde. Des conduits titaniques, la chaleur géothermique volcanique de la Crête de la Fournaise et une ancienne énergie tellurique nourrissent un écosystème isolé et hyper-accéléré qui résiste aux conditions arides des régions voisines de Tanaris et de Silithus.",al={"pourquoi ungoro est une jungle","lien désert ungoro","comment ungoro a des plantes"}},{q="Pourquoi les Qiraji appelaient-ils cet endroit les « terres des Dieux » ?",a="D'après les tablettes traduites de la guerre des Sables mouvants, les essaims d'insectes ont interrompu leur avancée au seuil du cratère. Le géologue Larksbane, qui a traduit ce récit, relie ce nom aux théories selon lesquelles les Titans auraient jadis séjourné dans le cratère, et se demande si Aman'Thul lui-même ne veillait pas sur les terres des Dieux.",al={"signification terres des dieux","qiraji ungoro","pourquoi les silithides n'ont pas pris ungoro"}},{q="À quoi sert l'Humus d'Un'Goro ?",a="Des tas de terre riche et puissante reposent à travers le bassin du cratère. Une fois ramassé, cet humus peut être associé à des graines de Tharlendris dans une Sacoche de printemps pour cultiver du morveblé, une herbe mystique ardemment recherchée par les chercheurs de Pitons-du-Tonnerre, de Darnassus et du Cercle cénarien.",al={"échantillon d'humus d'ungoro","à quoi sert l'humus d'ungoro","humus de morveblé"}},{q="Y a-t-il des campements humanoïdes ou des donjons ici ?",a="Le Cratère d’Un’Goro abrite un donjon, La terrasse du Façonneur, prévu pour les niveaux 58 à 60 environ, mais aucune société humanoïde indigène. La seule colonie durable est le Refuge des Marshal, un petit avant-poste d'expédition situé sur le rebord nord. En dehors de chasseurs ermites isolés ou d'explorateurs perdus, le reste de la caldeira est entièrement sauvage.",al={"donjons d'ungoro","qui vit à ungoro","humanoïdes à ungoro"}}},fp="14,269,13.410.0,18.462.0,16.490.0,35.282.0,45.336.0,56.270.0,51.330.0,30.235.0,52.287.0"}
P.entries["zone:wailing"] = {n="Cavernes des lamentations",s="Niché sous l'Oasis luxuriante dans les arides Tarides se trouvent les Cavernes des lamentations, un réseau labyrinthique de sources et de failles souterraines nommé d'après l'étrange sifflement de la vapeur emprisonnée. Ce qui avait commencé comme un noble effort druidique pour revitaliser la savane blanchie par le soleil de Kalimdor a dégénéré en un monde souterrain déformé et empoisonné. Les cavernes pullulent désormais d'une faune altérée et de disciples déchus corrompus par un profond et contre-nature cauchemar.",h="Niché sous l'Oasis luxuriante dans les arides Tarides se trouvent les Cavernes des lamentations, un réseau...",kw={"déviant","druides du croc","le cauchemar d'émeraude","dame anacondra","seigneur cobrahn","seigneur pythas","seigneur serpentis","oasis luxuriante","mutanus","naralex","verdan"},ang={["class:Druid"]="Pour les druides de tradition cénarienne comme de la voie des taurens, les cavernes constituent un avertissement tragique sur les périls du Rêve d'émeraude et le devoir solennel d'éliminer leurs frères déchus, les druides du Croc.",["race:NightElf"]="Naralex était une figure vénérée parmi les druides elfes de la nuit, et la tragédie de sa corruption par le Cauchemar d'émeraude représente une catastrophe douloureuse pour ses semblables par-delà la mer.",["race:Tauren"]="Les eaux altérées menacent les fragiles oasis qui soutiennent la vie à travers les Tarides, rendant la purification des sources vitale pour les tribus de Mulgore et de La Croisée."},sec={{t="Une noble vision devenue toxique",b="Le druide elfe de la nuit Naralex a initialement découvert ce vaste réseau hydrographique et conçu un projet ambitieux : en ouvrant un conduit directement vers le Rêve d'émeraude, il siphonnerait l'essence vitale primordiale pure à travers les sources souterraines, transformant les Tarides desséchées en un paradis verdoyant et prospère. Au plus profond des cavernes, Naralex entra en communion avec le Rêve, soutenu par ses loyaux acolytes. Tragiquement, au lieu de puiser dans la pure vitalité, l'esprit endormi du druide effleura le Cauchemar d'émeraude. La corruption purulente s'empara instantanément de lui, transformant son conduit bien intentionné en une vanne déversant venin et folie dans les cours d'eau souterrains."},{t="Les druides du Croc",b="Alors que l'énergie sombre du Cauchemar rayonnait depuis la silhouette impuissante de Naralex, ses élèves succombèrent à la démence. Renonçant à la tranquille sagesse du Cercle cénarien, ils formèrent les fanatiques druides du Croc. Adoptant des formes reptiliennes, les chefs de la secte — Dame Anacondra, Seigneur Cobrahn, Seigneur Pythas et Seigneur Serpentis — embrassent désormais la mutation venimeuse des cavernes plutôt que de la combattre. Ils protègent activement leur maître endormi de toute ingérence extérieure, convaincus que cette croissance corrompue constitue la véritable évolution de la nature."},{t="Le Cauchemar incarné",b="Briser l'emprise des druides du Croc ne sauve pas automatiquement Naralex. Lorsque ses derniers disciples non corrompus entament le rituel pour le tirer doucement de sa transe à Dreamer's Rock, le subconscient agité de l'elfe endormi purge violemment sa plus profonde terreur. La créature qui en jaillit — un murloc monstrueux et déformé nommé Mutanus le Dévoreur — est la manifestation physique des pires cauchemars de Naralex. Ce n'est qu'en terrassant cette abomination que le canal vers le Cauchemar peut être rompu, libérant Naralex pour qu'il s'éveille, prenne une forme aviaire et s'envole loin des cavernes souillées."}},faq={{q="Pourquoi les nomme-t-on les Cavernes des lamentations ?",a="La caverne tire son nom des cris lugubres et hurlants résonnant à travers les tunnels. Ces bruits sont produits naturellement lorsque des évents de vapeur souterrains et des rafales de vent à haute pression se frayent un chemin à travers d'étroites fissures dans la roche calcaire.",al={"pourquoi cavernes des lamentations","origine du nom","pourquoi se lamentent-elles"}},{q="Qu'est-ce qui a poussé les bêtes à l'intérieur à devenir « déviantes » ?",a="Lorsque Naralex tomba sous l'emprise du Cauchemar d'émeraude, les énergies oniriques corrompues s'écoulèrent directement dans les sources souterraines. Boire et vivre dans ces eaux contaminées ont fait muter les raptors, les crocolisques et les serpents naturels en variantes « déviantes » contre-nature.",al={"corruption des déviants","pourquoi les raptors mutent","origine des bêtes déviantes"}},{q="Qui sont les druides du Croc ?",a="Ils étaient autrefois les dévoués acolytes elfes de la nuit et taurens de Naralex. Corrompus à ses côtés par le Cauchemar, leur esprit s'est brisé et a dévoyé leurs arts druidiques vers l'adoration des serpents et du venin, adoptant des titres comme Cobrahn, Pythas et Anacondra.",al={"druides du croc","histoire des druides du croc","qui est serpentis"}},{q="Pourquoi le boss final est-il un murloc géant nommé Mutanus ?",a="Mutanus apparaît lors de la tentative de réveil de Naralex. Sa nature et son lien avec le druide endormi se révèlent au fil du rituel.",al={"pourquoi mutanus murloc","qu'est-ce que mutanus","histoire du boss final"}},{q="Que se passe-t-il après la défaite de Mutanus ?",a="La tentative du disciple de réveiller Naralex se poursuit après l'affrontement. Le sort du druide se révèle à la fin du rituel.",al={"réveiller naralex","fin de naralex","qu'arrive-t-il à naralex"}},{q="Qui vit dans la grotte au-dessus de l'entrée de la caverne ?",a="Perchés à l'intérieur de l'orbite rocheuse de la caverne semblable à un crâne se trouvent des loyalistes du Cercle cénarien, dont Nalpak et Ebru. Ils recherchent de courageux voyageurs pour récolter des Deviate Hides et purifier la corruption avant qu'elle n'engloutisse totalement les Tarides.",al={"grotte au-dessus de l'entrée","pnj oeil du crâne de serpent","qui sont nalpak et ebru"}}},fx={["3386ab3f"]={q="Quelles sont les Cavernes des lamentations ?",a="Les Cavernes des lamentations sont un vaste réseau de grottes souterraines s'étendant sous les arides Tarides, près de l'Oasis luxuriante. Ses sources souterraines naturelles canalisent l'eau sur des kilomètres sous terre, alimentant les rares oasis de surface disséminées dans la région. Découvertes par le druide elfe de la nuit Naralex, elles devaient être le cœur d'un grand projet de régénération naturelle. Au lieu de cela, elles sont devenues un épicentre de corruption dangereuse après qu'une tragique catastrophe s'est abattue sur les druides qui s'y trouvaient.",al={"qu'est-ce que les cavernes des lamentations","aperçu des cavernes des lamentations","à propos des cavernes des lamentations"}},e070a543={q="Qui vit là-bas ?",a="Les cavernes regorgent d'une faune contre-nature et de druides renégats. Les disciples corrompus de Naralex, les Druides du Croc, ont revendiqué les tunnels comme leur domaine aux côtés de serpents, de gelées, de raptors et de crocolisques mutants. À l'extérieur de l'entrée de l'instance, des bêtes sauvages, des gelées et même des parias rôdent dans les passages humides, tandis que les druides corrompus gardent les chambres intérieures et protègent leur maître endormi.",al={"qui se trouve dans les cavernes des lamentations","créatures des cavernes des lamentations","habitants des cavernes des lamentations"}},["49d47201"]={q="Pourquoi la Horde m'a-t-elle envoyé ici ?",a="L'étrange mutation des bêtes locales et les énergies impures jaillissant de l'Oasis luxuriante menacent l'ensemble des Tarides. La Horde et les druides cénariens des Pitons-du-Tonnerre ne peuvent tolérer qu'une puissance obscure incontrôlée empoisonne la terre et les voies navigables juste aux portes de la Croisée. Vous avez été envoyé pour enquêter, mettre fin aux agissements des chefs des Leaders of the Fang et aider à apaiser le danger croissant.",al={"pourquoi suis-je dans les cavernes des lamentations","mission de la horde aux cavernes des lamentations","pourquoi m'envoyer aux cavernes des lamentations"}},d445bb78={q="Cela fait-il partie d'un problème plus vaste dans les Tarides ?",a="Oui. Les canaux souterrains sous ces grottes alimentent les oasis de surface à travers les Tarides. La souillure du Cauchemar qui corrompt les eaux à l'intérieur des cavernes a commencé à se déverser dans le paysage environnant, provoquant la mutation de créatures sauvages comme les raptors et les crocolisques, et transformant l'Oasis luxuriante en un terrain de reproduction pour une étrange vie déviante.",al={"problème de l'oasis des tarides","corruption déviante des tarides","les cavernes des lamentations affectent-elles les tarides"}},["038fd1cf"]={q="Les créatures déviantes se propagent-elles en dehors des cavernes ?",a="C'est déjà le cas. Les sources souterraines s'écoulent directement dans les oasis de surface comme l'Oasis luxuriante, apportant une croissance contre-nature et des créatures mutantes au cœur de la savane. Des créatures étranges comme le Poisson déviant peuvent être pêchées dans les eaux à l'extérieur, et des prédateurs mutants agressifs harcèlent de plus en plus les voyageurs entre les oasis et la Croisée.",al={"les créatures déviantes se propagent-elles","bêtes déviantes des tarides","poisson déviant à l'extérieur"}},["8502642f"]={q="Qui est responsable ici ?",a="Alors que Naralex reste piégé dans son sommeil corrompu au plus profond des grottes, le commandement quotidien des cavernes appartient aux Druides du Croc. Ils sont dirigés par le Seigneur Serpentis, autrefois le meilleur élève de Naralex, qui a rallié ses frères corrompus pour transformer la terre en leur propre paradis déformé aux côtés d'autres chefs comme le Seigneur Cobrahn, le Seigneur Pythas et Dame Anacondra.",al={"qui dirige les cavernes des lamentations","chef des cavernes des lamentations","boss des cavernes des lamentations"}},["32be29c8"]={q="Qu'est-ce que le Rêve d'émeraude et quel est son lien avec cette grotte ?",a="Le Rêve d'émeraude est un vaste royaume spirituel représentant un Azeroth sauvage et intact, protégé par le vol draconique vert et accessible aux druides. Naralex pensait pouvoir canaliser les énergies pures et régénératrices du Rêve dans les aquifères souterrains des Cavernes des lamentations pour restaurer une flore luxuriante dans les Tarides. Cependant, lorsqu'il y a puisé, il a été piégé par le Cauchemar d'émeraude, projetant une version tordue de la nature dans les grottes physiques.",al={"lien avec le rêve d'émeraude","cavernes des lamentations rêve d'émeraude","naralex rêve d'émeraude"}},["38e519c2"]={q="Pourquoi tout le monde est-il si inquiet au sujet de cet endroit ?",a="Les sources souterraines dans les cavernes alimentent les principales oasis qui soutiennent la vie à travers les arides Tarides. Si la souillure du Cauchemar d'émeraude continue de s'infiltrer dans ces cours d'eau sans contrôle, les mutations tordues et la folie corrompant la flore et la faune de la grotte pourraient se propager dans toute la région, transformant la terre en un cauchemar éveillé.",al={"pourquoi s'inquiéter des cavernes des lamentations","menace des cavernes des lamentations pour les tarides","quel est l'état des cavernes des lamentations"}},["81917ac6"]={q="Comment ai-je fini dans les Cavernes des lamentations ?",a="Vous avez voyagé vers le sud depuis la Croisée jusqu'à l'Oasis luxuriante, en suivant les rapports faisant état de bêtes bizarres et d'eaux corrompues se répandant dans les Tarides. Cachée derrière le feuillage luxuriant et les camps de centaures Kolkar se trouve une immense caverne en forme de crâne creusée dans la roche. Attiré par les appels à l'aide des Pitons-du-Tonnerre, des gobelins de Cabestan cherchant des essences étranges, ou des disciples campés dans l'œil du crâne au-dessus, vous êtes descendu au-delà des fissures sinueuses et du sifflement des geysers souterrains dans les profondeurs gémissantes.",al={"comment suis-je arrivé ici","comment atteindre les cavernes des lamentations","d'où viens-je pour arriver ici"}},["28a012f3"]={q="Que suis-je censé faire dans les Cavernes des lamentations ?",a="Vous êtes ici pour purger la corruption qui s'est emparée de cette source souterraine. Le druide elfe de la nuit Naralex est tombé dans un sommeil cauchemardesque en essayant de revitaliser les Tarides, tordant les créatures à l'intérieur et transformant ses disciples en venimeux Druides du Croc. Vous devez traquer les quatre chefs : Dame Anacondra, le Seigneur Cobrahn, le Seigneur Pythas et le Seigneur Serpentis, pour briser leur emprise, puis aider le disciple restant à réveiller Naralex avant que son cauchemar fiévreux ne consume complètement l'oasis.",al={"quel est mon but ici","pourquoi suis-je dans les cavernes des lamentations","que fais-je là-dedans"}}},fp="15,278,31.501.0,22.495.0,24.481.1,37.218.0,50.226.0,31.267.0,51.127.1,39.123.1,52.229.0"}
P.entries["zone:warsonggulch"] = {n="Goulet des Chanteguerres",s="Le Goulet des Chanteguerres est une vallée boisée à la frontière d’Orneval et des Tarides, où la bataille entre la Horde et l’Alliance ne s’arrête jamais vraiment. Les orcs du Clan Chanteguerre y abattent les arbres d’Orneval pour la Horde, tandis que les Elfes de la nuit du Fort d’Aile-argent s’efforcent de les chasser de la forêt sacrée. Des combattants de toutes les races viennent prêter main-forte, à l’épée ou par la magie, chaque camp attaquant la forteresse adverse pour s’emparer de son drapeau.",h="Le Goulet des Chanteguerres est une vallée boisée à la frontière d’Orneval et des Tarides, où la bataille...",kw={"goulet des chanteguerres","champ de bataille","voltigeurs chanteguerre","sentinelles d'aile-argent","fort d'aile-argent","warsong mill","drapeau","bois d'œuvre","orneval","grom hellscream"},ang={["faction:Alliance"]="Les soldats de l'Alliance se battent ici pour leurs alliés elfes de la nuit, dont la forêt sacrée tombe arbre après arbre sous les haches du Clan Chanteguerre.",["faction:Horde"]="Chaque rondin qui quitte le Warsong Mill érige un mur de la Horde quelque part en Kalimdor ; tenir le goulet permet à la Horde de continuer à bâtir.",["race:NightElf"]="Ces bois ont connu les pas des kaldorei pendant dix mille ans. Chaque orc chassé du goulet est un morceau d'Orneval reconquis.",["race:Orc"]="Le Clan Chanteguerre est celui de Grom Hellscream lui-même, et le goulet est l'endroit où ses guerriers continuent d'honorer leur nom, la hache à la main contre les Sentinelles."},sec={{t="Du bois et du sang",b="La Horde a bâti son nouveau foyer en Kalimdor avec du bois, et une grande partie de ce bois provient d'Orneval. Le Clan Chanteguerre, les guerriers de Grom Hellscream, entame la forêt depuis le premier débarquement de la Horde, et leur Warsong Mill au bout du goulet approvisionne les camps et les remparts de la Horde. Pour les elfes de la nuit, chaque arbre abattu blesse une forêt qu'ils protègent depuis dix mille ans, et ils n'ont pas oublié que les guerriers de Grom ont autrefois occis Cenarius dans ces bois."},{t="Voltigeurs et Sentinelles",b="Les combattants de la Horde sont les Voltigeurs Chanteguerre, ravitaillés depuis le Campement de Mor'shan, à la limite nord des Tarides, où Kelm Hargunth veille à ce qu’ils aient armes et vivres. Face à eux se dressent les Sentinelles d’Aile-argent du Fort d’Aile-argent, des guerriers elfes de la nuit qui ont juré de chasser tous les envahisseurs d’Orneval, ravitaillés par Illiyana Braselune au Bosquet d’Aile-argent. Les alliés des deux camps affluent dans le goulet : des nains et des humains aux côtés des Sentinelles, des taurens, des trolls et des Réprouvés aux côtés des Voltigeurs."},{t="La lutte pour les bannières",b="Chaque camp tient une forteresse à une extrémité du goulet : la scierie Chanteguerre pour la Horde et le Fort d’Aile-argent pour les elfes de la nuit. Chacun y garde son étendard. La bataille est une succession de raids : les combattants s’introduisent dans la forteresse ennemie, s’emparent de son drapeau et le rapportent au leur, tandis que les défenseurs les traquent. Chaque drapeau rapporté porte un coup à l’orgueil ennemi, et le camp qui en capture le plus remporte la journée."}},faq={{q="Qu'est-ce que le Goulet des Chanteguerres ?",a="Le Goulet des Chanteguerres est un champ de bataille situé dans une vallée boisée entre Orneval et les Tarides. Les Voltigeurs Chanteguerre de la Horde et les Sentinelles d'Aile-argent des elfes de la nuit s'y affrontent au sujet de l'exploitation forestière d'Orneval par la Horde, chaque camp cherchant à capturer le drapeau adverse.",al={"qu'est-ce que le goulet des chanteguerres","champ de bataille du goulet des chanteguerres","goulet"}},{q="Pourquoi la Horde se bat-elle dans le Goulet des Chanteguerres ?",a="La Horde a besoin du bois d'Orneval pour bâtir et maintenir son foyer en Kalimdor. La scierie du Clan Chanteguerre au goulet en est l'une des sources principales, et les Voltigeurs la défendent afin que les camps et les remparts de la Horde continuent de s'élever.",al={"enjeux de la horde au goulet des chanteguerres","pourquoi les orcs coupent-ils du bois en orneval","motif des voltigeurs chanteguerre"}},{q="Pourquoi les elfes de la nuit se battent-ils dans le Goulet des Chanteguerres ?",a="Pour les elfes de la nuit, Orneval est une forêt sacrée qu'ils protègent depuis dix mille ans, et le Clan Chanteguerre y a autrefois occis le demi-dieu Cenarius. Les Sentinelles d'Aile-argent se battent pour mettre fin à l'abattage des arbres et chasser les orcs de leurs bois, et le reste de l'Alliance se tient à leurs côtés.",al={"enjeux de l'alliance au goulet des chanteguerres","pourquoi les sentinelles se battent-elles","motif des sentinelles d'aile-argent"}},{q="Qui sont les Voltigeurs Chanteguerre ?",a="Les Voltigeurs Chanteguerre sont les combattants de la Horde dans le Goulet des Chanteguerres, issus du Clan Chanteguerre autrefois mené par Grom Hellscream. Ils sont ravitaillés depuis le Campement de Mor'shan dans le nord des Tarides, où Kelm Hargunth équipe ceux qui luttent pour eux.",al={"voltigeurs chanteguerre","combattants du clan chanteguerre","kelm hargunth"}},{q="Qui sont les Sentinelles d'Aile-argent ?",a="Les Sentinelles d’Aile-argent sont des guerriers elfes de la nuit du Fort d’Aile-argent, qui ont juré de chasser la Horde d’Orneval. Illiyana Braselune, au Bosquet d’Aile-argent, ravitaille les champions de l’Alliance qui combattent à leurs côtés dans le goulet.",al={"sentinelles d'aile-argent","fort d'aile-argent","illiyana braselune"}},{q="Comment remporte-t-on la bataille dans le Goulet des Chanteguerres ?",a="Chaque camp conserve son drapeau dans son propre bastion. Les combattants mènent des raids contre la base ennemie, s'emparent de son drapeau et le ramènent à la leur tout en défendant leur bannière, et le camp qui rapporte le plus de drapeaux l'emporte.",al={"objectifs du goulet des chanteguerres","capture du drapeau chanteguerre","comment gagner au goulet des chanteguerres"}}},fp="13,291,16.424.0,23.488.0,28.315.0,22.226.0,42.201.0,46.259.0,30.223.0,33.216.0,39.193.0"}
P.entries["zone:westernplaguelands"] = {n="Maleterres de l’Ouest",s="Autrefois grenier agricole fertile du nord de Lordaeron, les Maleterres de l’ouest étouffent aujourd'hui sous une brume toxique et des légions de morts-vivants. Si les chaudrons de Kel'Thuzad ont ruiné les fermes et les villes de la région, la terre s'accroche encore avec ténacité à la vie. L'Aube d'argent, l'Alliance, les Réprouvés et la Croisade écarlate mènent tous des campagnes désespérées à travers ses champs flétris.",h="Autrefois grenier agricole fertile du nord de Lordaeron, les Maleterres de l’ouest étouffent aujourd'hui sous...",kw={"andorhal","la barricade","caer darrow","chaudrons","camp du noroît","âtreval","donjon de mardenholde","scholomance","tombeau d'uther","maleterres de l’ouest"},ang={["class:Paladin"]="Les champs profanés de Lordaeron sont une rude épreuve pour les guerriers sacrés, offrant l'occasion d'un pèlerinage au Tombeau d'Uther ainsi que d'une guerre vertueuse contre les horreurs de Scholomance et les fanatiques corrompus d'Âtreval.",["faction:Alliance"]="Le Camp du Noroît sert de garnison avancée à l'Alliance, où le commandant Ashlam Valorfist dirige des offensives pour neutraliser les chaudrons de la peste et venger les cités déchues de Lordaeron.",["faction:Horde"]="La Barricade marque la frontière de la souveraineté des Réprouvés ; de là, la Horde progresse vers l'est pour éliminer les commandants du Fléau et contester les fanatiques écarlates sur leur flanc vulnérable.",["profession:Herbalism"]="La corruption résiduelle fait de la région l'un des rares endroits où une flore rare et dangereuse, telle que la Fleur de peste et les Larmes d'Arthas, peut prendre racine au milieu des pinèdes flétries."},sec={{t="Le grenier de Lordaeron",b="Avant la Troisième guerre, cette terre était un corridor verdoyant d'exploitations agricoles s'étendant à l'est depuis les Clairières de Tirisfal jusqu'au Lac Darrowmere. Âtreval dirigeait l'administration du nord depuis le Donjon de Mardenholde, tandis que la vaste ville d'Andorhal orchestrait l'entreposage et l'exportation du grain à travers le royaume. Ce rôle agricole crucial fit de la région la cible principale de Kel'Thuzad. En introduisant la peste de la non-mort directement dans les cargaisons de grain à Andorhal, le Culte des damnés transforma la subsistance de Lordaeron en son trépas."},{t="Une terre assiégée",b="Pour empoisonner durablement le sol, le Fléau érigea quatre chaudrons de la peste massifs sur les plus grands domaines agricoles : le Champ de Gangrepierre, les Larmes de Dalson, le Repaire putride et La Flétrissure de Gahrron. Aujourd'hui, de monstrueux seigneurs des chaudrons entretiennent ces cuves nocives, crachant un brouillard venimeux dans l'atmosphère. Les arbres environnants se tordent sous des excroissances calleuses et tumorales, et une faune corrompue s'agite frénétiquement dans les sous-bois. Sous Caer Darrow, sur le Lac Darrowmere, le Sombre Maître Gandling forme des nécromanciens au sein de Scholomance, intensifiant la menace des morts-vivants."},{t="Factions divisées",b="Malgré l'omniprésence du Fléau, plusieurs factions maintiennent des têtes de pont chèrement disputées. La Croisade écarlate contrôle la forteresse d'Âtreval au nord, purgeant avec un zèle fanatique tout ce qu'elle juge souillé. Au sud, les forces de l'Alliance s'organisent depuis le Camp du Noroît, tandis que les Réprouvés défendent leurs frontières à La Barricade. L'Aube d'argent, faction neutre, sert de médiateur et dirige la lutte contre les chaudrons de la peste, venant en aide aux champions des deux camps et gardant le Tombeau d'Uther, le dernier sol véritablement sanctifié de la région."}},faq={{q="Pourquoi la Peste a-t-elle frappé si durement cette région ?",a="Andorhal était la plaque tournante du transport agricole du nord de Lordaeron. Kel'Thuzad a délibérément ciblé les réserves de la région, infectant les silos à grain et installant d'imposants chaudrons de la peste sur quatre grandes fermes afin de propager rapidement la non-mort via les cargaisons de nourriture dans tout le royaume.",al={"pourquoi les maleterres de l'ouest sont empestées","qu'est-il arrivé à andorhal","pourquoi des chaudrons ici"}},{q="Qui contrôle Âtreval au nord ?",a="Âtreval et sa forteresse, le Donjon de Mardenholde, sont aux mains de la Croisade écarlate. Bien qu'il s'agissait à l'origine d'un centre administratif régional de Lordaeron, les zélotes exécutent désormais tout étranger qui s'approche de leurs frontières, considérant quiconque ne fait pas partie de leur croisade avec suspicion.",al={"faction d'âtreval","qui vit au donjon de mardenholde","âtreval est-elle amicale"}},{q="Où les joueurs de l'Alliance et de la Horde peuvent-ils trouver des avant-postes sûrs ?",a="L'Alliance maintient le Camp du Noroît près de la frontière sud avec les Montagnes d'Alterac, disposant d'un maître de vol et d'alliés de l'Aube d'argent. La Horde opère depuis La Barricade, à la frontière occidentale menant aux Clairières de Tirisfal.",al={"où sont les maîtres de vol","camp horde maleterres de l'ouest","camp alliance maleterres de l'ouest"}},{q="À quoi servent les chaudrons de la peste dans les champs ?",a="Érigés par le Culte des damnés au Champ de Gangrepierre, aux Larmes de Dalson, au Repaire putride et à La Flétrissure de Gahrron, ces chaudrons déversent constamment des vapeurs pestilentielles dans l'air et la terre. Des agents de l'Aube d'argent recrutent des aventuriers pour abattre les seigneurs des chaudrons et élaborer des contre-poisons à ces mixtures toxiques.",al={"que sont les chaudrons","utilité des chaudrons","chaudron de felstone"}},{q="Qu'est-ce que Scholomance et où se trouve-t-elle ?",a="Scholomance est une académie souterraine de nécromancie dirigée par le Fléau et le Culte des damnés. Elle est dissimulée sous les ruines de Caer Darrow, une forteresse insulaire située dans les eaux du sud-est du Lac Darrowmere.",al={"emplacement de scholomance","où se trouve scholomance","donjon de caer darrow"}},{q="Y a-t-il une partie des Maleterres de l’ouest qui ne soit pas corrompue ?",a="Le Tombeau d'Uther, situé sur la Colline des chagrins près de la limite sud de la zone, demeure entièrement sacré et épargné par la souillure. Il se dresse comme un mémorial consacré au défunt haut général Uther le Porteur de Lumière et à l'Ordre de la Main d’argent disparu.",al={"terre sacrée maleterres de l'ouest","le tombeau d'uther est-il purifié","tombeau d'uther en sécurité"}}},fp="19,342,28.378.0,18.438.0,16.443.0,41.268.0,37.227.0,56.233.0,58.277.0,44.206.0,51.204.0"}
P.entries["zone:westfall"] = {n="Marche de l’Ouest",s="Les fermes de la Marche de l’Ouest sont sans défense, et la Confrérie défias tient une grande partie des campagnes. Jadis grenier de Hurlevent, le territoire peine désormais à survivre sans soutien de la couronne ni garnisons militaires.",h="Les fermes de la Marche de l’Ouest sont sans défense, et la Confrérie défias tient une grande partie des...",kw={"les mortemines","défias","golem des moissons","milice","ruisselune","saldean","colline des sentinelles","roidemantel","vancleef","marche de l’ouest"},ang={["class:Rogue"]="En tant que voleur, vous découvrez une guerre de l’ombre dans la Marche de l’Ouest, où les espions du SI:7 affrontent les éclaireurs aguerris, les voleurs et les assassins de la Confrérie défias.",["faction:Alliance"]="En tant que voyageur de l’Alliance, vous pouvez voir comment la People's Militia tient la Colline des Sentinelles. Sans elle, la Confrérie défias contrôlerait les accès méridionaux à la Forêt d’Elwynn.",["profession:Cooking"]="En tant que cuisinier, vous pouvez découvrir comment les fermiers accablés de la Ferme des Saldean s’accommodent des bêtes locales à la chair coriace et enseignent aux voyageurs la préparation du Westfall Stew.",["race:Human"]="En tant qu’humain, vous voyez dans la Marche de l’Ouest le déclin politique de Hurlevent. Les fermiers qui meurent de faim dans la poussière ont été abandonnés par la noblesse qu’ils s’épuisaient à nourrir."},sec={{t="Une terre délaissée",b="Les pâturages et les champs de blé de la Marche de l’Ouest nourrissaient autrefois le royaume de Hurlevent. Après la Second War, les finances du royaume se sont taries, et ses dirigeants ont négligé le territoire. Hurlevent a envoyé ses ressources ailleurs et retiré ses garnisons. Les terres sont restées en friche.\n\nDésormais, les pâturages stériles, les vents côtiers violents, les golems des moissons incontrôlables et les gnolls Riverpaw rendent la survie difficile aux rares fermiers restants."},{t="L’essor de la Confrérie",b="L’arrivée de la Confrérie défias a précipité l’effondrement de la Marche de l’Ouest. Les bandits portent des masques rouges et suivent un chef dont personne dans les campagnes ne connaît le nom. Ils ont fait de la Marche de l’Ouest leur bastion, brûlant les champs des fermiers, salant les terres et s’emparant des mines abandonnées.\n\nDepuis Ruisselune, une ville fantôme, la Confrérie règne de fait sur la majeure partie des campagnes."},{t="La People's Militia",b="La House of Nobles a ignoré la détresse de la Marche de l’Ouest, alors les habitants ont pris leur défense en main. À la Colline des Sentinelles, Gryan Roidemantel a formé la People's Militia, une force de volontaires qui résiste aux gnolls et aux bandits. Hurlevent n’envoie ni soldats réguliers ni ravitaillement.\n\nLa milice compte sur les aventuriers de passage pour repousser les Défias et protéger les fermes qui subsistent."},{t="Des maçons aux masques rouges",b="Edwin VanCleef dirige la Confrérie. Il était le maître de guilde qui a reconstruit Hurlevent, mais la House of Nobles a refusé de payer ses tailleurs de pierre, et des émeutes les ont chassés. Ils ont adopté le masque rouge dans la Marche de l’Ouest. Les bandits qui brûlent ses champs sont ceux-là mêmes qui ont érigé les remparts de la capitale."},{t="Le complot des Mortemines",b="Sous Ruisselune, Edwin VanCleef a rassemblé des coupe-jarrets, des gobelins et des renégats dans les galeries aurifères abandonnées des Mortemines. La Confrérie y construit un immense navire de guerre cuirassé. Il doit remonter la côte et bombarder Hurlevent."}},faq={{q="Pourquoi tant de fermes sont-elles abandonnées dans la Marche de l’Ouest ?",a="Hurlevent a retiré ses garnisons lorsque leur entretien est devenu trop coûteux, laissant la Marche de l’Ouest sans protection. La Confrérie défias s’est alors emparée d’une grande partie des campagnes, chassant les fermiers, brûlant les cultures et reprogrammant les gardiens mécaniques des moissons en sentinelles meurtrières.",al={"fermes abandonnées","pourquoi la marche de l’ouest est-elle morte","pourquoi les terres sont-elles en friche"}},{q="Pourquoi Hurlevent n’envoie-t-elle pas de troupes aider la Marche de l’Ouest ?",a="Le trésor du royaume est à bout, et la House of Nobles accorde davantage de priorité aux menaces qui pèsent sur d’autres terres. Les manipulations de la cour ont aussi discrètement privé la Marche de l’Ouest d’attention et de ravitaillement, laissant les habitants se défendre seuls.",al={"pourquoi aucune armée de hurlevent","où sont les gardes","aide de hurlevent"}},{q="Qu’est-ce que la People's Militia ?",a="Gryan Roidemantel a organisé la People's Militia à la Colline des Sentinelles pour défendre la Marche de l’Ouest. Sans soldats de la couronne, fermiers et colons se sont unis pour combattre la Confrérie défias et les gnolls Riverpaw.",al={"people's militia","milice de la colline des sentinelles","armée de gryan roidemantel"}},{q="Qui dirige la Confrérie défias dans la Marche de l’Ouest ?",a="Edwin VanCleef, ancien maître de la Stonemasons Guild, dirige la Confrérie défias. Il a supervisé la reconstruction de Hurlevent, puis conduit ses ouvriers dans la Marche de l’Ouest et les a armés après un âpre conflit salarial qui s’est terminé en émeutes.",al={"chef des défias","qui dirige les défias","vancleef"}},{q="Que cache Ruisselune ?",a="Sous une grange d’apparence banale de Ruisselune se trouve l’entrée des Mortemines. La Confrérie défias a transformé la mine d’or abandonnée en forteresse souterraine et en chantier naval pour sa guerre contre Hurlevent.",al={"secret de ruisselune","que contiennent les mortemines","mine de ruisselune"}},{q="Pourquoi les épouvantails mécaniques attaquent-ils les gens ?",a="Des bricoleurs gobelins alliés aux Défias ont capturé les gardiens mécaniques des moissons, conçus à l’origine pour entretenir les cultures et éloigner les nuisibles. Ils les ont modifiés pour patrouiller dans les champs et tuer les intrus.",al={"golems des moissons agressifs","gardiens des moissons","épouvantails maléfiques"}}},fx={ec2fd06e={q="Hurlevent a-t-il vraiment refusé de payer les tailleurs de pierre ?",a="Oui. La Chambre des nobles avait accumulé des dettes astronomiques en multipliant les expéditions militaires ailleurs, laissant le royaume au bord de la faillite. Influencés par les intrigues de cour et l’arrogance aristocratique, les nobles n’ont proposé qu’une somme dérisoire pour un travail colossal, refusant purement et simplement d’honorer les contrats dans leur intégralité.",al={"est-ce que hurlevent a triché avec les tailleurs de pierre","pourquoi les nobles n’ont pas payé","litige sur le paiement des tailleurs de pierre"}},cf60f690={q="Pourquoi y a-t-il tant de gnolls dans la Marche de l’Ouest ?",a="Les gnolls de la meute des Pattes-de-rivière ont traversé la frontière pour profiter de l’absence de soldats de Hurlevent. Pire, la Confrérie défias les a activement recrutés comme mercenaires, les positionnant à travers les collines et les plaines pour tendre des embuscades aux voyageurs et harceler les fermes survivantes.",al={"pourquoi y a-t-il des gnolls ici","gnolls pattes-de-rivière marche de l’ouest","gnolls danuvin"}},e40fa3bd={q="Qu’est-ce que Ruisselune ?",a="Ruisselune était autrefois la principale ville marchande et minière du sud de la Marche de l’Ouest. Située au-dessus de l’ancienne entrée des Mortemines, elle a été totalement saisie et évacuée par la Confrérie défias, qui utilise désormais ses bâtiments vides comme périmètre de garde pour leur bastion souterrain.",al={"qu’est-ce que ruisselune","histoire de ruisselune","parle-moi de ruisselune"}},["46f1c864"]={q="Où mène l’enquête sur les Défias ?",a="Votre enquête révèle le cœur secret de la Confrérie sous Ruisselune, dans les Mortemines. Là, au plus profond des cavernes souterraines, Edwin VanCleef supervise la construction d’un gigantesque cuirassé blindé destiné à bombarder Hurlevent depuis la mer, ce qui conduit à un affrontement direct avec le maître de guilde lui-même.",al={"où mène la suite de quêtes défias","comment se termine l’histoire des défias","conclusion des mortemines"}},["27471424"]={q="Comment ai-je fini dans la Marche de l’Ouest ?",a="Vous avez probablement traversé le pont de la rivière depuis la Forêt d’Elwynn en suivant la route vers l’ouest, envoyé par les autorités ou des amis de la Colline des Sentinelles. Hurlevent étant à court d’effectifs et incapable de détacher des troupes royales, le mot s’est répandu dans les terres voisines que Gryan Roidemantel et les fermiers locaux ont désespérément besoin d’aide. Que vous soyez venu en répondant à un appel à l’aide ou simplement en suivant la route royale à la recherche de travail, vous avez pénétré dans un royaume que les soldats du royaume ont pratiquement abandonné.",al={"comment suis-je arrivé ici","comment suis-je arrivé dans la marche de l’ouest","comment ai-je fini ici"}},["6324593c"]={q="Que suis-je censé faire dans la Marche de l’Ouest ?",a="Votre mission principale est d’aider la milice locale à la Colline des Sentinelles à repousser les innombrables menaces qui étouffent la province. Gryan Roidemantel a besoin de volontaires pour éliminer la faune agressive, réduire au silence les gardiens des moissons renégats qui rôdent dans les champs en friche et repousser les gnolls Pattes-de-rivière. Surtout, vous êtes chargé de traquer l’insaisissable Confrérie défias, de découvrir où ils se cachent et de briser leur emprise sur ce qu’il reste des fermes en difficulté de la Marche de l’Ouest.",al={"que dois-je faire ici","que fais-je dans la marche de l’ouest","pourquoi suis-je ici"}},cd1e134e={q="Qu'est-ce que la Marche de l’Ouest ?",a="La Marche de l’Ouest est le territoire balayé par les vents à l'ouest du royaume de Hurlevent, s'étendant à l'ouest de la Forêt d’Elwynn jusqu'à la mer. Autrefois le grenier à blé fertile du royaume, ses collines vallonnées et ses vastes pâturages ont nourri Hurlevent pendant des générations. Aujourd'hui, négligée par la couronne et ravagée par le conflit, elle s'est détériorée en plaines de poussière en jachère, en fermes en ruines et en territoire de hors-la-loi.",al={"quelle est cette zone","parlez-moi de la marche de l'ouest","histoire de la marche de l'ouest"}},["44cadea7"]={q="Pourquoi est-ce si désert ici ?",a="Un mélange combiné de sécheresse, de négligence et de banditisme a vidé la campagne. Après la Deuxième Guerre, Hurlevent a concentré ses soldats ailleurs, laissant les fermes locales sans défense. Lorsque la The Defias Brotherhood s'est soulevée, ils ont chassé les fermiers, brûlé les récoltes et salé les champs. Sans garnisons royales pour les protéger, la plupart des habitants ont fui ou sont morts de faim.",al={"pourquoi la marche de l'ouest est-elle stérile","pourquoi est-ce si vide","pourquoi n'y a-t-il personne ici"}},["1a97e791"]={q="La Marche de l’Ouest a-t-elle toujours été aussi pauvre ?",a="Pas du tout. Pendant des générations, la Marche de l’Ouest fut le fier cœur agricole de Hurlevent, célèbre pour ses champs de blé dorés, son sol riche et ses mines d'or abondantes comme Jangolode et Mortemines. Sa nourriture nourrissait la capitale, et ses mines remplissaient les trésors royaux avant que les guerres et les troubles intérieurs ne la laissent stérile.",al={"la marche de l'ouest a-t-elle toujours été pauvre","la marche de l'ouest était-elle riche avant","passé de la marche de l'ouest"}},["1d4a9481"]={q="Qui est la The Defias Brotherhood ?",a="La The Defias Brotherhood est une organisation criminelle massive composée de maçons renégats, de voleurs, de brigands et de parias. Dirigés par Edwin VanCleef, ils ont pris le contrôle des fermes et des mines abandonnées de la Marche de l’Ouest pour mener une âpre guerre de l'ombre contre le royaume de Hurlevent, déterminés à obtenir vengeance pour les dettes impayées et les trahisons perçues.",al={"qui sont les defias","qu'est-ce que la the defias brotherhood","qui sont ces bandits"}},b6953315={q="Pourquoi les Defias portent-ils des bandanas rouges ?",a="Les bandanas rouges sont la marque de fabrique de la The Defias Brotherhood, et le matériau indique le rang d'un membre. Les Red Silk Bandanas identifient les membres de haut rang ; l'Eclaireur Riell demande aux aventuriers de les collecter comme preuve de leur mort.",al={"pourquoi les bandanas rouges","masques rouges defias","signification des masques rouges"}},["908b4fe1"]={q="Que veulent les Defias dans la Marche de l’Ouest ?",a="Ils traitent la Marche de l’Ouest comme leur bastion souverain et leur base arrière. En contrôlant ses mines d'or, en s'emparant des approvisionnements alimentaires et en chassant les fermiers loyalistes, ils peuvent secrètement renforcer leurs troupes et leurs machines loin du regard direct de Hurlevent tout en complotant la chute du royaume.",al={"que veulent les defias","objectifs des defias dans la marche de l'ouest","pourquoi les defias sont-ils dans la marche de l'ouest"}},d384bc2d={q="Pourquoi ai-je été envoyé dans la Marche de l’Ouest ?",a="Vous avez été dirigé ici parce que l'armée régulière de Hurlevent refuse ou échoue à déployer des troupes dans la Marche de l’Ouest, laissant le territoire sur le point de tomber entièrement sous le joug du banditisme. Les autorités de la Forêt d’Elwynn redirigent les aventuriers capables vers l'ouest pour soutenir les locaux en difficulté qui ont désespérément besoin d'aide.",al={"pourquoi suis-je dans la marche de l'ouest","qui m'a envoyé dans la marche de l'ouest","pourquoi m'envoyer ici"}},d59f010f={q="Qui est Gryan Roidemantel ?",a="Gryan Roidemantel est un paladin de la Main d'argent et un natif de la Marche de l’Ouest. Revenant chez lui après avoir combattu en Lordaeron pendant la Troisième Guerre, il trouva sa terre natale envahie par les bandits et désertée par l'armée de Hurlevent. En réponse, il a rassemblé les défenseurs locaux pour établir la The People's Militia à la Colline des Sentinelles.",al={"qui est roidemantel","gryan roidemantel","qui dirige la colline des sentinelles"}},af1c3ddb={q="Gryan Roidemantel est-il réellement responsable de la Marche de l’Ouest ?",a="En pratique, oui. Bien que le jeune roi à Hurlevent détienne une revendication légale sur la Marche de l’Ouest, la couronne n'exerce presque aucune autorité réelle ici. Roidemantel et sa milice de volontaires à la Colline des Sentinelles représentent la seule défense et force de maintien de l'ordre fonctionnelles restant dans le royaume.",al={"qui gouverne la marche de l'ouest","roidemantel est-il le chef","qui est responsable"}},c01912f7={q="Qu'est-il arrivé à la Stonemasons Guild ?",a="Sous la direction du maître de guilde Edwin VanCleef, la Stonemasons Guild a passé des années à reconstruire Hurlevent après la Première guerre. Une fois le travail terminé, la House of Nobles a refusé de payer la somme convenue. Après l'échec des appels pacifiques, la guilde a été dissoute de force, déclenchant de furieuses émeutes qui ont poussé les maçons à l'exil.",al={"qu'est-il arrivé aux stonemasons","histoire de la stonemasons guild","qui étaient les stonemasons"}}},fp="8,190,18.391.0,27.355.0,20.380.0,19.294.1,24.254.1,44.264.0,52.230.0,29.199.0,45.227.1,32.204.1,51.187.0"}
P.entries["zone:wetlands"] = {n="Les Paluns",s="Les Paluns sont un vaste marécage enveloppé de brume, niché entre les montagnes de Khaz Modan et les rivages de la baie de Baradin. Historiquement éprouvés par les guerres naines et les invasions orques, ils servent de zone tampon accidentée entre Forgefer et les terres septentrionales de Lordaeron. Le port fortifié du Port de Menethil constitue la principale bouée de sauvetage de l'Alliance dans une contrée sauvage et détrempée, envahie par les orcs Gueules-de-dragon, les murlocs et les gnolls.",h="Les Paluns sont un vaste marécage enveloppé de brume, niché entre les montagnes de Khaz Modan et les rivages...",kw={"baie de baradin","gueules-de-dragon","dun algaz","dun modr","grim batol","menethil","port de menethil","viaduc de thandol","les paluns"},ang={["faction:Alliance"]="Le Port de Menethil sert de principale porte d'accès en eau profonde de l'Alliance à travers la Grande mer, reliant les royaumes de l'est aux avant-postes expéditionnaires de Kalimdor.",["profession:Mining"]="Les collines et les profondeurs caverneuses du Rocher de Thelgen abritent de riches filons minéraux, notamment de rares gisements de minerai d'incendicite très convoités par les mineurs et ingénieurs nains.",["race:Dwarf"]="Pour les nains, les Paluns sont un lieu doux-amer marqué par la perte de Dun Modr, la tragédie antique de Grim Batol et l'effort permanent pour défendre la route commerciale du roi Magni vers le nord."},sec={{t="Une terre d'eau et de ruines",b="S'étendant sous le précipice imposant du barrage de Formepierre, les Paluns sont une étendue froide et gorgée d'eau, drapée d'un brouillard perpétuel et de ciels d'un gris uniforme. Bien qu'ils aient autrefois abrité des colonies naines prospères, la Fondrière est désormais parsemée de ruines de pierre englouties, de fondrières détrempées et de bourbiers traîtres. Les aventuriers pénétrant dans la région doivent emprunter des défilés étroits, soit en venant du sud depuis Dun Algaz et Loch Modan, soit en franchissant les arches imposantes du viaduc de Thandol depuis les Hautes-terres Arathies."},{t="Les cicatrices de Grim Batol",b="Les confins orientaux du marais sont dominés par la présence menaçante de Grim Batol, l'ancienne place forte des Marteaux-hardis. Après sa profanation durant la guerre des Trois Marteaux, elle devint le réduit fortifié du clan Gueules-de-dragon pendant la Deuxième guerre. Lorsque le Vol draconique rouge s'est libéré de sa captivité imposée par les orcs, sa vengeance ardente a brisé les forces orques et ravagé les pentes environnantes. Aujourd'hui, des draconiens rouges gardent les portes des Gueules-de-dragon contre tout intrus, tandis que des vestiges sauvages du clan Gueules-de-dragon occupent des campements épars sur les collines, continuant de harceler les voyageurs à travers le marécage."},{t="Port de la côte ouest",b="Perché au bord de la baie de Baradin, le Port de Menethil est le cœur battant du commerce et de la logistique de l'Alliance en Khaz Modan. Nommé en l'honneur du roi Terenas Menethil II, ce port vaillant relie les Royaumes de l'est au lointain Kalimdor grâce à des navires de transport réguliers naviguant vers l'Ile de Theramore et, par le biais d'Austrivage, vers Auberdine. Malgré son importance militaire stratégique et sa solide architecture naine, le port est perpétuellement menacé par les murlocs côtiers, les créatures des marais et les écumeurs du littoral qui s'attaquent aux navires franchissant les passes rocheuses."},{t="Frontières assiégées",b="Les Paluns sont une zone de guerre active sur de multiples fronts. Tout au nord, les nains Sombrefer sous les ordres du démoniste Balgaras le Souilleur ont saboté à l'explosif le viaduc de Thandol et envahi la ville de Dun Modr, coupant les convois de ravitaillement terrestres. Pendant ce temps, les gnolls Poil-moussu pullulent dans les marais du centre, menaçant même d'anciens protecteurs comme Rethiel le Gouverneur vert. Entre bandes de guerre d'orcs renégats, infiltrateurs Sombrefer et épaves maudites le long de la côte, tenir le marécage exige une vigilance constante."}},faq={{q="Comment se rendre aux Paluns à pied ?",a="Les aventuriers de l'Alliance voyagent généralement vers le nord depuis Loch Modan en passant par le défilé montagneux de Dun Algaz. Les voyageurs de la Horde venant du nord peuvent franchir le viaduc de Thandol depuis les Hautes-terres Arathies. Prenez garde, car ces deux voies de passage sont disputées par des forces hostiles telles que les orcs Gueules-de-dragon et les nains Sombrefer.",al={"comment aller aux paluns","chemin vers les paluns","courir vers les paluns"}},{q="Où vont les bateaux du Port de Menethil ?",a="Les quais du Port de Menethil exploitent deux liaisons maritimes majeures vers Kalimdor : un navire fait escale à Austrivage dans les Contreforts de Hautebrande, puis traverse la Grande mer jusqu'à Auberdine sur les rivages de Sombrivage, tandis que l'autre navigue vers le sud en direction de l'Ile de Theramore dans le Marécage d’Âprefange.",al={"bateaux de menethil","navires du port de menethil","où va le bateau dans les paluns"}},{q="Qu'est-ce que Grim Batol et pourquoi est-il gardé ?",a="Grim Batol est une ancienne forteresse naine abandonnée après la guerre des Trois Marteaux, puis occupée par le clan Gueules-de-dragon. Après la Deuxième guerre, le Vol draconique rouge libéré en chassa les orcs et scella la montagne. De puissants rejetons et draconiens rouges patrouillent devant les portes des Gueules-de-dragon pour empêcher quiconque de pénétrer dans ces salles maudites.",al={"pourquoi y a-t-il des dragons à grim batol","dragons rouges de grim batol","portes des gueules-de-dragon"}},{q="Qu'est-il arrivé à Dun Modr ?",a="Dun Modr était une place forte naine du nord qui gardait le viaduc de Thandol. Elle a été récemment attaquée et envahie par des nains Sombrefer menés par Balgaras le Souilleur. Les survivants, menés par Rhag Garmason, maintiennent un campement retranché à proximité tout en luttant pour reconquérir leur ville.",al={"qui a détruit dun modr","ruines de dun modr","sombrefer à dun modr"}},{q="Qui est Rethiel le Gouverneur vert ?",a="Rethiel est un ancien bourbier vivant qui réside dans la Ceinture verte des Paluns. Il sollicite l'aide des voyageurs pour endiguer la vague d'agressifs gnolls Poil-moussu et abattre les Rampants des tourbières malades afin que les marais puissent se régénérer.",al={"la ceinture verte","rethiel paluns","qui est the greenwarden"}},{q="D'où viennent tous les orcs présents dans le marais ?",a="Les orcs appartiennent au clan Gueules-de-dragon, qui s'était initialement retranché à Grim Batol durant la Deuxième guerre. Après avoir été dévastés par le Vol draconique rouge libéré, les orcs survivants se sont enfuis dans le marécage et sur les collines, d'où ils mènent encore des raids contre les routes et les voyageurs.",al={"pourquoi y a-t-il des orcs dans les paluns","gueules-de-dragon des paluns","clan des gueules-de-dragon paluns"}}},fx={["78aee5e0"]={q="Comment suis-je arrivé dans les Paluns ?",a="La plupart des voyageurs de l'Alliance atteignent les Paluns en se dirigeant vers le nord depuis le Loch Modan, affrontant les tunnels étroits des montagnes de Dun Algaz pour descendre dans les marécages brumeux en contrebas. D'autres arrivent par bateau depuis la Grande mer, accostant au Port de Menethil en venant des rivages de Kalimdor. Ceux qui s'aventurent au sud depuis les Hautes-terres Arathies doivent, quant à eux, traverser les passages périlleux du Viaduc de Thandol en ruines.",al={"comment suis-je arrivé ici","comment suis-je arrivé dans les paluns","d'où viens-je"}},["87ca94d2"]={q="Que suis-je censé faire dans les Paluns ?",a="Le marécage est une frontière en difficulté où l'Alliance s'accroche à un fragile point d'ancrage. Depuis le Port de Menethil, vous êtes appelé à protéger les routes commerciales essentielles et à repousser les orcs Gueule-de-dragon qui pillent les basses terres. Plus loin à l'est et au nord, les alpinistes nains ont besoin de votre acier pour contenir les meutes de gnolls hostiles, aider les sites de fouilles en difficulté et repousser les nains Sombrefer qui menacent de couper complètement le Viaduc de Thandol.",al={"que dois-je faire ici","pourquoi suis-je ici","quelle est ma mission dans les paluns"}},["2cd88152"]={q="Qu’est-ce que les Paluns ?",a="Les Paluns sont un marais froid et étendu niché entre les montagnes de Khaz Modan et la mer occidentale. Enveloppés d’une brume grise perpétuelle, ils se situent juste au nord de Loch Modan et au sud des Hautes-terres Arathies. Autrefois foyer de nombreuses colonies naines, la région a été ravagée par les guerres passées et constitue désormais une nature sauvage, accidentée et indomptée qui sépare les royaumes nains des ruines de Lordaeron.",al={"qu’est-ce que les paluns","histoire des paluns","parle-moi des paluns"}},["4984d286"]={q="Pourquoi est-ce un marécage ici ?",a="Les Paluns se trouvent dans un bassin bas bordé sur trois côtés par des chaînes de montagnes imposantes, captant les eaux de ruissellement et le drainage des sommets. Il est alimenté par d’innombrables rivières, étangs et ruisseaux descendant vers la Baie de Baradin, maintenant le sol perpétuellement saturé et froid.",al={"pourquoi les paluns sont-ils un marécage","géographie des paluns","pourquoi tant d’eau dans les paluns"}},["60c5b961"]={q="Qui vit dans les Paluns ?",a="La principale présence civilisée est l’Alliance au Port de Menethil, aux côtés des montagnards nains qui luttent pour tenir des avant-postes clés. Cependant, la nature sauvage est dominée par des forces hostiles : des orcs Gueule-de-dragon renégats qui se cachent dans les contreforts orientaux, des gnolls Moussus rôdant dans les marais, des murlocs rampant le long des côtes et des nains Sombrefer violents poussant vers le sud depuis Dun Modr.",al={"qui vit ici","factions des paluns","habitants des paluns"}},["8d21dccb"]={q="Qu’est-ce que le Port de Menethil et qui le dirige ?",a="Le Port de Menethil est une ville portuaire fortement fortifiée construite sur une île de la Baie de Baradin, servant de porte d’entrée côtière principale de l’Alliance en Khaz Modan. Nommé en l’honneur du roi Terenas Menethil II de Lordaeron, il est entretenu par des nains et des humains alliés, protégé par les solides murs de pierre du Donjon de Menethil et gardé par la garnison du Capitaine Rudepoing.",al={"port de menethil","qui dirige menethil","ville de menethil"}},fd9bb568={q="Pourquoi les nains ont-ils construit un port ici ?",a="Pendant la Deuxième guerre, Orgrim Marteau-du-Destin a construit un chantier naval ici pour transporter la Horde à travers la Baie de Baradin jusqu’à Lordaeron. Après avoir chassé les orcs, l’Alliance a récupéré le site et l’a reconstruit en un port prospère, établissant des routes d’approvisionnement maritimes essentielles reliant Khaz Modan à la fois aux alliés humains et aux terres lointaines à travers la mer.",al={"pourquoi le port de menethil","pourquoi construire un port dans le marais","raison d’être du port de menethil"}},["4cff40a7"]={q="Le Port de Menethil est-il un territoire de l’Alliance ?",a="Oui. Le Port de Menethil est une place forte officielle de l’Alliance. Bien qu’il s’agisse d’une ville portuaire rude et animée, remplie de marins, de marchands, de voyageurs et de dockers bourrus, elle arbore la bannière de l’Alliance et est défendue par les forces de Forgefer.",al={"menethil est-il alliance","faction du port de menethil","qui possède le port de menethil"}},["6dc9c02b"]={q="Qui est responsable par ici ?",a="Il n’y a pas de dirigeant unique pour ces marécages indomptés. L’autorité de l’Alliance est concentrée au Port de Menethil sous le commandement du Capitaine Rudepoing et de la garnison du Donjon de Menethil. En dehors des murs du port, le marais est une frontière sans foi ni loi disputée par des patrouilles militaires, des seigneurs de guerre orcs et des bêtes primordiales.",al={"qui dirige les paluns","commandant des paluns","qui est le chef ici"}},b8a9f96f={q="Qui est le Capitaine Rudepoing ?",a="Le Capitaine Rudepoing est le commandant nain responsable de la garnison au Port de Menethil. Depuis la sécurité du port, il coordonne les opérations défensives à travers le marais, chargeant des aventuriers compétents de contenir les raids incessants des orcs Gueule-de-dragon voisins.",al={"capitaine rudepoing paluns","histoire de rudepoing","qui est rudepoing"}},["38351a9f"]={q="Qui sont les orcs Gueule-de-dragon et pourquoi sont-ils ici ?",a="Les Gueule-de-dragon sont un clan orc brutal qui a utilisé l’Âme des démons pour asservir Alexstrasza et le Vol draconique rouge pendant la Deuxième guerre, régnant depuis les hauteurs de Grim Batol. Lorsque la Reine-dragon a été libérée, les dragons vengeurs ont brisé le clan, dispersant les survivants dans les marais et les montagnes des Paluns, où ils restent une menace violente et persistante.",al={"gueule-de-dragon paluns","pourquoi les gueule-de-dragon sont-ils dans les paluns","orcs gueule-de-dragon"}},ecc875bb={q="Qui sont les nains Sombrefer et pourquoi attaquent-ils Dun Modr ?",a="Les Sombrefer sont un clan nain perfide et adepte des ombres, exilé depuis longtemps de Forgefer. Profitant du déploiement des forces de l’Alliance à l’étranger, ils ont frappé vers le nord, s’emparant de la ville de Dun Modr et sabotant le Viaduc de Thandol pour couper les communications vitales et reprendre du terrain en Khaz Modan.",al={"sombrefer dun modr","pourquoi les sombrefer dans les paluns","attaque sombrefer des paluns"}},["0f0d7fa8"]={q="Qu’est-ce que le Viaduc de Thandol et pourquoi est-ce important ?",a="Le Viaduc de Thandol est une magnifique paire de ponts de pierre nains massifs enjambant le gouffre entre le nord de Khaz Modan et les Hautes-terres Arathies. Construit après la Guerre des trois marteaux pour faciliter le commerce et la fraternité avec les Marteaux-hardis, il reste le seul lien terrestre entre les royaumes du sud et le nord de Lordaeron.",al={"viaduc de thandol","pont de thandol","pourquoi le viaduc de thandol est-il important"}},faff9f74={q="Pourquoi les Sombrefer veulent-ils le faire sauter ?",a="En détruisant le Viaduc de Thandol, les Sombrefer visent à isoler complètement Forgefer et Khaz Modan des alliés de l’Alliance à Lordaeron. Couper cette bouée de sauvetage terrestre empêche les renforts de marcher vers le sud pour reprendre Dun Modr ou apporter de l’aide contre de nouvelles incursions Sombrefer.",al={"pourquoi détruire le viaduc de thandol","complot du pont sombrefer","faire sauter le viaduc de thandol"}},eabba297={q="Comment ai-je fini dans les Paluns et où cela mène-t-il ensuite ?",a="La plupart des voyageurs arrivent en marchant vers le nord par le col de montagne de Dun Algaz depuis Loch Modan, ou en faisant le long voyage jusqu’au Port de Menethil en bateau. De là, la route continue vers le nord à travers le Viaduc de Thandol vers les Hautes-terres Arathies, tandis que les navires quittant les quais emmènent les aventuriers vers l’ouest à travers la Grande mer.",al={"où aller depuis les paluns","zone suivante après les paluns","chemin des paluns"}},["75fb0ece"]={q="Est-ce la route pour Forgefer ?",a="Oui. Suivre la route vers le sud depuis le marais vous mène directement dans les tunnels étroits de Dun Algaz. Passer par les montagnes vous amène à Loch Modan, d’où l’autoroute principale se dirige vers l’ouest par le Passage de la porte Nord directement dans les neiges de Dun Morogh et de Forgefer.",al={"route vers forgefer depuis les paluns","comment aller à forgefer depuis les paluns","chemin vers forgefer"}}},fp="8,284,24.340.0,23.473.0,22.380.0,18.430.0,40.227.0,41.185.0,41.317.0,26.225.0,31.198.1,46.224.0"}
P.entries["zone:winterspring"] = {n="Berceau-de-l’Hiver",s="Le Berceau-de-l’Hiver est une vaste vallée enneigée nichée sur les pentes nord-est du mont Hyjal, directement au-dessus des forêts enchantées de Reflet-de-Lune et de Gangrebois. Réputée pour son froid glacial, ses ruines bien-nées ancestrales et ses redoutables prédateurs errants, la région s'articule autour de l'avant-poste gobelin neutre de Long-guet. C'est une contrée de redoutables périls naturels abritant les vestiges du Vol draconique bleu, tout en affrontant la corruption démoniaque sur ses hauteurs méridionales.",h="Le Berceau-de-l’Hiver est une vaste vallée enneigée nichée sur les pentes nord-est du mont Hyjal, directement...",kw={"dragons bleus","gorge du sombre murmure","donova antreneige","long-guet","sabre-de-givre","calot de glace","kel'theril","mazthoril","grumegueules","berceau-de-l’hiver"},ang={["class:Druid"]="Situé sur les hauteurs de Reflet-de-Lune, le Berceau-de-l’Hiver revêt une importance sacrée en tant que lieu où Malfurion Hurlorage réveilla les druides de la Serre de leur long sommeil au cours de la Troisième guerre.",["faction:Alliance"]="Les héros de l'Alliance rendent fréquemment visite à Rivern Givrevent au roc des Sabres-de-Givre, œuvrant sans relâche dans ce froid extrême pour gagner la loyauté des prestigieuses montures sabres-de-givre du Berceau-de-l’Hiver.",["profession:Herbalism"]="Le Berceau-de-l’Hiver est le seul habitat connu du calot de glace, une herbe alpine essentielle très convoitée pour les préparations alchimiques avancées, aux côtés de pousses éparses de sauge-argent des montagnes et de rares lotus noirs.",["profession:Mining"]="Les parois caverneuses et les crêtes glacées de la vallée regorgent de minerais précieux, offrant fréquemment de petits et de riches filons de thorium ainsi que de rares gisements de vrai-argent.",["race:NightElf"]="Le Berceau-de-l’Hiver est intimement lié à l'histoire elfique, abritant les terriers où reposèrent les druides de la Serre pendant des millénaires, Les ruines de Kel'Theril au destin tragique et les racines exposées de Nordrassil meurtries durant la bataille du mont Hyjal."},sec={{t="Un royaume de givre perpétuel",b="Perché à des milliers de mètres au-dessus des étendues sauvages environnantes, le Berceau-de-l’Hiver baigne sous un air vif de montagne et d'incessantes tempêtes de neige. D'immenses racines découvertes de l'Arbre-Monde, Nordrassil, percent les congères telles de gigantesques arches de bois, déformées et tordues lors des affrontements tragiques de la Troisième guerre. Tandis qu'une grande partie du nord de Kalimdor est dominée par des forêts denses et un climat tempéré, le Berceau-de-l’Hiver est une terre paisible de forêts alpines clairsemées, de falaises rocheuses et de lacs gelés, foyer de redoutables sabres-de-givre, chimères, yétis et ours d'hiver à la fourrure épaisse."},{t="Carrefours et avant-postes",b="Pour atteindre ce haut plateau, il faut emprunter les galeries séculaires du Repaire des Grumegueules, gardées par des furbolgs indemnes de corruption qui surveillent de près chaque voyageur venant de Gangrebois ou de Reflet-de-Lune. Au centre de la vallée se dresse Long-guet, un comptoir marchand florissant géré par le Cartel Gentepression. Les gobelins y accueillent les aventuriers de l'Alliance comme de la Horde avec des registres grands ouverts, offrant un refuge indispensable d'ingénierie, de commerce et de feux chaleureux face aux morsures du gel montagnard."},{t="Vieux fantômes et drakes bleus",b="Des siècles avant l'apparition des colonies modernes, d'anciens elfes bâtirent la cité lacustre de Kel'Theril. Après que des sorciers bien-nés téméraires eurent brisé le maudit Cristal de Zin-Malor, la folie s'empara d'eux, abandonnant jusqu'à ce jour des spectres tourmentés errer parmi les piliers en ruine et les eaux gelées. Plus au sud s'élèvent les hauteurs caverneuses de Mazthoril, le bastion traditionnel du Vol bleu en Kalimdor. Là, la couvée du Tisse-sort Malygos, sous la supervision de la matrone protectrice Haleh, surveille les courants arcaniques et combat les menaces locales."},{t="L'ombre menaçante de la gorge",b="La sérénité du Berceau-de-l’Hiver est brutalement rompue à sa frontière la plus méridionale, dans la gorge du Sombre murmure. Là, des forces démoniaques d'élite, vestiges des légions de la Troisième guerre, arpentent des canyons escarpés bloquant les voies d'accès vers le sommet du mont Hyjal. Pendant ce projet, les furbolgs Tombeneige indigènes ont succombé à de funestes corruptions, incitant des chercheurs indépendants tels que Donova Antreneige à enquêter sur cette souillure envahissante avant que la faune de la vallée tout entière ne soit dévorée."}},faq={{q="Comment se rendre au Berceau-de-l'Hiver ?",a="Les voyageurs doivent traverser le Repaire des Grumegueules, un réseau souterrain de galeries situé au nord-est de Gangrebois. Pour franchir ces grottes en paix, il faut gagner la confiance des furbolgs grumegueules indigènes, qui attaqueront tout intrus jugé hostile. Une fois la sortie orientale passée, les pentes enneigées du Berceau-de-l’Hiver s'ouvrent immédiatement devant vous.",al={"aller au berceau-de-l'hiver","comment entrer au berceau-de-l'hiver","entree du berceau-de-l'hiver","tunnel des grumegueules berceau-de-l'hiver"}},{q="Qui dirige la ville de Long-guet ?",a="Long-guet est gérée par le Cartel Gentepression, le conglomérat marchand gobelin. En raison de la stricte recherche du profit et de la neutralité de ces gobelins, les voyageurs de la Horde et de l'Alliance peuvent accéder à ses maîtres de vol, ses marchands de réparation, ses coffres de banque et ses marchandises, à condition de ne pas troubler la paix dans l'enceinte de la ville.",al={"qui controle long-guet","faction de long-guet","long-guet est-il neutre"}},{q="Que sont les fantômes qui hantent le lac Kel'Theril ?",a="Ce sont les esprits des Elfes de la nuit bien-nés qui peuplaient l'antique cité de Kel'Theril il y a dix mille ans. Lorsque leurs sorciers manipulèrent le Cristal de Zin-Malor dérobé, sa destruction déchaîna une malédiction catastrophique. Des expéditions ultérieures de hauts-elfes menées des siècles plus tard furent de la même manière frappées de folie, condamnées à hanter les ruines gelées aux côtés de leurs ancêtres.",al={"fantomes du lac kel'theril","esprits des ruines de kel'theril","qui est a kel'theril"}},{q="Pourquoi les furbolgs Tombeneige sont-ils agressifs ?",a="Les furbolgs Tombeneige ont succombé à une corruption contre-nature galopante qui a plongé leur clan dans une hostilité forcenée. Tandis que les Grumegueules voisins s'accrochent à leur raison, les Tombeneige sont tombés sous de sombres influences, incitant des chercheurs comme Donova Antreneige à étudier leur souillure et à purger leurs campements.",al={"pourquoi les tombeneige sont agressifs","corruption de la tribu tombeneige","donova antreneige furbolgs"}},{q="Que vit à l'intérieur de Mazthoril ?",a="Mazthoril est le perchoir principal et le sanctuaire du Vol draconique bleu sur Kalimdor. Au plus profond de ses aiguilles caverneuses, des draconidiens, des dragonnets d'élite et de vénérables drakes gardent de puissantes reliques draconiques ainsi que des secrets arcaniques sous l'œil vigilant de Haleh, consorte de l'Aspect Malygos.",al={"dragons de mazthoril","qu'est-ce que mazthoril","dragons bleus au berceau-de-l'hiver"}},{q="Qu'est-ce que la gorge du Sombre murmure ?",a="La gorge du Sombre murmure est un canyon périlleux situé aux confins méridionaux de la vallée, occupé par de puissants démons d'élite subsistant de la Troisième guerre. Il forme un périmètre lourdement gardé le long des sentiers ardus menant aux hauteurs du mont Hyjal.",al={"demons de la gorge du sombre murmure","que trouve-t-on dans la gorge du sombre murmure","porte d'hyjal berceau-de-l'hiver"}},{q="Peut-on dresser ou apprivoiser des sabres-de-givre ici ?",a="Au roc des Sabres-de-Givre, situé à l'extrême nord de la vallée, l'Elfe de la nuit Rivern Givrevent s'occupe des fauves blancs indigènes. Les aventuriers qui l'aident à rassembler des provisions et à protéger la harde peuvent se montrer dignes d'apprendre les secrets nécessaires à l'élevage et à la monte d'un sabre-de-givre.",al={"monture sabre-de-givre","rivern givrevent sabre-de-givre","comment obtenir un sabre-de-givre"}}},fp="12,328,26.408.0,23.361.0,26.385.0,31.374.0,29.250.0,30.220.0,45.324.0,43.293.0,28.244.0,26.191.0,39.225.0"}
P.entries["zone:zephras"] = {n="Île de Zéphras",s="L'île de Zéphras est une île volante suspendue au sein du Mur-Céleste, le plan élémentaire de l'Air. Elle sert de foyer ancestral et de point de départ aux Célestes, dont la société fait aujourd'hui face à une crise existentielle alors que la magie maintenant l'île s'érode peu à peu. Tout contact étant rompu avec les royaumes célestes voisins, ses habitants luttent contre l'effondrement élémentaire et l'arrivée de réfugiés.",h="L'île de Zéphras est une île volante suspendue au sein du Mur-Céleste, le plan élémentaire de l'Air.",kw={"aéronefs","anvilas","plan élémentaire","siroccas","célestes","mur-céleste","valanaar","pierres de vent","zéphras"},ang={["class:Shaman"]="Existant directement au sein du plan élémentaire de l'Air, l'île de Zéphras illustre ce qu'il advient des terres élémentaires lorsque les esprits maintenant leur équilibre disparaissent soudainement.",["race:Skyborne"]="L'île de Zéphras est votre foyer ancestral et votre point de départ, bien que sa beauté persistante dissimule une crise urgente d'effondrement de son terrain et d'extinction de sa puissance élémentaire."},sec={{t="Un royaume dans les airs",b="L'île de Zéphras est une masse terrestre isolée qui dérive dans les vents sans fin du Mur-Céleste. Pendant des générations, les Célestes y ont vécu aux côtés d'élémentaires d'air indigènes qui aidaient à préserver les courants magiques maintenant l'île en lévitation. Cependant, il y a plusieurs siècles, ces gardiens élémentaires ont entièrement disparu. Privés de leur présence et de leur tutelle, les enchantements latents qui soutiennent la terre ont lentement commencé à faillir, provoquant la progressive fracturation et la déstabilisation de Zéphras."},{t="Horizons rompus",b="Zéphras n'était pas le seul sanctuaire habité par les Célestes au sein du plan élémentaire. Des îles sœurs connues sous les noms d'Anvilas et Siroccas dérivaient également à travers le Mur-Céleste, mais les communications avec elles ont cessé après la disparition des élémentaires. Récemment, des réfugiés venus de ces terres voisines en ruine sont parvenus à atteindre Zéphras en quête de sécurité, apportant de sinistres nouvelles : les autres îles se désintègrent purement et simplement sous leurs pieds."},{t="Le seuil d'Azeroth",b="Face au lent déclin de leur propre terre, les Célestes de Zéphras ont commencé à regarder au-delà des frontières du Mur-Céleste, vers Azeroth. Depuis les docks célestes de Valanaar, des aéronefs s'aventurent désormais au dehors pour établir de rares lignes de survie vers le royaume des mortels. Ces voyages relient directement le domaine aérien à divers points d'Azeroth, notamment les abords de Dalaran dans les montagnes d'Alterac et le plateau de Guette-ciel en Mulgore."}},faq={{q="Où se situe l'île de Zéphras ?",a="L'île de Zéphras est située à l'intérieur du Mur-Céleste, le plan élémentaire de l'Air, plutôt qu'à la surface d'Azeroth. Elle flotte au milieu des nuages perpétuels et des courants venteux de ce domaine éthéré.",al={"emplacement île de zéphras","où se trouve zéphras","sur quel plan se trouve zéphras"}},{q="Pourquoi l'île de Zéphras s'effondre-t-elle ?",a="L'île dépendait de la présence d'élémentaires d'air indigènes qui coexistaient jadis avec les Célestes. Il y a plusieurs siècles, ces élémentaires ont disparu, laissant les fondations magiques qui ancrent et préservent la terre flottante s'affaiblir et se dégrader lentement avec le temps.",al={"pourquoi zéphras s'effondre","destruction île de zéphras","île mourante"}},{q="Que sont Anvilas et Siroccas ?",a="Ce sont des îles flottantes voisines dans le Mur-Céleste, également peuplées par les Célestes. L'île de Zéphras a perdu tout contact avec elles lors de la disparition des élémentaires, et des réfugiés fuyant le désastre rapportent désormais qu'Anvilas comme Siroccas s'effondrent dans le néant.",al={"anvilas","siroccas","autres îles célestes"}},{q="Comment voyage-t-on entre l'île de Zéphras et Azeroth ?",a="Les Célestes exploitent des docks célestes dans la colonie de Valanaar. Des aéronefs s'élancent depuis ces quais à travers la frontière planaire vers Azeroth, atterrissant près de Dalaran dans les montagnes d'Alterac et au plateau de Guette-ciel en Mulgore.",al={"comment quitter zéphras","aéronefs de zéphras","voyage vers azeroth"}},{q="Qui sont les Célestes ?",a="Les Célestes sont les habitants qui ont élu domicile sur l'île de Zéphras et ses royaumes célestes frères. Établis dans le Mur-Céleste depuis des générations, ils font désormais face à la lente destruction de leur patrie volante à mesure que s'estompe la magie qui la soutient.",al={"race des célestes","qui vit sur zéphras"}},{q="Qui vit sur l'île de Zéphras en dehors des Célestes ?",a="En dehors des villages paisibles et des réfugiés de passage, l'île est troublée par des bandits locaux, des noctegriffes cavernicoles et des bêtes qui peuplent des lieux comme la tanière des criailleuses et la caverne de la Noctegriffe.",al={"habitants de zéphras","ennemis sur zéphras"}}},fx={["1fd88046"]={q="Qu'est-ce que l'Île de Zéphras ?",a="L'Île de Zéphras est une vaste masse terrestre flottante située au sein du Mur-Céleste, le plan élémentaire de l'Air. Il y a des millénaires, des exilés elfes de la nuit fuyant la persécution à Eldre'Thalas ont passé un accord avec des esprits du vent indigènes, qui ont soulevé l'île dans les cieux pour les protéger. Elle sert de sanctuaire ancestral à leurs descendants, les Skyborne.",al={"qu'est-ce que zéphras","à propos de l'île de zéphras","infos sur l'île de zéphras"}},["7ea7c85c"]={q="Que s'est-il passé sur l'Île de Zéphras ?",a="L'Île de Zéphras a été élevée dans le Mur-Céleste après que des ancêtres hauts-elfes ont rompu avec le règne sanglant du prince Tortheldrin à Eldre'Thalas. Les Skyborne ont vécu en harmonie avec les élémentaires de l'air pendant des milliers d'années, mais il y a des siècles, ces protecteurs élémentaires ont disparu sans explication. Sans leur magie continue, les pylônes ancrant l'île ont commencé à se dégrader, et des réfugiés venant des îles effondrées voisines se sont enfuis ici tandis que des factions internes se disputent des ressources en diminution.",al={"histoire de zéphras","que s'est-il passé ici zéphras","lore de zéphras"}},["70a3c6ae"]={q="L'Île de Zéphras est-elle dangereuse ?",a="Oui. Au-delà de la menace physique imminente de l'île elle-même qui se déstabilise et chute du ciel, la disparition des protecteurs élémentaires a rendu la terre chaotique. Des camps de bandits, des repaires de faune hostile et des frictions politiques volatiles entre l'Ordre suprême, les Sculpte-vents et les Al'Aketh rendent les voyages en dehors des colonies fortifiées périlleux.",al={"zéphras est-elle dangereuse","menaces de zéphras","dangers sur zéphras"}},b4875d06={q="Où se situe l'île par rapport au reste d'Azeroth ?",a="L'Île de Zéphras ne repose pas sur la surface d'Azeroth ; elle dérive au sein du Mur-Céleste, un domaine dimensionnel séparé façonné par les forgés par les titans pour contenir les élémentaires de l'air chaotiques. Les seules connexions physiques entre l'île et le monde mortel en contrebas sont des dirigeables spécialisés qui accostent à Valanaar et traversent la frontière vers des points comme Dalaran et Mulgore.",al={"où est zéphras par rapport à azeroth","zéphras est-elle en azeroth","emplacement de zéphras par rapport à azeroth"}},["2c89f95d"]={q="Qui sont les Al'Aketh ?",a="Les Al'Aketh sont l'une des factions rivales luttant pour la domination sur l'Île de Zéphras aux côtés de l'Ordre suprême et des Sculpte-vents. Alors que les pylônes ancrant l'île faiblissent et que la survie devient désespérée, les Al'Aketh rivalisent activement pour la suprématie et le contrôle des ressources mystiques restantes de l'île.",al={"que sont les alaketh","faction al'aketh","qui sont les alaketh"}},["6e14d755"]={q="Vais-je quitter l'île un jour ?",a="Oui. Bien que l'Île de Zéphras serve de foyer et de terrain d'entraînement initial, des dirigeables partent des quais aériens de Valanaar à travers des failles planaires vers le continent d'Azeroth, se connectant directement à Dalaran dans les Montagnes d’Alterac et au Plateau de Guette-ciel à Mulgore.",al={"vais-je quitter zéphras","quitter l'île de zéphras","pouvons-nous aller en azeroth"}},["19470e71"]={q="Comment suis-je arrivé sur l'Île de Zéphras ?",a="Vous êtes né parmi les Skyborne, les shen'dorei qui habitent ce havre flottant haut dans le Mur-Céleste, le plan élémentaire de l'Air. Il y a des millénaires, vos ancêtres ont fui la purge du prince Tortheldrin à Eldre'Thalas et ont passé un pacte avec des esprits du vent qui ont élevé ce sanctuaire dans les cieux. Alors que d'autres îles sœurs comme Anvilas et Siroccas s'effritent ou deviennent inaccessibles, l'Île de Zéphras a été votre foyer depuis le début. Vous commencez votre voyage ici parmi les vôtres.",al={"comment suis-je arrivé ici","comment ai-je atteint l'île de zéphras","pourquoi me suis-je réveillé ici","d'où viens-je"}},["5dae6f41"]={q="Que suis-je censé faire sur l'Île de Zéphras ?",a="Votre foyer s'effondre sous vos pieds. Il y a des siècles, les bienveillants élémentaires de l'air ont disparu, et les pylônes arcaniques qui maintiennent l'Île de Zéphras ensemble perdent leur pouvoir. Des réfugiés affluent depuis les îles extérieures qui s'effondrent tandis que des factions rivales, dont l'Ordre suprême, les Sculpte-vents et les Al'Aketh, se disputent ce qui reste. Vous devez aider votre peuple, apaiser les menaces internes et les bêtes sauvages, aider à stabiliser les magies défaillantes et, finalement, chercher un passage vers Azeroth avant que l'île ne tombe.",al={"que suis-je censé faire ici","quel est mon objectif ici","que fais-je sur l'île de zéphras","pourquoi suis-je ici"}}},fp="12,263,13.353.0,16.350.0,20.265.0,30.156.0,34.190.0,30.197.0,54.178.0,21.180.0,47.152.0"}
